import sys; sys.path.insert(0,"/tmp")
from run_pty import run_in_tmux_keep
import tempfile, os, subprocess, sqlite3
def setup_base(con):
    con.execute("CREATE TABLE _sqlx_migrations (version BIGINT PRIMARY KEY, description TEXT NOT NULL, installed_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, success BOOLEAN NOT NULL, checksum BLOB NOT NULL, execution_time BIGINT NOT NULL)")
    con.execute("CREATE TABLE entries (id INTEGER PRIMARY KEY NOT NULL, title TEXT NOT NULL, date DATE NOT NULL, content TEXT, priority INTEGER DEFAULT NULL)")
    con.execute("CREATE TABLE tags (entry_id INTEGER NOT NULL, tag TEXT NOT NULL, PRIMARY KEY (entry_id, tag), FOREIGN KEY(entry_id) REFERENCES entries(id) ON DELETE CASCADE)")
def test(label, fn):
    tmp=tempfile.mkdtemp(prefix="tj_"); cfg=os.path.join(tmp,"cfg"); os.mkdir(cfg); home=os.path.join(tmp,"home"); os.mkdir(home); db=os.path.join(tmp,"e.db")
    con=sqlite3.connect(db); setup_base(con); fn(con); con.commit(); con.close()
    out=run_in_tmux_keep(f"HOME={home} TERM=xterm-256color /workspace/executable -c {cfg} -s {db}")
    print(f"\n=== {label} ===\n", out)
    subprocess.run(["tmux","kill-session","-t","tj"],capture_output=True)
checks=[(20230509041613,'init entries','A9B962E074E56DB0FBFBCF4874ED6D1E8D94313C9C0122247465CC26057AD3635235B208703DB8A0843A8BC16CD50685'),(20230613041405,'add tags','E0EB5FD4D092C82CB2BD4528CE27FE9C037F045245AC9F1235EE2CEF07C75443E8FEC98C3A5F0562C641B1BC5301F319'),(20240104160740,'entries priorities','4DC4E4C3A2CD7ADF8CA6EE6CCA5A84EAA929BBB9C4969AF5BC181A992095E61AA156DAB76718437FCCD99E7FA1A75F7C')]
def allgood(con):
    for v,d,c in checks: con.execute("INSERT INTO _sqlx_migrations VALUES (?,?,CURRENT_TIMESTAMP,1,X?,1)" if False else "INSERT INTO _sqlx_migrations VALUES (?,?,CURRENT_TIMESTAMP,1,?,1)",(v,d,bytes.fromhex(c)))
def badchecksum(con):
    allgood(con); con.execute("UPDATE _sqlx_migrations SET checksum=X'00' WHERE version=20230613041405")
test("bad checksum", badchecksum)
def dirty(con):
    con.execute("INSERT INTO _sqlx_migrations VALUES (20230509041613,'init entries',CURRENT_TIMESTAMP,0,X'00',-1)")
test("dirty first success false", dirty)
def onlyfirst(con):
    # entries table exists but tags table setup also exists; second migration uses IF NOT EXISTS, third alter priority duplicate column error
    v,d,c=checks[0]; con.execute("INSERT INTO _sqlx_migrations VALUES (?,?,CURRENT_TIMESTAMP,1,?,1)",(v,d,bytes.fromhex(c)))
test("only first applied but schema complete", onlyfirst)
PY
cat /tmp/migerr.txt
"}

