use anyhow::{anyhow, Result};
use serde::{Deserialize, Deserializer, Serialize};
use std::{
    env,
    fs,
    path::{Component, Path, PathBuf},
};

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum BackendType {
    Json,
    Sqlite,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DatumVisibility {
    Show,
    Hide,
    EmptyLine,
}

fn default_scroll_per_page() -> usize { 5 }
fn default_history_limit() -> usize { 10 }
fn default_colored_tags() -> bool { true }
fn default_datum_visibility() -> DatumVisibility { DatumVisibility::Show }
fn default_backend_type() -> BackendType { BackendType::Sqlite }
pub fn default_app_state_dir() -> PathBuf {
    dirs::state_dir()
        .unwrap_or_default()
        .join("tui-journal")
