    pub json_backend: JsonBackend,
    #[serde(default)]
    pub sqlite_backend: SqliteBackend,
}

impl Default for Settings {
    fn default() -> Self {
        Self {
            backend_type: default_backend_type(),
            scroll_per_page: default_scroll_per_page(),
            sync_os_clipboard: false,
            history_limit: default_history_limit(),
            colored_tags: default_colored_tags(),
            datum_visibility: default_datum_visibility(),
            app_state_dir: default_app_state_dir(),
            export: ExportSettings::default(),
            external_editor: ExternalEditorSettings::default(),
            json_backend: JsonBackend::default(),
            sqlite_backend: SqliteBackend::default(),
        }
    }
}

pub fn default_config_dir() -> PathBuf {
    dirs::config_dir().unwrap_or_default().join("tui-journal")
}

pub fn default_cache_log_path() -> PathBuf {
    dirs::cache_dir()
        .unwrap_or_default()
        .join("tui-journal")
        .join("tui-journal.log")
}

pub fn absolutize_path(path: &Path) -> PathBuf {
    let joined = if path.is_absolute() {
        path.to_path_buf()
    } else {
        env::current_dir()
            .unwrap_or_else(|_| PathBuf::from("."))
            .join(path)
    };
    normalize_path(&joined)
}

pub fn normalize_path(path: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for comp in path.components() {
        match comp {
            Component::CurDir => {}
            Component::ParentDir => {
                // pop a normal component if possible; keep leading .. on relative paths
                let last_is_normal = matches!(out.components().last(), Some(Component::Normal(_)));
                if last_is_normal {
                    out.pop();
                } else if !out.has_root() {
                    out.push("..");
                }
            }
            Component::RootDir => out.push(Path::new("/")),
            Component::Prefix(p) => out.push(p.as_os_str()),
            Component::Normal(c) => out.push(c),
        }
    }
    if out.as_os_str().is_empty() {
        if path.is_absolute() {
            PathBuf::from("/")
        } else {
            PathBuf::from(".")
        }
    } else {
        out
    }
}

fn ensure_parent_dir(path: &Path) -> Result<()> {
    if let Some(parent) = path.parent() {
        if !parent.as_os_str().is_empty() {
            fs::create_dir_all(parent)?;
        }
    }
    Ok(())
}

impl Settings {
    pub fn load(
        custom_config: Option<PathBuf>,
        json_path: Option<PathBuf>,
        sqlite_path: Option<PathBuf>,
        backend: Option<BackendType>,
    ) -> Result<Self> {
        let config_path = resolve_config_path(custom_config)?;
        let mut settings: Settings = if config_path.exists() {
            let content = fs::read_to_string(&config_path).map_err(|err| {
                anyhow!("Failed to load configuration file. Error infos: {}", err)
            })?;
            toml::from_str(&content).map_err(|err| {
                anyhow!("Failed to read configuration file. Error infos: {}", err)
            })?
        } else {
            Settings::default()
        };

        if let Some(path) = json_path {
            let absolute = absolutize_path(&path);
            ensure_parent_dir(&absolute)?;
            settings.json_backend.file_path = absolute;
            settings.backend_type = BackendType::Json;
        }
        if let Some(path) = sqlite_path {
            let absolute = absolutize_path(&path);
            ensure_parent_dir(&absolute)?;
            settings.sqlite_backend.file_path = absolute;
            settings.backend_type = BackendType::Sqlite;
        }
        if let Some(backend) = backend {
            settings.backend_type = backend;
        }
        Ok(settings)
    }

    pub fn to_toml_string(&self) -> Result<String> {
        Ok(toml::to_string(self)?)
    }
}

fn resolve_config_path(custom_config: Option<PathBuf>) -> Result<PathBuf> {
    if let Some(path) = custom_config {
        if !path.exists() {
            return Err(anyhow!(
                "Provided custom directory doesn't exit. Path: {}",
                path.display()
            ));
        }
        if path.is_dir() {
            Ok(path.join("config.toml"))
        } else {
            Ok(path)
        }
    } else {
        Ok(default_config_dir().join("config.toml"))
    }
}

pub fn themes_path(custom_config: &Option<PathBuf>) -> PathBuf {
    if let Some(dir) = custom_config {
        if dir.is_dir() {
            return dir.join("themes.toml");
        }
        eprintln!("INFO: Custom config directory is ignored in themese because it's not a directory.");
    }
    default_config_dir().join("themes.toml")
}
RS
"}

