use anyhow::{Context, Result};
use ratatui::style::{Color, Modifier, Style as RatStyle};
use serde::{Deserialize, Deserializer, Serialize, Serializer};
use std::{fs, path::{Path, PathBuf}, str::FromStr};

use crate::settings::themes_path;

pub const DEFAULT_THEMES_TOML: &str = include_str!("default_themes.toml");

// ---------- Colors ----------
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Colors(pub Color);

#[derive(Deserialize)]
#[serde(untagged)]
enum ColorFormat {
    Named(String),
}

impl<'de> Deserialize<'de> for Colors {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where D: Deserializer<'de> {
        // Reproduce the reference error messages for unsupported shapes.
        let fmt = ColorFormat::deserialize(deserializer)
            .map_err(|err| serde::de::Error::custom(format!("Failed to parse Colors: {}", err)))?;
        let ColorFormat::Named(text) = fmt;
        parse_color_str(&text)
            .map(Colors)
            .map_err(|_| serde::de::Error::custom("Failed to parse Colors"))
    }
}

