// ---------- Colors ----------
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Colors(pub Color);

#[derive(Deserialize)]
#[serde(untagged)]
enum ColorFormat {
    Named(String),
}

impl<'de> Deserialize<'de> for Colors {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where D: Deserializer<'de> {
        // Reproduce the reference error messages for unsupported shapes.
        let fmt = ColorFormat::deserialize(deserializer)
            .map_err(|err| serde::de::Error::custom(format!("Failed to parse Colors: {}", err)))?;
        let ColorFormat::Named(text) = fmt;
        parse_color_str(&text)
            .map(Colors)
            .map_err(|_| serde::de::Error::custom("Failed to parse Colors"))
    }
}

fn parse_color_str(text: &str) -> Result<Color, String> {
    // Ratatui's Color FromStr handles named colours, indexed numbers and
    // #RRGGBB hex.  It trims/normalises names with spaces/dashes/underscores.
    Color::from_str(text).map_err(|e| e.to_string())
}

impl Serialize for Colors {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where S: Serializer {
        serializer.serialize_str(&color_to_string(self.0))
    }
}

pub fn color_to_string(color: Color) -> String {
    match color {
        Color::Reset => "Reset".to_owned(),
        Color::Black => "Black".to_owned(),
        Color::Red => "Red".to_owned(),
        Color::Green => "Green".to_owned(),
        Color::Yellow => "Yellow".to_owned(),
        Color::Blue => "Blue".to_owned(),
        Color::Magenta => "Magenta".to_owned(),
        Color::Cyan => "Cyan".to_owned(),
        Color::Gray => "Gray".to_owned(),
        Color::DarkGray => "DarkGray".to_owned(),
        Color::LightRed => "LightRed".to_owned(),
        Color::LightGreen => "LightGreen".to_owned(),
        Color::LightYellow => "LightYellow".to_owned(),
        Color::LightBlue => "LightBlue".to_owned(),
        Color::LightMagenta => "LightMagenta".to_owned(),
        Color::LightCyan => "LightCyan".to_owned(),
        Color::White => "White".to_owned(),
        Color::Rgb(r, g, b) => format!("#{r:02X}{g:02X}{b:02X}"),
        Color::Indexed(i) => i.to_string(),
    }
}

// ---------- Modifiers ----------
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Modifiers(pub Modifier);

impl Default for Modifiers {
    fn default() -> Self { Self(Modifier::empty()) }
}

impl<'de> Deserialize<'de> for Modifiers {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where D: Deserializer<'de> {
        struct V;
        impl<'de> serde::de::Visitor<'de> for V {
            type Value = Modifiers;
            fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
                f.write_str("a string value of `|` separated flags")
            }
            fn visit_str<E>(self, value: &str) -> Result<Self::Value, E>
            where E: serde::de::Error {
                parse_modifiers(value).map(Modifiers).map_err(E::custom)
            }
            fn visit_string<E>(self, value: String) -> Result<Self::Value, E>
            where E: serde::de::Error {
                parse_modifiers(&value).map(Modifiers).map_err(E::custom)
            }
        }
        deserializer.deserialize_string(V)
    }
}

fn parse_modifiers(text: &str) -> Result<Modifier, String> {
    let mut out = Modifier::empty();
    if text.trim().is_empty() {
        return Ok(out);
    }
    for raw in text.split('|') {
        let token = raw.trim();
        let flag = match token {
            "BOLD" => Modifier::BOLD,
            "DIM" => Modifier::DIM,
            "ITALIC" => Modifier::ITALIC,
            "UNDERLINED" => Modifier::UNDERLINED,
            "SLOW_BLINK" => Modifier::SLOW_BLINK,
            "RAPID_BLINK" => Modifier::RAPID_BLINK,
            "REVERSED" => Modifier::REVERSED,
            "HIDDEN" => Modifier::HIDDEN,
            "CROSSED_OUT" => Modifier::CROSSED_OUT,
            other => return Err(format!("unrecognized named flag `{other}`")),
        };
        out |= flag;
    }
    Ok(out)
}

fn modifiers_to_string(m: Modifier) -> String {
    let mut parts = Vec::new();
    if m.contains(Modifier::BOLD) { parts.push("BOLD"); }
    if m.contains(Modifier::DIM) { parts.push("DIM"); }
    if m.contains(Modifier::ITALIC) { parts.push("ITALIC"); }
    if m.contains(Modifier::UNDERLINED) { parts.push("UNDERLINED"); }
    if m.contains(Modifier::SLOW_BLINK) { parts.push("SLOW_BLINK"); }
    if m.contains(Modifier::RAPID_BLINK) { parts.push("RAPID_BLINK"); }
    if m.contains(Modifier::REVERSED) { parts.push("REVERSED"); }
    if m.contains(Modifier::HIDDEN) { parts.push("HIDDEN"); }
    if m.contains(Modifier::CROSSED_OUT) { parts.push("CROSSED_OUT"); }
    parts.join(" | ")
}

impl Serialize for Modifiers {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where S: Serializer {
        serializer.serialize_str(&modifiers_to_string(self.0))
    }
}

// ---------- Style (theme level, name is intentional for toml errors) ----------
#[derive(Debug, Clone, Copy, Deserialize, Serialize)]
#[serde(default)]
pub struct Style {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub fg: Option<Colors>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bg: Option<Colors>,
    #[serde(default)]
    pub modifiers: Modifiers,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub underline_color: Option<Colors>,
}

impl Default for Style {
    fn default() -> Self {
        Self { fg: None, bg: None, modifiers: Modifiers::default(), underline_color: None }
    }
}

impl Style {
    pub fn new(fg: Option<Color>, bg: Option<Color>, modifiers: Modifier) -> Self {
        Self {
            fg: fg.map(Colors),
            bg: bg.map(Colors),
            modifiers: Modifiers(modifiers),
            underline_color: None,
        }
    }
    pub fn to_rat(&self) -> RatStyle {
        let mut s = RatStyle::new();
        if let Some(c) = self.fg { s = s.fg(c.0); }
        if let Some(c) = self.bg { s = s.bg(c.0); }
        if let Some(c) = self.underline_color { s = s.underline_color(c.0); }
        s = s.add_modifier(self.modifiers.0);
        s
    }
}

fn st(fg: Color, modifiers: Modifier) -> Style { Style::new(Some(fg), None, modifiers) }
fn stb(fg: Color, bg: Color, modifiers: Modifier) -> Style { Style::new(Some(fg), Some(bg), modifiers) }

