#[derive(Debug, Clone, Default, Deserialize, Serialize)]
#[serde(default)]
pub struct AppStyles {
    pub general: GeneralStyles,
    pub journals_list: JournalsListStyles,
    pub editor: EditorStyles,
    pub msgbox: MsgBoxColors,
}
// Aliases matching probable upstream names in serde errors come from the
// concrete struct names above; the root type name is not surfaced by toml
// for a top-level table.
pub type Styles = AppStyles;

pub fn load_styles(custom_config: &Option<PathBuf>) -> Result<AppStyles> {
    let path = themes_path(custom_config);
    load_styles_from_path(&path)
        .context("Error while retrieving app styles")
}

fn load_styles_from_path(path: &Path) -> Result<AppStyles> {
    if !path.exists() {
        return Ok(AppStyles::default());
    }
    let content = fs::read_to_string(path).with_context(|| {
        format!("Loading themes file content failed. Path: {}", path.display())
    })?;
    let styles: AppStyles = toml::from_str(&content).with_context(|| {
        format!(
            "Error while desrializing toml text to styles. File path: {}",
            path.display()
        )
    })?;
    Ok(styles)
}

pub fn write_default_themes(path: &Path) -> Result<()> {
    // Caller performs existence check with its own message.
    fs::write(path, DEFAULT_THEMES_TOML).context("Error while writing default themes to file")
}
