/// Parse a date/time value as sqlx's SQLite chrono decoder would accept it.
/// Returns the decode error message (without the column prefix) on failure.
pub fn parse_sqlite_datetime(value: &str) -> std::result::Result<DateTime<Utc>, String> {
    // RFC3339 with offset (including 'Z')
    if let Ok(dt) = DateTime::parse_from_rfc3339(value) {
        return Ok(dt.with_timezone(&Utc));
    }
    // Naive date-times treated as UTC: "%Y-%m-%dT%H:%M:%S%.f" and with space.
    let fmts = [
        "%Y-%m-%dT%H:%M:%S%.f",
        "%Y-%m-%d %H:%M:%S%.f",
        "%Y-%m-%dT%H:%M:%S",
        "%Y-%m-%d %H:%M:%S",
    ];
    for fmt in fmts {
        if let Ok(ndt) = chrono::NaiveDateTime::parse_from_str(value, fmt) {
            return Ok(DateTime::from_naive_utc_and_offset(ndt, Utc));
        }
    }
    Err(format!("invalid datetime: {}", value))
}

pub fn sql_decode_error(column: &str, msg: &str) -> anyhow::Error {
    anyhow!("error occurred while decoding column \"{}\": {}", column, msg)
}
