pub struct JsonDataProvider {
    pub file_path: PathBuf,
}

impl JsonDataProvider {
    pub fn new(file_path: PathBuf) -> Self { Self { file_path } }

    fn load_entries_from_file(&self) -> Result<Vec<Entry>> {
        if !self.file_path.exists() {
            // Reading a missing file beneath a missing parent also yields
            // NotFound at open time; matching the reference, any "does not
            // exist" situation is an empty list.  Other I/O errors (a parent
            // component being a regular file, a directory in place of the
            // file, permissions) are surfaced.
            match fs::read_to_string(&self.file_path) {
                Ok(content) => return parse_entries(&content),
                Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(Vec::new()),
                Err(err) => return Err(err.into()),
            }
        }
        let content = fs::read_to_string(&self.file_path)?;
        if content.is_empty() {
            return Ok(Vec::new());
        }
        parse_entries(&content)
    }

    fn write_entries(&self, entries: &[Entry]) -> Result<()> {
        if let Some(parent) = self.file_path.parent() {
            if !parent.as_os_str().is_empty() {
                fs::create_dir_all(parent)?;
            }
        }
        let text = serde_json::to_string(entries)?;
        fs::write(&self.file_path, text)?;
        Ok(())
    }
}

fn parse_entries(content: &str) -> Result<Vec<Entry>> {
    if content.is_empty() {
        return Ok(Vec::new());
    }
    let entries: Vec<Entry> = serde_json::from_str(content)
        .map_err(|_| anyhow!("Error while parsing entries json data"))?;
