const COL_INTEGER: c_int = 1;
const COL_FLOAT: c_int = 2;
const COL_TEXT: c_int = 3;
const COL_BLOB: c_int = 4;
const COL_NULL: c_int = 5;

#[derive(Debug)]
struct DbError {
    code: i32,
    message: String,
}
impl std::fmt::Display for DbError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "(code: {}) {}", self.code, self.message)
    }
}
impl std::error::Error for DbError {}

fn sqlx_database_error(code: i32, message: String) -> anyhow::Error {
    // sqlx Error::Database displays as "error returned from database: (code: N) msg"
    // and carries the database error as its source.  Creating the chain in
    // this order reproduces anyhow's Debug rendering at the top level.
    let inner = DbError { code, message: message.clone() };
    anyhow::Error::new(inner).context(format!("error returned from database: (code: {}) {}", code, message))
}

struct Conn {
    db: *mut sqlite3,
}
// The connection is only used behind a Mutex.
unsafe impl Send for Conn {}

impl Conn {
    fn open(path: &PathBuf) -> Result<Self> {
        let cpath = CString::new(path.to_string_lossy().as_bytes())
            .map_err(|_| anyhow!("invalid path"))?;
        let mut db: *mut sqlite3 = ptr::null_mut();
        let rc = unsafe {
            sqlite3_open_v2(
                cpath.as_ptr(),
                &mut db,
                SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE | SQLITE_OPEN_FULLMUTEX,
                ptr::null(),
            )
        };
        if rc != SQLITE_OK {
            let (code, msg) = if db.is_null() {
                (rc, "out of memory".to_owned())
            } else {
                let code = unsafe { sqlite3_errcode(db) };
                let msg = unsafe { cstr_to_string(sqlite3_errmsg(db)) };
                unsafe { sqlite3_close(db) };
                (code, msg)
            };
            return Err(sqlx_database_error(code, msg));
        }
        Ok(Self { db })
    }

    fn last_error(&self) -> (i32, String) {
        unsafe {
            let code = sqlite3_errcode(self.db);
            (code, cstr_to_string(sqlite3_errmsg(self.db)))
        }
    }

    fn db_error(&self) -> anyhow::Error {
        let (code, msg) = self.last_error();
        sqlx_database_error(code, msg)
    }

    fn simple_db_error_string(&self) -> String {
        let (code, msg) = self.last_error();
        format!("error returned from database: (code: {}) {}", code, msg)
    }

    /// Execute SQL with no result rows expected (may be multiple statements).
    fn exec(&self, sql: &str) -> Result<()> {
        let mut remaining = sql;
        loop {
            let trimmed = remaining.trim();
            if trimmed.is_empty() {
                return Ok(());
            }
            let (stmt, tail_offset) = self.prepare(remaining)?;
            if stmt.is_null() {
                return Ok(());
            }
            let rc = unsafe { sqlite3_step(stmt) };
            let fin_rc = unsafe { sqlite3_finalize(stmt) };
            if rc != SQLITE_DONE && rc != SQLITE_ROW && rc != SQLITE_OK {
                return Err(self.db_error());
            }
            if fin_rc != SQLITE_OK && rc == SQLITE_DONE {
                // finalize surfaces errors of the just-run statement
                // (already handled via step's code in most cases).
            }
            if tail_offset >= remaining.len() {
                return Ok(());
            }
            remaining = &remaining[tail_offset..];
        }
    }

    fn exec_migration(&self, sql: &str) -> std::result::Result<(), String> {
        self.exec(sql).map_err(|e| {
            // For migration failures the reference renders the sqlx error
            // via Display (no chain) inside its own message.
            format!("{}", e)
        })
    }

    fn prepare(&self, sql: &str) -> Result<(*mut sqlite3_stmt, usize)> {
        let csql = CString::new(sql).map_err(|_| anyhow!("invalid sql"))?;
        let mut stmt: *mut sqlite3_stmt = ptr::null_mut();
        let mut tail: *const c_char = ptr::null();
        let rc = unsafe {
            sqlite3_prepare_v2(self.db, csql.as_ptr(), -1, &mut stmt, &mut tail)
        };
        if rc != SQLITE_OK {
            if !stmt.is_null() {
                unsafe { sqlite3_finalize(stmt) };
            }
            return Err(self.db_error());
        }
        let offset = if tail.is_null() {
            sql.len()
        } else {
            unsafe { tail.offset_from(csql.as_ptr()) as usize }
        };
        Ok((stmt, offset))
    }

    fn query(&self, sql: &str, params: &[Param]) -> Result<Vec<Vec<Value>>> {
        let (stmt, _) = self.prepare(sql)?;
        if stmt.is_null() {
            return Ok(Vec::new());
        }
        bind_params(stmt, params);
        let mut rows = Vec::new();
        loop {
            let rc = unsafe { sqlite3_step(stmt) };
            if rc == SQLITE_ROW {
                let n = unsafe { sqlite3_column_count(stmt) };
                let mut row = Vec::new();
                for i in 0..n {
                    row.push(column_value(stmt, i));
                }
                rows.push(row);
            } else if rc == SQLITE_DONE {
                break;
            } else {
                let err = self.db_error();
                unsafe { sqlite3_finalize(stmt) };
                return Err(err);
            }
        }
        unsafe { sqlite3_finalize(stmt) };
        Ok(rows)
    }

    fn execute(&self, sql: &str, params: &[Param]) -> Result<()> {
        let (stmt, _) = self.prepare(sql)?;
        if stmt.is_null() {
            return Ok(());
        }
        bind_params(stmt, params);
        let rc = unsafe { sqlite3_step(stmt) };
        if rc != SQLITE_DONE && rc != SQLITE_ROW && rc != SQLITE_OK {
            let err = self.db_error();
            unsafe { sqlite3_finalize(stmt) };
            return Err(err);
        }
        unsafe { sqlite3_finalize(stmt) };
        Ok(())
    }

    fn last_insert_rowid(&self) -> i64 {
        unsafe { sqlite3_last_insert_rowid(self.db) }
    }
}

impl Drop for Conn {
    fn drop(&mut self) {
        if !self.db.is_null() {
            unsafe { sqlite3_close(self.db) };
        }
    }
}

unsafe fn cstr_to_string(ptr_: *const c_char) -> String {
    if ptr_.is_null() {
        return String::new();
    }
    let cstr = std::ffi::CStr::from_ptr(ptr_);
    cstr.to_string_lossy().into_owned()
}

#[derive(Debug, Clone)]
enum Value {
    Null,
    Integer(i64),
    Real(f64),
    Text(String),
    Blob(Vec<u8>),
}

#[derive(Debug, Clone)]
enum Param {
    Null,
    Integer(i64),
    Text(String),
    Blob(Vec<u8>),
}

fn bind_params(stmt: *mut sqlite3_stmt, params: &[Param]) {
    for (i, param) in params.iter().enumerate() {
        let idx = (i + 1) as c_int;
        unsafe {
            match param {
                Param::Null => { sqlite3_bind_null(stmt, idx); }
                Param::Integer(v) => { sqlite3_bind_int64(stmt, idx, *v); }
                Param::Text(s) => {
                    // SQLITE_TRANSIENT: sqlite copies the text.
                    sqlite3_bind_text(stmt, idx, s.as_ptr() as *const c_char, s.len() as c_int, SQLITE_TRANSIENT);
                }
                Param::Blob(b) => {
                    sqlite3_bind_blob(stmt, idx, b.as_ptr() as *const c_void, b.len() as c_int, SQLITE_TRANSIENT);
                }
            }
        }
    }
}

fn column_value(stmt: *mut sqlite3_stmt, idx: c_int) -> Value {
    let ty = unsafe { sqlite3_column_type(stmt, idx) };
    match ty {
        COL_INTEGER => Value::Integer(unsafe { sqlite3_column_int64(stmt, idx) }),
        COL_FLOAT => {
            // sqlite3_column_double not bound; obtain via text round-trip is wrong.
            // Bind it here through a local extern to keep it faithful.
            #[link(name = "sqlite3")]
            extern "C" { fn sqlite3_column_double(stmt: *mut sqlite3_stmt, idx: c_int) -> f64; }
            Value::Real(unsafe { sqlite3_column_double(stmt, idx) })
        }
        COL_TEXT => {
            let text_ptr = unsafe { sqlite3_column_text(stmt, idx) };
            let n = unsafe { sqlite3_column_bytes(stmt, idx) } as usize;
            if text_ptr.is_null() {
                Value::Text(String::new())
            } else {
                let bytes = unsafe { std::slice::from_raw_parts(text_ptr, n) };
                Value::Text(String::from_utf8_lossy(bytes).into_owned())
            }
        }
        COL_BLOB => {
            let blob_ptr = unsafe { sqlite3_column_blob(stmt, idx) };
            let n = unsafe { sqlite3_column_bytes(stmt, idx) } as usize;
            if blob_ptr.is_null() {
                Value::Blob(Vec::new())
            } else {
                let bytes = unsafe { std::slice::from_raw_parts(blob_ptr as *const u8, n) };
                Value::Blob(bytes.to_vec())
            }
        }
        _ => Value::Null,
    }
}

