fn hex_to_bytes(hex: &str) -> Vec<u8> {
    let mut out = Vec::with_capacity(hex.len() / 2);
    let bytes = hex.as_bytes();
    let mut i = 0;
    while i + 1 < bytes.len() {
        let hi = (bytes[i] as char).to_digit(16).unwrap_or(0) as u8;
        let lo = (bytes[i + 1] as char).to_digit(16).unwrap_or(0) as u8;
        out.push((hi << 4) | lo);
        i += 2;
    }
    out
}

pub struct SqliteDataProvider {
    #[allow(dead_code)]
    pub file_path: PathBuf,
    conn: Mutex<Conn>,
}

impl SqliteDataProvider {
    pub fn new(file_path: PathBuf) -> Result<Self> {
        if let Some(parent) = file_path.parent() {
            if !parent.as_os_str().is_empty() {
                fs::create_dir_all(parent)?;
            }
        }
        log::trace!(target: "backend::sqlite", "Creating Database with the URL 'sqlite://{}'", file_path.display());
        let conn = Conn::open(&file_path)?;
        // Touch the database like a real pool would; this surfaces
        // "file is not a database" and similar errors at creation.
        conn.exec("PRAGMA journal_mode = WAL; PRAGMA foreign_keys = ON;")?;
        let provider = Self { file_path, conn: Mutex::new(conn) };
        provider.run_migrations()?;
        Ok(provider)
    }

    fn run_migrations(&self) -> Result<()> {
        let conn = self.conn.lock().unwrap();
        let migrate = |conn: &Conn| -> Result<()> {
            // sqlx migration connection switches journaling off.
            let _ = conn.exec("PRAGMA journal_mode = OFF; PRAGMA foreign_keys = ON; PRAGMA synchronous = OFF;");
            conn.exec(
                "CREATE TABLE IF NOT EXISTS _sqlx_migrations (\n    version BIGINT PRIMARY KEY,\n    description TEXT NOT NULL,\n    installed_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    success BOOLEAN NOT NULL,\n    checksum BLOB NOT NULL,\n    execution_time BIGINT NOT NULL\n);",
            )
            .map_err(|e| anyhow!("Error while applying migrations on database: Error info {}", migration_error_text(&e)))?;
            // Dirty check.
            let dirty = conn
                .query("SELECT version FROM _sqlx_migrations WHERE success = false ORDER BY version LIMIT 1", &[])
                .map_err(|e| anyhow!("Error while applying migrations on database: Error info {}", migration_error_text(&e)))?;
            if let Some(row) = dirty.first() {
                if let Some(Value::Integer(v)) = row.first() {
                    return Err(anyhow!(
                        "Error while applying migrations on database: Error info migration {} is partially applied; fix and remove row from `_sqlx_migrations` table",
                        v
                    ));
                }
            }
            let applied_rows = conn
                .query("SELECT version, checksum FROM _sqlx_migrations ORDER BY version", &[])
                .map_err(|e| anyhow!("Error while applying migrations on database: Error info {}", migration_error_text(&e)))?;
            let mut applied: Vec<(i64, Vec<u8>)> = Vec::new();
            for row in &applied_rows {
                let version = match row.first() { Some(Value::Integer(v)) => *v, _ => continue };
                let checksum = match row.get(1) {
                    Some(Value::Blob(b)) => b.clone(),
                    Some(Value::Text(t)) => t.as_bytes().to_vec(),
                    _ => Vec::new(),
                };
                applied.push((version, checksum));
            }
            // Version missing has its own message in the reference.
            for (version, checksum) in &applied {
                match MIGRATIONS.iter().find(|m| m.version == *version) {
                    None => {
                        return Err(anyhow!(
                            "Database version mismatches. Error Info: migration {} was previously applied but is missing in the resolved migrations",
                            version
                        ));
                    }
                    Some(m) => {
                        if *checksum != hex_to_bytes(m.checksum_hex) {
                            return Err(anyhow!(
                                "Error while applying migrations on database: Error info migration {} was previously applied but has been modified",
                                version
                            ));
                        }
                    }
                }
            }
            let applied_versions: Vec<i64> = applied.iter().map(|(v, _)| *v).collect();
            for m in MIGRATIONS {
                if applied_versions.contains(&m.version) {
                    continue;
                }
                let started = Instant::now();
                let _ = conn.exec("BEGIN");
                let body = (|| -> std::result::Result<(), String> {
                    conn.exec_migration(m.sql)?;
                    conn.execute(
                        "INSERT INTO _sqlx_migrations ( version, description, success, checksum, execution_time ) VALUES ( ?1, ?2, TRUE, ?3, -1 )",
                        &[
                            Param::Integer(m.version),
                            Param::Text(m.description.to_owned()),
                            Param::Blob(hex_to_bytes(m.checksum_hex)),
                        ],
                    )
                    .map_err(|e| format!("{}", e))?;
                    Ok(())
                })();
                match body {
                    Ok(()) => {
                        let _ = conn.exec("COMMIT");
                    }
                    Err(msg) => {
                        let _ = conn.exec("ROLLBACK");
                        // msg already has "error returned from database: ..." form
                        // when it came from a database error.
                        let detail = if msg.starts_with("error returned from database:") {
                            msg
                        } else {
                            // anyhow Display of a context chain shows only the outer
                            // context for our DbError; reconstruct prefix if needed.
                            msg
                        };
                        return Err(anyhow!(
                            "Error while applying migrations on database: Error info while executing migration {}: {}",
                            m.version, detail
                        ));
                    }
                }
                let elapsed_ns = started.elapsed().as_nanos() as i64;
                let _ = conn.execute(
                    "UPDATE _sqlx_migrations SET execution_time = ?1 WHERE version = ?2",
                    &[Param::Integer(elapsed_ns), Param::Integer(m.version)],
                );
            }
            Ok(())
        };
        migrate(&conn)?;
        // Back to per-connection defaults for normal operations.
        let _ = conn.exec("PRAGMA foreign_keys = ON;");
        Ok(())
    }

    fn load_entries_locked(&self, conn: &Conn) -> Result<Vec<Entry>> {
        let rows = conn.query(
            "SELECT id, title, date, content, priority FROM entries",
            &[],
        )?;
        let mut entries = Vec::new();
        for row in rows {
            let id = decode_u32(row.get(0), "id", false)?;
            let title = decode_string(row.get(1), "title")?;
            let date = decode_date(row.get(2))?;
            let content = match row.get(3) {
                Some(Value::Null) | None => String::new(),
                Some(_) => decode_string(row.get(3), "content")?,
            };
            let priority = decode_opt_u32(row.get(4), "priority")?;
            let tag_rows = conn.query(
                "SELECT tag FROM tags WHERE entry_id = ?1",
                &[Param::Integer(id as i64)],
            )?;
            let mut tags = Vec::new();
            for trow in tag_rows {
                tags.push(decode_string(trow.get(0), "tag")?);
            }
            entries.push(Entry { id, date, title, content, tags, priority });
        }
        Ok(entries)
    }
}

fn migration_error_text(err: &anyhow::Error) -> String {
    // sqlx MigrateError display for execute errors is
    // "while executing migration N: ..."; other layers are handled by callers.
    // Our Conn errors already display in sqlx's database-error form.
    format!("{}", err)
}

fn sql_type_name(v: &Value) -> &'static str {
    match v {
        Value::Integer(_) => "INTEGER",
        Value::Real(_) => "REAL",
        Value::Text(_) => "TEXT",
        Value::Blob(_) => "BLOB",
        Value::Null => "NULL",
    }
}

fn decode_u32(v: Option<&Value>, column: &str, _opt: bool) -> Result<u32> {
    match v {
        Some(Value::Integer(i)) => {
            if *i < 0 || *i > u32::MAX as i64 {
                Err(sql_decode_error(column, "out of range integral type conversion attempted"))
            } else {
                Ok(*i as u32)
            }
        }
        Some(Value::Null) | None => Err(sql_decode_error(
            column,
            "unexpected null; try decoding as an `Option`",
        )),
        Some(other) => Err(sql_decode_error(
            column,
            &format!(
                "mismatched types; Rust type `u32` (as SQL type `INTEGER`) is not compatible with SQL type `{}`",
                sql_type_name(other)
            ),
        )),
    }
}

fn decode_opt_u32(v: Option<&Value>, column: &str) -> Result<Option<u32>> {
    match v {
        Some(Value::Null) | None => Ok(None),
        Some(Value::Integer(i)) => {
            if *i < 0 || *i > u32::MAX as i64 {
                Err(sql_decode_error(column, "out of range integral type conversion attempted"))
            } else {
                Ok(Some(*i as u32))
            }
        }
        Some(other) => Err(sql_decode_error(
            column,
            &format!(
                "mismatched types; Rust type `core::option::Option<u32>` (as SQL type `INTEGER`) is not compatible with SQL type `{}`",
                sql_type_name(other)
            ),
        )),
    }
}

fn decode_string(v: Option<&Value>, column: &str) -> Result<String> {
    match v {
        Some(Value::Text(s)) => Ok(s.clone()),
        Some(Value::Null) | None => Err(sql_decode_error(
            column,
            "unexpected null; try decoding as an `Option`",
        )),
        Some(other) => Err(sql_decode_error(
            column,
            &format!(
                "mismatched types; Rust type `alloc::string::String` (as SQL type `TEXT`) is not compatible with SQL type `{}`",
                sql_type_name(other)
            ),
        )),
    }
}

fn decode_date(v: Option<&Value>) -> Result<chrono::DateTime<chrono::Utc>> {
    match v {
        Some(Value::Text(s)) => parse_sqlite_datetime(s)
            .map_err(|msg| sql_decode_error("date", &msg)),
        Some(Value::Integer(i)) => {
            // sqlx decodes integer timestamps as seconds since the epoch.
            chrono::DateTime::from_timestamp(*i, 0)
                .ok_or_else(|| sql_decode_error("date", &format!("invalid datetime: {}", i)))
        }
        Some(Value::Null) | None => Err(sql_decode_error(
            "date",
            "unexpected null; try decoding as an `Option`",
        )),
        Some(other) => Err(sql_decode_error(
            "date",
            &format!(
                "mismatched types; Rust type `chrono::datetime::DateTime<chrono::offset::utc::Utc>` (as SQL type `TEXT`) is not compatible with SQL type `{}`",
                sql_type_name(other)
            ),
        )),
    }
}

impl DataProvider for SqliteDataProvider {
    fn load_all_entries(&self) -> Result<Vec<Entry>> {
        let conn = self.conn.lock().unwrap();
        self.load_entries_locked(&conn)
    }

    fn add_entry(&self, draft: EntryDraft) -> Result<Entry> {
        let conn = self.conn.lock().unwrap();
        conn.execute(
            "INSERT INTO entries (title, date, content, priority) VALUES (?1, ?2, ?3, ?4)",
            &[
                Param::Text(draft.title.clone()),
                Param::Text(date_to_sqlite_text(&draft.date)),
                Param::Text(draft.content.clone()),
                match draft.priority { Some(p) => Param::Integer(p as i64), None => Param::Null },
            ],
        )?;
        let id = conn.last_insert_rowid() as u32;
        for tag in &draft.tags {
            conn.execute(
                "INSERT INTO tags (entry_id, tag) VALUES (?1, ?2)",
                &[Param::Integer(id as i64), Param::Text(tag.clone())],
            )?;
        }
        Ok(Entry {
            id,
            date: draft.date,
            title: draft.title,
            content: draft.content,
            tags: draft.tags,
            priority: draft.priority,
        })
    }

    fn remove_entry(&self, id: u32) -> Result<()> {
        let conn = self.conn.lock().unwrap();
        // Foreign keys are ON, so tags cascade; deleting them explicitly is
        // harmless and makes behaviour independent of the pragma state.
        conn.execute("DELETE FROM tags WHERE entry_id = ?1", &[Param::Integer(id as i64)])?;
        conn.execute("DELETE FROM entries WHERE id = ?1", &[Param::Integer(id as i64)])?;
        Ok(())
    }

    fn update_entry(&self, entry: &Entry) -> Result<()> {
        let conn = self.conn.lock().unwrap();
        conn.execute(
            "UPDATE entries SET title = ?1, date = ?2, content = ?3, priority = ?4 WHERE id = ?5",
            &[
                Param::Text(entry.title.clone()),
                Param::Text(date_to_sqlite_text(&entry.date)),
                Param::Text(entry.content.clone()),
                match entry.priority { Some(p) => Param::Integer(p as i64), None => Param::Null },
                Param::Integer(entry.id as i64),
            ],
        )?;
        conn.execute("DELETE FROM tags WHERE entry_id = ?1", &[Param::Integer(entry.id as i64)])?;
        for tag in &entry.tags {
            conn.execute(
                "INSERT INTO tags (entry_id, tag) VALUES (?1, ?2)",
                &[Param::Integer(entry.id as i64), Param::Text(tag.clone())],
            )?;
        }
        Ok(())
    }

    fn assign_priority(&self, priority: u32) -> Result<()> {
        let conn = self.conn.lock().unwrap();
        conn.execute(
            "UPDATE entries SET priority = ?1 WHERE priority IS NULL",
            &[Param::Integer(priority as i64)],
        )?;
        Ok(())
    }
}
