// Minimal bind to the system libsqlite3 (the reference uses a SQLite pool;
// only externally visible behaviour is reproduced here).
#[allow(non_camel_case_types)]
type sqlite3 = c_void;
#[allow(non_camel_case_types)]
type sqlite3_stmt = c_void;

const SQLITE_OK: c_int = 0;
const SQLITE_ROW: c_int = 100;
const SQLITE_DONE: c_int = 101;
const SQLITE_OPEN_READWRITE: c_int = 0x2;
const SQLITE_OPEN_CREATE: c_int = 0x4;
const SQLITE_OPEN_FULLMUTEX: c_int = 0x10000;
const SQLITE_TRANSIENT: isize = -1;

#[link(name = "sqlite3")]
extern "C" {
    fn sqlite3_open_v2(filename: *const c_char, db: *mut *mut sqlite3, flags: c_int, vfs: *const c_char) -> c_int;
    fn sqlite3_close(db: *mut sqlite3) -> c_int;
    fn sqlite3_errcode(db: *mut sqlite3) -> c_int;
    fn sqlite3_extended_errcode(db: *mut sqlite3) -> c_int;
    fn sqlite3_errmsg(db: *mut sqlite3) -> *const c_char;
    fn sqlite3_prepare_v2(db: *mut sqlite3, sql: *const c_char, nbyte: c_int, stmt: *mut *mut sqlite3_stmt, tail: *mut *const c_char) -> c_int;
    fn sqlite3_step(stmt: *mut sqlite3_stmt) -> c_int;
    fn sqlite3_finalize(stmt: *mut sqlite3_stmt) -> c_int;
    fn sqlite3_reset(stmt: *mut sqlite3_stmt) -> c_int;
    fn sqlite3_clear_bindings(stmt: *mut sqlite3_stmt) -> c_int;
    fn sqlite3_bind_text(stmt: *mut sqlite3_stmt, idx: c_int, text: *const c_char, n: c_int, destructor: isize) -> c_int;
    fn sqlite3_bind_int64(stmt: *mut sqlite3_stmt, idx: c_int, value: i64) -> c_int;
    fn sqlite3_bind_blob(stmt: *mut sqlite3_stmt, idx: c_int, value: *const c_void, n: c_int, destructor: isize) -> c_int;
    fn sqlite3_bind_null(stmt: *mut sqlite3_stmt, idx: c_int) -> c_int;
    fn sqlite3_column_count(stmt: *mut sqlite3_stmt) -> c_int;
    fn sqlite3_column_type(stmt: *mut sqlite3_stmt, idx: c_int) -> c_int;
    fn sqlite3_column_int64(stmt: *mut sqlite3_stmt, idx: c_int) -> i64;
    fn sqlite3_column_text(stmt: *mut sqlite3_stmt, idx: c_int) -> *const u8;
    fn sqlite3_column_bytes(stmt: *mut sqlite3_stmt, idx: c_int) -> c_int;
    fn sqlite3_column_blob(stmt: *mut sqlite3_stmt, idx: c_int) -> *const c_void;
    fn sqlite3_last_insert_rowid(db: *mut sqlite3) -> i64;
}

const COL_INTEGER: c_int = 1;
const COL_FLOAT: c_int = 2;
const COL_TEXT: c_int = 3;
const COL_BLOB: c_int = 4;
const COL_NULL: c_int = 5;

#[derive(Debug)]
struct DbError {
    code: i32,
    message: String,
}
impl std::fmt::Display for DbError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "(code: {}) {}", self.code, self.message)
    }
}
impl std::error::Error for DbError {}

fn sqlx_database_error(code: i32, message: String) -> anyhow::Error {
    // sqlx Error::Database displays as "error returned from database: (code: N) msg"
    // and carries the database error as its source.  Creating the chain in
    // this order reproduces anyhow's Debug rendering at the top level.
    let inner = DbError { code, message: message.clone() };
    anyhow::Error::new(inner).context(format!("error returned from database: (code: {}) {}", code, message))
}

struct Conn {
    db: *mut sqlite3,
}
// The connection is only used behind a Mutex.
unsafe impl Send for Conn {}

impl Conn {
    fn open(path: &PathBuf) -> Result<Self> {
        let cpath = CString::new(path.to_string_lossy().as_bytes())
            .map_err(|_| anyhow!("invalid path"))?;
        let mut db: *mut sqlite3 = ptr::null_mut();
        let rc = unsafe {
            sqlite3_open_v2(
                cpath.as_ptr(),
                &mut db,
                SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE | SQLITE_OPEN_FULLMUTEX,
                ptr::null(),
            )
        };
        if rc != SQLITE_OK {
            let (code, msg) = if db.is_null() {
                (rc, "out of memory".to_owned())
            } else {
                let code = unsafe { sqlite3_errcode(db) };
                let msg = unsafe { cstr_to_string(sqlite3_errmsg(db)) };
                unsafe { sqlite3_close(db) };
                (code, msg)
            };
            return Err(sqlx_database_error(code, msg));
        }
        Ok(Self { db })
    }

    fn last_error(&self) -> (i32, String) {
        unsafe {
            let code = sqlite3_errcode(self.db);
            (code, cstr_to_string(sqlite3_errmsg(self.db)))
        }
    }

    fn db_error(&self) -> anyhow::Error {
        let (code, msg) = self.last_error();
        sqlx_database_error(code, msg)
    }

    fn simple_db_error_string(&self) -> String {
        let (code, msg) = self.last_error();
        format!("error returned from database: (code: {}) {}", code, msg)
    }

    /// Execute SQL with no result rows expected (may be multiple statements).
    fn exec(&self, sql: &str) -> Result<()> {
        let mut remaining = sql;
        loop {
            let trimmed = remaining.trim();
            if trimmed.is_empty() {
                return Ok(());
            }
            let (stmt, tail_offset) = self.prepare(remaining)?;
            if stmt.is_null() {
                return Ok(());
            }
            let rc = unsafe { sqlite3_step(stmt) };
            let fin_rc = unsafe { sqlite3_finalize(stmt) };
            if rc != SQLITE_DONE && rc != SQLITE_ROW && rc != SQLITE_OK {
                return Err(self.db_error());
            }
            if fin_rc != SQLITE_OK && rc == SQLITE_DONE {
                // finalize surfaces errors of the just-run statement
                // (already handled via step's code in most cases).
            }
            if tail_offset >= remaining.len() {
                return Ok(());
            }
            remaining = &remaining[tail_offset..];
        }
    }

    fn exec_migration(&self, sql: &str) -> std::result::Result<(), String> {
        self.exec(sql).map_err(|e| {
            // For migration failures the reference renders the sqlx error
            // via Display (no chain) inside its own message.
            format!("{}", e)
        })
    }

    fn prepare(&self, sql: &str) -> Result<(*mut sqlite3_stmt, usize)> {
        let csql = CString::new(sql).map_err(|_| anyhow!("invalid sql"))?;
        let mut stmt: *mut sqlite3_stmt = ptr::null_mut();
        let mut tail: *const c_char = ptr::null();
        let rc = unsafe {
            sqlite3_prepare_v2(self.db, csql.as_ptr(), -1, &mut stmt, &mut tail)
        };
        if rc != SQLITE_OK {
            if !stmt.is_null() {
                unsafe { sqlite3_finalize(stmt) };
            }
            return Err(self.db_error());
        }
        let offset = if tail.is_null() {
            sql.len()
        } else {
            unsafe { tail.offset_from(csql.as_ptr()) as usize }
        };
        Ok((stmt, offset))
    }

    fn query(&self, sql: &str, params: &[Param]) -> Result<Vec<Vec<Value>>> {
        let (stmt, _) = self.prepare(sql)?;
        if stmt.is_null() {
            return Ok(Vec::new());
        }
        bind_params(stmt, params);
        let mut rows = Vec::new();
        loop {
            let rc = unsafe { sqlite3_step(stmt) };
            if rc == SQLITE_ROW {
                let n = unsafe { sqlite3_column_count(stmt) };
                let mut row = Vec::new();
                for i in 0..n {
                    row.push(column_value(stmt, i));
                }
                rows.push(row);
            } else if rc == SQLITE_DONE {
                break;
            } else {
                let err = self.db_error();
                unsafe { sqlite3_finalize(stmt) };
                return Err(err);
            }
        }
        unsafe { sqlite3_finalize(stmt) };
        Ok(rows)
    }

    fn execute(&self, sql: &str, params: &[Param]) -> Result<()> {
        let (stmt, _) = self.prepare(sql)?;
        if stmt.is_null() {
            return Ok(());
        }
        bind_params(stmt, params);
        let rc = unsafe { sqlite3_step(stmt) };
        if rc != SQLITE_DONE && rc != SQLITE_ROW && rc != SQLITE_OK {
            let err = self.db_error();
            unsafe { sqlite3_finalize(stmt) };
            return Err(err);
        }
        unsafe { sqlite3_finalize(stmt) };
        Ok(())
    }

    fn last_insert_rowid(&self) -> i64 {
        unsafe { sqlite3_last_insert_rowid(self.db) }
    }
}

impl Drop for Conn {
    fn drop(&mut self) {
        if !self.db.is_null() {
            unsafe { sqlite3_close(self.db) };
        }
    }
}

unsafe fn cstr_to_string(ptr_: *const c_char) -> String {
    if ptr_.is_null() {
        return String::new();
    }
    let cstr = std::ffi::CStr::from_ptr(ptr_);
    cstr.to_string_lossy().into_owned()
}

#[derive(Debug, Clone)]
enum Value {
    Null,
    Integer(i64),
    Real(f64),
    Text(String),
    Blob(Vec<u8>),
}

#[derive(Debug, Clone)]
enum Param {
    Null,
    Integer(i64),
    Text(String),
    Blob(Vec<u8>),
}

fn bind_params(stmt: *mut sqlite3_stmt, params: &[Param]) {
    for (i, param) in params.iter().enumerate() {
        let idx = (i + 1) as c_int;
        unsafe {
            match param {
                Param::Null => { sqlite3_bind_null(stmt, idx); }
                Param::Integer(v) => { sqlite3_bind_int64(stmt, idx, *v); }
                Param::Text(s) => {
                    // SQLITE_TRANSIENT: sqlite copies the text.
                    sqlite3_bind_text(stmt, idx, s.as_ptr() as *const c_char, s.len() as c_int, SQLITE_TRANSIENT);
                }
                Param::Blob(b) => {
                    sqlite3_bind_blob(stmt, idx, b.as_ptr() as *const c_void, b.len() as c_int, SQLITE_TRANSIENT);
                }
            }
        }
    }
}

fn column_value(stmt: *mut sqlite3_stmt, idx: c_int) -> Value {
    let ty = unsafe { sqlite3_column_type(stmt, idx) };
    match ty {
        COL_INTEGER => Value::Integer(unsafe { sqlite3_column_int64(stmt, idx) }),
        COL_FLOAT => {
            // sqlite3_column_double not bound; obtain via text round-trip is wrong.
            // Bind it here through a local extern to keep it faithful.
            #[link(name = "sqlite3")]
            extern "C" { fn sqlite3_column_double(stmt: *mut sqlite3_stmt, idx: c_int) -> f64; }
            Value::Real(unsafe { sqlite3_column_double(stmt, idx) })
        }
        COL_TEXT => {
            let text_ptr = unsafe { sqlite3_column_text(stmt, idx) };
            let n = unsafe { sqlite3_column_bytes(stmt, idx) } as usize;
            if text_ptr.is_null() {
                Value::Text(String::new())
            } else {
                let bytes = unsafe { std::slice::from_raw_parts(text_ptr, n) };
                Value::Text(String::from_utf8_lossy(bytes).into_owned())
            }
        }
        COL_BLOB => {
            let blob_ptr = unsafe { sqlite3_column_blob(stmt, idx) };
            let n = unsafe { sqlite3_column_bytes(stmt, idx) } as usize;
            if blob_ptr.is_null() {
                Value::Blob(Vec::new())
            } else {
                let bytes = unsafe { std::slice::from_raw_parts(blob_ptr as *const u8, n) };
                Value::Blob(bytes.to_vec())
            }
        }
        _ => Value::Null,
    }
}

struct Migration {
    version: i64,
    description: &'static str,
    sql: &'static str,
    checksum_hex: &'static str,
}

const MIGRATIONS: &[Migration] = &[
    Migration {
        version: 20230509041613,
        description: "init entries",
        sql: "\n\nCREATE TABLE entries\n(\n  id        INTEGER PRIMARY KEY  NOT NULL,\n  title     TEXT                 NOT NULL,\n  date      DATE                 NOT NULL,\n  content   TEXT\n)\n",
        checksum_hex: "A9B962E074E56DB0FBFBCF4874ED6D1E8D94313C9C0122247465CC26057AD3635235B208703DB8A0843A8BC16CD50685",
    },
    Migration {
        version: 20230613041405,
        description: "add tags",
        sql: "\n\nCREATE TABLE IF NOT EXISTS tags (\n  entry_id INTEGER NOT NULL,\n  tag TEXT NOT NULL,\n  PRIMARY KEY (entry_id, tag)\n  FOREIGN KEY (entry_id) REFERENCES entries (id) ON DELETE CASCADE\n) \n",
        checksum_hex: "E0EB5FD4D092C82CB2BD4528CE27FE9C037F045245AC9F1235EE2CEF07C75443E8FEC98C3A5F0562C641B1BC5301F319",
    },
    Migration {
        version: 20240104160740,
        description: "entries priorities",
        sql: "\n\nALTER TABLE entries\nAdd COLUMN priority INTEGER DEFAULT NULL;\n",
        checksum_hex: "4DC4E4C3A2CD7ADF8CA6EE6CCA5A84EAA929BBB9C4969AF5BC181A992095E61AA156DAB76718437FCCD99E7FA1A75F7C",
    },
];

fn hex_to_bytes(hex: &str) -> Vec<u8> {
    let mut out = Vec::with_capacity(hex.len() / 2);
    let bytes = hex.as_bytes();
    let mut i = 0;
    while i + 1 < bytes.len() {
        let hi = (bytes[i] as char).to_digit(16).unwrap_or(0) as u8;
        let lo = (bytes[i + 1] as char).to_digit(16).unwrap_or(0) as u8;
        out.push((hi << 4) | lo);
        i += 2;
    }
    out
}

pub struct SqliteDataProvider {
    #[allow(dead_code)]
    pub file_path: PathBuf,
    conn: Mutex<Conn>,
}

impl SqliteDataProvider {
    pub fn new(file_path: PathBuf) -> Result<Self> {
        if let Some(parent) = file_path.parent() {
            if !parent.as_os_str().is_empty() {
                fs::create_dir_all(parent)?;
            }
        }
        log::trace!(target: "backend::sqlite", "Creating Database with the URL 'sqlite://{}'", file_path.display());
        let conn = Conn::open(&file_path)?;
        // Touch the database like a real pool would; this surfaces
        // "file is not a database" and similar errors at creation.
        conn.exec("PRAGMA journal_mode = WAL; PRAGMA foreign_keys = ON;")?;
        let provider = Self { file_path, conn: Mutex::new(conn) };
        provider.run_migrations()?;
        Ok(provider)
    }

    fn run_migrations(&self) -> Result<()> {
        let conn = self.conn.lock().unwrap();
        let migrate = |conn: &Conn| -> Result<()> {
            // sqlx migration connection switches journaling off.
            let _ = conn.exec("PRAGMA journal_mode = OFF; PRAGMA foreign_keys = ON; PRAGMA synchronous = OFF;");
            conn.exec(
                "CREATE TABLE IF NOT EXISTS _sqlx_migrations (\n    version BIGINT PRIMARY KEY,\n    description TEXT NOT NULL,\n    installed_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    success BOOLEAN NOT NULL,\n    checksum BLOB NOT NULL,\n    execution_time BIGINT NOT NULL\n);",
            )
            .map_err(|e| anyhow!("Error while applying migrations on database: Error info {}", migration_error_text(&e)))?;
            // Dirty check.
            let dirty = conn
                .query("SELECT version FROM _sqlx_migrations WHERE success = false ORDER BY version LIMIT 1", &[])
                .map_err(|e| anyhow!("Error while applying migrations on database: Error info {}", migration_error_text(&e)))?;
            if let Some(row) = dirty.first() {
                if let Some(Value::Integer(v)) = row.first() {
                    return Err(anyhow!(
                        "Error while applying migrations on database: Error info migration {} is partially applied; fix and remove row from `_sqlx_migrations` table",
                        v
                    ));
                }
            }
            let applied_rows = conn
                .query("SELECT version, checksum FROM _sqlx_migrations ORDER BY version", &[])
                .map_err(|e| anyhow!("Error while applying migrations on database: Error info {}", migration_error_text(&e)))?;
            let mut applied: Vec<(i64, Vec<u8>)> = Vec::new();
            for row in &applied_rows {
                let version = match row.first() { Some(Value::Integer(v)) => *v, _ => continue };
                let checksum = match row.get(1) {
                    Some(Value::Blob(b)) => b.clone(),
                    Some(Value::Text(t)) => t.as_bytes().to_vec(),
                    _ => Vec::new(),
                };
                applied.push((version, checksum));
            }
            // Version missing has its own message in the reference.
            for (version, checksum) in &applied {
                match MIGRATIONS.iter().find(|m| m.version == *version) {
                    None => {
                        return Err(anyhow!(
                            "Database version mismatches. Error Info: migration {} was previously applied but is missing in the resolved migrations",
                            version
                        ));
                    }
                    Some(m) => {
                        if *checksum != hex_to_bytes(m.checksum_hex) {
                            return Err(anyhow!(
                                "Error while applying migrations on database: Error info migration {} was previously applied but has been modified",
                                version
                            ));
                        }
                    }
                }
            }
            let applied_versions: Vec<i64> = applied.iter().map(|(v, _)| *v).collect();
            for m in MIGRATIONS {
                if applied_versions.contains(&m.version) {
                    continue;
                }
                let started = Instant::now();
                let _ = conn.exec("BEGIN");
                let body = (|| -> std::result::Result<(), String> {
                    conn.exec_migration(m.sql)?;
                    conn.execute(
                        "INSERT INTO _sqlx_migrations ( version, description, success, checksum, execution_time ) VALUES ( ?1, ?2, TRUE, ?3, -1 )",
                        &[
                            Param::Integer(m.version),
                            Param::Text(m.description.to_owned()),
                            Param::Blob(hex_to_bytes(m.checksum_hex)),
                        ],
                    )
                    .map_err(|e| format!("{}", e))?;
                    Ok(())
                })();
                match body {
                    Ok(()) => {
                        let _ = conn.exec("COMMIT");
                    }
                    Err(msg) => {
                        let _ = conn.exec("ROLLBACK");
                        // msg already has "error returned from database: ..." form
                        // when it came from a database error.
                        let detail = if msg.starts_with("error returned from database:") {
                            msg
                        } else {
                            // anyhow Display of a context chain shows only the outer
                            // context for our DbError; reconstruct prefix if needed.
                            msg
                        };
                        return Err(anyhow!(
                            "Error while applying migrations on database: Error info while executing migration {}: {}",
                            m.version, detail
                        ));
                    }
                }
                let elapsed_ns = started.elapsed().as_nanos() as i64;
                let _ = conn.execute(
                    "UPDATE _sqlx_migrations SET execution_time = ?1 WHERE version = ?2",
                    &[Param::Integer(elapsed_ns), Param::Integer(m.version)],
                );
            }
            Ok(())
        };
        migrate(&conn)?;
        // Back to per-connection defaults for normal operations.
        let _ = conn.exec("PRAGMA foreign_keys = ON;");
        Ok(())
    }

    fn load_entries_locked(&self, conn: &Conn) -> Result<Vec<Entry>> {
        let rows = conn.query(
            "SELECT id, title, date, content, priority FROM entries",
            &[],
        )?;
        let mut entries = Vec::new();
        for row in rows {
            let id = decode_u32(row.get(0), "id", false)?;
            let title = decode_string(row.get(1), "title")?;
            let date = decode_date(row.get(2))?;
            let content = match row.get(3) {
                Some(Value::Null) | None => String::new(),
                Some(_) => decode_string(row.get(3), "content")?,
            };
            let priority = decode_opt_u32(row.get(4), "priority")?;
            let tag_rows = conn.query(
                "SELECT tag FROM tags WHERE entry_id = ?1",
                &[Param::Integer(id as i64)],
            )?;
            let mut tags = Vec::new();
            for trow in tag_rows {
                tags.push(decode_string(trow.get(0), "tag")?);
            }
            entries.push(Entry { id, date, title, content, tags, priority });
        }
        Ok(entries)
    }
}

fn migration_error_text(err: &anyhow::Error) -> String {
    // sqlx MigrateError display for execute errors is
    // "while executing migration N: ..."; other layers are handled by callers.
    // Our Conn errors already display in sqlx's database-error form.
    format!("{}", err)
}

fn sql_type_name(v: &Value) -> &'static str {
    match v {
        Value::Integer(_) => "INTEGER",
        Value::Real(_) => "REAL",
        Value::Text(_) => "TEXT",
        Value::Blob(_) => "BLOB",
        Value::Null => "NULL",
    }
}

fn decode_u32(v: Option<&Value>, column: &str, _opt: bool) -> Result<u32> {
    match v {
        Some(Value::Integer(i)) => {
            if *i < 0 || *i > u32::MAX as i64 {
                Err(sql_decode_error(column, "out of range integral type conversion attempted"))
            } else {
                Ok(*i as u32)
            }
        }
        Some(Value::Null) | None => Err(sql_decode_error(
            column,
            "unexpected null; try decoding as an `Option`",
        )),
        Some(other) => Err(sql_decode_error(
            column,
            &format!(
                "mismatched types; Rust type `u32` (as SQL type `INTEGER`) is not compatible with SQL type `{}`",
                sql_type_name(other)
            ),
        )),
    }
}

fn decode_opt_u32(v: Option<&Value>, column: &str) -> Result<Option<u32>> {
    match v {
        Some(Value::Null) | None => Ok(None),
        Some(Value::Integer(i)) => {
            if *i < 0 || *i > u32::MAX as i64 {
                Err(sql_decode_error(column, "out of range integral type conversion attempted"))
            } else {
                Ok(Some(*i as u32))
            }
        }
        Some(other) => Err(sql_decode_error(
            column,
            &format!(
                "mismatched types; Rust type `core::option::Option<u32>` (as SQL type `INTEGER`) is not compatible with SQL type `{}`",
                sql_type_name(other)
            ),
        )),
    }
}

fn decode_string(v: Option<&Value>, column: &str) -> Result<String> {
    match v {
        Some(Value::Text(s)) => Ok(s.clone()),
        Some(Value::Null) | None => Err(sql_decode_error(
            column,
            "unexpected null; try decoding as an `Option`",
        )),
        Some(other) => Err(sql_decode_error(
            column,
            &format!(
                "mismatched types; Rust type `alloc::string::String` (as SQL type `TEXT`) is not compatible with SQL type `{}`",
                sql_type_name(other)
            ),
        )),
    }
}

fn decode_date(v: Option<&Value>) -> Result<chrono::DateTime<chrono::Utc>> {
    match v {
        Some(Value::Text(s)) => parse_sqlite_datetime(s)
            .map_err(|msg| sql_decode_error("date", &msg)),
        Some(Value::Integer(i)) => {
            // sqlx decodes integer timestamps as seconds since the epoch.
            chrono::DateTime::from_timestamp(*i, 0)
                .ok_or_else(|| sql_decode_error("date", &format!("invalid datetime: {}", i)))
        }
        Some(Value::Null) | None => Err(sql_decode_error(
            "date",
            "unexpected null; try decoding as an `Option`",
        )),
        Some(other) => Err(sql_decode_error(
            "date",
            &format!(
                "mismatched types; Rust type `chrono::datetime::DateTime<chrono::offset::utc::Utc>` (as SQL type `TEXT`) is not compatible with SQL type `{}`",
                sql_type_name(other)
            ),
        )),
    }
}

impl DataProvider for SqliteDataProvider {
    fn load_all_entries(&self) -> Result<Vec<Entry>> {
        let conn = self.conn.lock().unwrap();
        self.load_entries_locked(&conn)
    }

    fn add_entry(&self, draft: EntryDraft) -> Result<Entry> {
        let conn = self.conn.lock().unwrap();
        conn.execute(
            "INSERT INTO entries (title, date, content, priority) VALUES (?1, ?2, ?3, ?4)",
            &[
                Param::Text(draft.title.clone()),
                Param::Text(date_to_sqlite_text(&draft.date)),
                Param::Text(draft.content.clone()),
                match draft.priority { Some(p) => Param::Integer(p as i64), None => Param::Null },
            ],
        )?;
        let id = conn.last_insert_rowid() as u32;
        for tag in &draft.tags {
            conn.execute(
                "INSERT INTO tags (entry_id, tag) VALUES (?1, ?2)",
                &[Param::Integer(id as i64), Param::Text(tag.clone())],
            )?;
        }
        Ok(Entry {
            id,
            date: draft.date,
            title: draft.title,
            content: draft.content,
            tags: draft.tags,
            priority: draft.priority,
        })
    }

    fn remove_entry(&self, id: u32) -> Result<()> {
        let conn = self.conn.lock().unwrap();
        // Foreign keys are ON, so tags cascade; deleting them explicitly is
        // harmless and makes behaviour independent of the pragma state.
        conn.execute("DELETE FROM tags WHERE entry_id = ?1", &[Param::Integer(id as i64)])?;
        conn.execute("DELETE FROM entries WHERE id = ?1", &[Param::Integer(id as i64)])?;
        Ok(())
    }

    fn update_entry(&self, entry: &Entry) -> Result<()> {
        let conn = self.conn.lock().unwrap();
        conn.execute(
            "UPDATE entries SET title = ?1, date = ?2, content = ?3, priority = ?4 WHERE id = ?5",
            &[
                Param::Text(entry.title.clone()),
                Param::Text(date_to_sqlite_text(&entry.date)),
                Param::Text(entry.content.clone()),
                match entry.priority { Some(p) => Param::Integer(p as i64), None => Param::Null },
                Param::Integer(entry.id as i64),
            ],
        )?;
        conn.execute("DELETE FROM tags WHERE entry_id = ?1", &[Param::Integer(entry.id as i64)])?;
        for tag in &entry.tags {
            conn.execute(
                "INSERT INTO tags (entry_id, tag) VALUES (?1, ?2)",
                &[Param::Integer(entry.id as i64), Param::Text(tag.clone())],
            )?;
        }
        Ok(())
    }

    fn assign_priority(&self, priority: u32) -> Result<()> {
        let conn = self.conn.lock().unwrap();
        conn.execute(
            "UPDATE entries SET priority = ?1 WHERE priority IS NULL",
            &[Param::Integer(priority as i64)],
        )?;
        Ok(())
    }
}
RS
