                )),
        )
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .action(ArgAction::Count)
                .help("Increases logging verbosity each use for up to 3 times"),
        )
        .arg(
            Arg::new("log")
                .short('l')
                .long("log")
                .value_name("FILE PATH")
                .help(format!(
                    "Specifies a file to use for logging\n(default file: {})",
                    default_log.display()
                )),
        )
        .subcommand(
            Command::new("print-config")
                .visible_alias("pc")
                .about("Print the current settings including the paths for the back-end files"),
        )
        .subcommand(
            Command::new("import-journals")
                .visible_alias("imj")
                .about("Import journals from the given transfer JSON file to the current back-end file")
                .arg(
                    Arg::new("path")
                        .short('p')
                        .long("path")
                        .value_name("FILE PATH")
                        .required(true)
                        .help("Path of the JSON file to import from"),
                ),
        )
        .subcommand(
            Command::new("assign-priority")
                .visible_alias("ap")
                .about("Assign priority for all the entries with empty priority field")
                .arg(
                    Arg::new("priority")
                        .value_name("PRIORITY")
                        .required(true)
                        .value_parser(clap::value_parser!(u32))
                        .help("Priority value (Positive number)"),
                ),
        )
        .subcommand(
            Command::new("theme")
                .visible_alias("style")
                .about("Provides commands regarding changing themes and styles of the app")
                .arg_required_else_help(true)
                .subcommand(
                    Command::new("print-path")
                        .visible_alias("path")
                        .about("Prints the path to the user themes file"),
                )
                .subcommand(
                    Command::new("print-default")
                        .visible_alias("default")
                        .about("Dumps the styles with the default values to be used as a reference and base for user custom themes"),
                )
                .subcommand(
                    Command::new("write-defaults")
                        .visible_alias("write")
                        .about("Creates user custom themes file if doesn't exist then writes the default styles to it"),
                ),
        )
}

enum Pending {
    None,
    Import(PathBuf),
    AssignPriority(u32),
}

fn main() -> Result<()> {
    let matches = build_cli().get_matches();

    let json_path: Option<PathBuf> = matches.get_one::<String>("json-file-path").map(PathBuf::from);
    let sqlite_path: Option<PathBuf> = matches.get_one::<String>("sqlite-file-path").map(PathBuf::from);
    let backend: Option<BackendType> = matches.get_one::<String>("backend-type").map(|s| match s.as_str() {
        "json" => BackendType::Json,
        _ => BackendType::Sqlite,
    });
    let custom_config: Option<PathBuf> = matches.get_one::<String>("config").map(PathBuf::from);
    let verbose: u8 = matches.get_count("verbose");
    let log_path: Option<PathBuf> = matches.get_one::<String>("log").map(PathBuf::from);

    let settings = Settings::load(custom_config.clone(), json_path, sqlite_path, backend)?;
    logging::setup(log_path, verbose)?;

    let mut pending = Pending::None;
    if let Some((name, sub)) = matches.subcommand() {
        match name {
            "print-config" => {
                let text = settings.to_toml_string()?;
                println!("{}", text);
                return Ok(());
            }
            "theme" => {
                handle_theme(sub, &custom_config)?;
                return Ok(());
            }
            "import-journals" => {
                let path = sub.get_one::<String>("path").unwrap();
                pending = Pending::Import(PathBuf::from(path));
            }
            "assign-priority" => {
                let prio = *sub.get_one::<u32>("priority").unwrap();
                pending = Pending::AssignPriority(prio);
            }
            _ => {}
        }
    }

    let styles = themes::load_styles(&custom_config)?;
    run_tui(settings, styles, pending)
}

fn handle_theme(matches: &clap::ArgMatches, custom_config: &Option<PathBuf>) -> Result<()> {
    let (name, _sub) = matches.subcommand().ok_or_else(|| anyhow!("missing theme subcommand"))?;
    match name {
        "print-path" => {
            let path = settings::themes_path(custom_config);
            println!("{}", path.display());
            Ok(())
        }
        "print-default" => {
            print!("{}", themes::DEFAULT_THEMES_TOML);
            if !themes::DEFAULT_THEMES_TOML.ends_with("\n\n") {
                println!();
            }
            Ok(())
        }
        "write-defaults" => {
            let path = settings::themes_path(custom_config);
            if path.exists() {
                return Err(anyhow!("Themes file already exists. Path: {}", path.display()));
            }
            themes::write_default_themes(&path)?;
            println!("Default themes have been written to {}", path.display());
            Ok(())
        }
        _ => Ok(()),
    }
}

fn run_tui(_settings: Settings, _styles: themes::AppStyles, _pending: Pending) -> Result<()> {
    // Placeholder: replaced by the app module below.
    crossterm::terminal::enable_raw_mode().context("terminal")?;
    let _ = crossterm::terminal::disable_raw_mode();
    Ok(())
}
