use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use unicode_width::UnicodeWidthChar;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EditorMode {
    Normal,
    Edit,
    Visual,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Operator {
    Delete,
    Yank,
    Change,
}

/// A small multi-line editor with Vim-like Normal/Visual modes and an
/// Emacs-like Edit (insert) mode.  It stores text as lines without line
/// terminators, mirroring a typical terminal text-area widget.
#[derive(Debug, Clone)]
pub struct Editor {
    pub lines: Vec<String>,
    // cursor (row, col) col is a char index, 0..=len(line)
    pub row: usize,
    pub col: usize,
    pub mode: EditorMode,
    anchor: Option<(usize, usize)>,
    yank: String,
    operator: Option<Operator>,
    pending_g: bool,
    goal_col: Option<usize>,
    undo_stack: Vec<Snapshot>,
    redo_stack: Vec<Snapshot>,
    pub scroll_row: usize,
    pub scroll_col: usize,
}

#[derive(Debug, Clone)]
struct Snapshot {
    lines: Vec<String>,
    row: usize,
    col: usize,
}

pub const TAB_WIDTH: usize = 4;

pub fn char_disp_width_at(ch: char, visual_col: usize) -> usize {
    if ch == '\t' {
        TAB_WIDTH - (visual_col % TAB_WIDTH)
    } else {
        UnicodeWidthChar::width(ch).unwrap_or(0)
    }
}

pub fn line_disp_width(line: &str) -> usize {
    let mut col = 0;
    for ch in line.chars() {
        col += char_disp_width_at(ch, col);
    }
    col
}

pub fn disp_col_of(line: &str, char_col: usize) -> usize {
    let mut col = 0;
    for (i, ch) in line.chars().enumerate() {
        if i >= char_col { break; }
        col += char_disp_width_at(ch, col);
    }
    col
}

impl Default for Editor {
    fn default() -> Self { Self::new("") }
}

impl Editor {
    pub fn new(text: &str) -> Self {
        let mut lines: Vec<String> = text.lines().map(|s| s.to_owned()).collect();
        if lines.is_empty() {
            lines.push(String::new());
        } else if text.ends_with('\n') {
            lines.push(String::new());
        }
        let row = lines.len() - 1;
        let col = lines[row].chars().count();
        Self {
            lines,
            row,
            col,
            mode: EditorMode::Normal,
            anchor: None,
            yank: String::new(),
            operator: None,
            pending_g: false,
            goal_col: None,
            undo_stack: Vec::new(),
            redo_stack: Vec::new(),
            scroll_row: 0,
            scroll_col: 0,
        }
    }

    pub fn set_text(&mut self, text: &str) {
        *self = Self::new(text);
    }

    pub fn text(&self) -> String {
        self.lines.join("\n")
    }

    pub fn is_empty_selection(&self) -> bool { self.anchor.is_none() }

    pub fn selection_range(&self) -> Option<((usize, usize), (usize, usize))> {
        let anchor = self.anchor?;
        let cur = (self.row, self.col);
        if anchor <= cur { Some((anchor, cur)) } else { Some((cur, anchor)) }
    }

    fn snapshot(&self) -> Snapshot {
        Snapshot { lines: self.lines.clone(), row: self.row, col: self.col }
    }
    fn push_undo(&mut self) {
        let snap = self.snapshot();
        // Avoid duplicate consecutive snapshots.
        if self.undo_stack.last().map(|s: &Snapshot| &s.lines) != Some(&snap.lines) {
            self.undo_stack.push(snap);
        }
        self.redo_stack.clear();
    }
    pub fn undo(&mut self) {
        if let Some(snap) = self.undo_stack.pop() {
            let cur = self.snapshot();
            self.redo_stack.push(cur);
            self.lines = snap.lines;
            self.row = snap.row;
            self.col = snap.col;
            self.anchor = None;
            self.mode = EditorMode::Normal;
            self.clamp_cursor();
        }
    }
    pub fn redo(&mut self) {
        if let Some(snap) = self.redo_stack.pop() {
            let cur = self.snapshot();
            self.undo_stack.push(cur);
            self.lines = snap.lines;
            self.row = snap.row;
            self.col = snap.col;
            self.anchor = None;
            self.mode = EditorMode::Normal;
            self.clamp_cursor();
        }
    }

    fn line_len(&self, row: usize) -> usize {
        self.lines.get(row).map(|l| l.chars().count()).unwrap_or(0)
    }
    fn clamp_cursor(&mut self) {
        if self.row >= self.lines.len() { self.row = self.lines.len().saturating_sub(1); }
        let max = self.line_len(self.row);
        // In Normal/Visual the original widget allows the cursor to sit one
        // cell past the last character (it loads content with the cursor at
        // the end), so allow col == len in every mode.
        if self.col > max { self.col = max; }
    }
    fn byte_of(&self, row: usize, col: usize) -> usize {
        let line = &self.lines[row];
        if col == 0 { return 0; }
        line.char_indices().nth(col).map(|(b, _)| b).unwrap_or(line.len())
    }

    // ---------- basic motions ----------
    pub fn move_left(&mut self) { if self.col > 0 { self.col -= 1; } self.goal_col = None; }
    pub fn move_right(&mut self) {
        if self.col < self.line_len(self.row) { self.col += 1; }
        self.goal_col = None;
    }
    pub fn move_up(&mut self) {
        if self.row > 0 {
            let goal = *self.goal_col.get_or_insert(disp_col_of(&self.lines[self.row], self.col));
            self.row -= 1;
            self.col = self.char_col_for_disp(self.row, goal);
        }
    }
    pub fn move_down(&mut self) {
        if self.row + 1 < self.lines.len() {
            let goal = *self.goal_col.get_or_insert(disp_col_of(&self.lines[self.row], self.col));
            self.row += 1;
            self.col = self.char_col_for_disp(self.row, goal);
        }
    }
    fn char_col_for_disp(&self, row: usize, disp: usize) -> usize {
        let line = &self.lines[row];
        let mut d = 0;
        for (i, ch) in line.chars().enumerate() {
            let w = char_disp_width_at(ch, d);
            if d + w > disp { return i; }
            d += w;
        }
        line.chars().count()
    }
    pub fn move_head(&mut self) { self.col = 0; self.goal_col = None; }
    pub fn move_end(&mut self) { self.col = self.line_len(self.row); self.goal_col = None; }
    pub fn move_top(&mut self) { self.row = 0; self.clamp_cursor(); }
    pub fn move_bottom(&mut self) { self.row = self.lines.len().saturating_sub(1); self.clamp_cursor(); }

    fn is_word(ch: char) -> bool { ch.is_alphanumeric() || ch == '_' }

    fn flat(&self) -> Vec<char> {
        // Flatten with '\n' separators for word motions.
        let mut v = Vec::new();
        for (i, line) in self.lines.iter().enumerate() {
            if i > 0 { v.push('\n'); }
            v.extend(line.chars());
        }
        v
    }
    fn flat_pos(&self) -> usize {
        let mut pos = 0;
        for i in 0..self.row {
            pos += self.lines[i].chars().count() + 1;
        }
        pos + self.col
    }
    fn set_flat_pos(&mut self, mut pos: usize) {
        for (i, line) in self.lines.iter().enumerate() {
            let len = line.chars().count();
            if pos <= len {
                self.row = i;
                self.col = pos;
                return;
            }
            pos -= len + 1;
        }
        self.row = self.lines.len().saturating_sub(1);
        self.col = self.line_len(self.row);
    }
    pub fn word_forward(&mut self) {
        let flat = self.flat();
        let mut i = self.flat_pos();
        if i < flat.len() {
            // Skip current word (or non-word run), then whitespace/newlines.
            if Self::is_word(flat[i]) {
                while i < flat.len() && Self::is_word(flat[i]) { i += 1; }
            } else if !flat[i].is_whitespace() {
                while i < flat.len() && !Self::is_word(flat[i]) && !flat[i].is_whitespace() { i += 1; }
            }
            while i < flat.len() && flat[i].is_whitespace() { i += 1; }
        }
        self.set_flat_pos(i);
        self.goal_col = None;
    }
    pub fn word_backward(&mut self) {
        let flat = self.flat();
        let mut i = self.flat_pos();
        if i > 0 {
            i -= 1;
            while i > 0 && flat[i].is_whitespace() { i -= 1; }
            if Self::is_word(flat[i]) {
                while i > 0 && Self::is_word(flat[i - 1]) { i -= 1; }
            } else {
                while i > 0 && !Self::is_word(flat[i - 1]) && !flat[i - 1].is_whitespace() { i -= 1; }
            }
        }
        self.set_flat_pos(i);
        self.goal_col = None;
    }
    pub fn word_end_forward(&mut self) {
        let flat = self.flat();
        let mut i = self.flat_pos();
        if i < flat.len() {
            i += 1;
            while i < flat.len() && flat[i].is_whitespace() { i += 1; }
            if i < flat.len() {
                if Self::is_word(flat[i]) {
                    while i + 1 < flat.len() && Self::is_word(flat[i + 1]) { i += 1; }
                } else {
                    while i + 1 < flat.len() && !Self::is_word(flat[i + 1]) && !flat[i + 1].is_whitespace() { i += 1; }
                }
                // 'e' lands on the last char of the word: cursor col points at
                // that char.  Because our cursor may sit past a char, use i+? 
                // Vim e leaves cursor on last char.
                self.set_flat_pos(i);
                return;
            }
        }
        self.set_flat_pos(i.min(flat.len()));
    }

    // ---------- editing primitives ----------
    pub fn insert_char(&mut self, ch: char) {
        self.push_undo();
        let b = self.byte_of(self.row, self.col);
        self.lines[self.row].insert(b, ch);
        self.col += 1;
    }
    pub fn insert_str(&mut self, text: &str) {
        if text.is_empty() { return; }
        self.push_undo();
        for ch in text.chars() {
            if ch == '\n' {
                self.insert_newline_inner();
            } else if ch != '\r' {
                let b = self.byte_of(self.row, self.col);
                self.lines[self.row].insert(b, ch);
                self.col += 1;
            }
        }
    }
    fn insert_newline_inner(&mut self) {
        let b = self.byte_of(self.row, self.col);
        let rest = self.lines[self.row][b..].to_owned();
        self.lines[self.row].truncate(b);
        self.row += 1;
        self.lines.insert(self.row, rest);
        self.col = 0;
    }
    pub fn insert_newline(&mut self) {
        self.push_undo();
        self.insert_newline_inner();
    }
    pub fn backspace(&mut self) {
        if self.col > 0 {
            self.push_undo();
            self.col -= 1;
            let b = self.byte_of(self.row, self.col);
            self.lines[self.row].remove(b);
        } else if self.row > 0 {
            self.push_undo();
            let cur = self.lines.remove(self.row);
            self.row -= 1;
            self.col = self.line_len(self.row);
            self.lines[self.row].push_str(&cur);
        }
    }
    pub fn delete_char(&mut self) {
        if self.col < self.line_len(self.row) {
            self.push_undo();
            let b = self.byte_of(self.row, self.col);
            self.lines[self.row].remove(b);
        } else if self.row + 1 < self.lines.len() {
            self.push_undo();
            let next = self.lines.remove(self.row + 1);
            self.lines[self.row].push_str(&next);
        }
    }
    fn delete_range(&mut self, start: (usize, usize), end: (usize, usize), inclusive_end: bool) -> String {
        // end is a cursor position; if inclusive_end, delete through the char
        // at end as well.
        let mut end = end;
        if inclusive_end && end.1 < self.line_len(end.0) {
            end.1 += 1;
        }
        if start == end { return String::new(); }
        self.push_undo();
        let removed = self.text_range(start, end);
        if start.0 == end.0 {
            let b1 = self.byte_of(start.0, start.1);
            let b2 = self.byte_of(end.0, end.1);
            self.lines[start.0].drain(b1..b2);
        } else {
            let b1 = self.byte_of(start.0, start.1);
            let b2 = self.byte_of(end.0, end.1);
            let tail = self.lines[end.0][b2..].to_owned();
            self.lines[start.0].truncate(b1);
            self.lines[start.0].push_str(&tail);
            self.lines.drain(start.0 + 1..=end.0);
        }
        self.row = start.0;
        self.col = start.1;
        self.clamp_cursor();
        removed
    }
    pub fn text_range(&self, start: (usize, usize), end: (usize, usize)) -> String {
        // end exclusive
        if start.0 == end.0 {
            let line = &self.lines[start.0];
            let b1 = self.byte_of(start.0, start.1);
            let b2 = self.byte_of(end.0, end.1.min(self.line_len(end.0)));
            return line[b1..b2].to_owned();
        }
        let mut out = String::new();
        let first = &self.lines[start.0];
        out.push_str(&first[self.byte_of(start.0, start.1)..]);
        for r in start.0 + 1..end.0 {
            out.push('\n');
            out.push_str(&self.lines[r]);
        }
        out.push('\n');
        let last = &self.lines[end.0];
        out.push_str(&last[..self.byte_of(end.0, end.1.min(self.line_len(end.0)))]);
        out
    }
    pub fn selected_text(&self) -> String {
        if let Some((mut s, mut e)) = self.selection_range() {
            // Visual selection includes the char under the cursor.
            if e.1 < self.line_len(e.0) { e.1 += 1; }
            let _ = &mut s;
            return self.text_range(s, e);
        }
        String::new()
    }
    pub fn yank_text(&self) -> &str { &self.yank }
    pub fn set_yank(&mut self, text: String) { self.yank = text; }

    pub fn start_visual(&mut self) {
        self.anchor = Some((self.row, self.col));
        self.mode = EditorMode::Visual;
    }
    pub fn exit_visual(&mut self) {
        self.anchor = None;
        self.mode = EditorMode::Normal;
    }

    fn apply_operator(&mut self, op: Operator, start: (usize, usize), end: (usize, usize), inclusive: bool) {
        let (s, e) = if start <= end { (start, end) } else { (end, start) };
        match op {
            Operator::Yank => {
                let mut ee = e;
                if inclusive && ee.1 < self.line_len(ee.0) { ee.1 += 1; }
                self.yank = self.text_range(s, ee);
                self.row = s.0;
                self.col = s.1;
            }
            Operator::Delete => {
                let removed = self.delete_range(s, e, inclusive);
                if !removed.is_empty() { self.yank = removed; }
                self.mode = EditorMode::Normal;
            }
            Operator::Change => {
                let removed = self.delete_range(s, e, inclusive);
                if !removed.is_empty() { self.yank = removed; }
                self.mode = EditorMode::Edit;
            }
        }
    }

    fn delete_line(&mut self) {
        self.push_undo();
        let line = self.lines.remove(self.row);
        self.yank = line;
        if self.lines.is_empty() { self.lines.push(String::new()); }
        if self.row >= self.lines.len() { self.row = self.lines.len() - 1; }
        self.col = 0;
    }
    fn yank_line(&mut self) {
        self.yank = self.lines[self.row].clone();
    }

    pub fn paste_after(&mut self) {
        if self.yank.is_empty() { return; }
        let text = self.yank.clone();
        // If the yank buffer holds whole lines (no mixed partial behaviour we
        // can detect easily), tui-textarea pastes at the cursor position.
        // Vim 'p' after a char-wise yank pastes after the cursor.
        if self.col < self.line_len(self.row) {
            self.col += 1;
        }
        self.insert_str(&text);
        // insert_str leaves the cursor after the pasted text; move back one.
        if self.col > 0 { self.col -= 1; }
    }

    // ---------- key handling ----------
    /// Handle a key while in Edit mode (Emacs-ish).  Returns true if handled.
    pub fn handle_edit_key(&mut self, key: KeyEvent) -> bool {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let alt = key.modifiers.contains(KeyModifiers::ALT);
        match key.code {
            KeyCode::Char(ch) if ctrl => {
                match ch {
                    'f' => self.move_right(),
                    'b' => self.move_left(),
                    'n' => self.move_down(),
                    'p' => self.move_up(),
                    'a' => self.move_head(),
                    'e' => self.move_end(),
                    'd' => self.delete_char(),
                    'h' => self.backspace(),
                    'k' => {
                        // delete to end of line
                        self.push_undo();
                        let b = self.byte_of(self.row, self.col);
                        self.lines[self.row].truncate(b);
                    }
                    'u' => {
                        // Emacs C-u in tui-textarea typically undoes; keep undo.
                        self.undo();
                        self.mode = EditorMode::Edit;
                    }
                    'w' => {
                        // delete word backward
                        let start = (self.row, self.col);
                        self.word_backward();
                        let s = (self.row, self.col);
                        self.delete_range(s, start, false);
                        self.mode = EditorMode::Edit;
                    }
                    _ => return false,
                }
                true
            }
            KeyCode::Char(ch) if alt => {
                match ch {
                    'f' => self.word_forward(),
                    'b' => self.word_backward(),
                    'd' => {
                        let start = (self.row, self.col);
                        self.word_forward();
                        let e = (self.row, self.col);
                        self.delete_range(start, e, false);
                        self.mode = EditorMode::Edit;
                    }
                    _ => return false,
                }
                true
            }
            KeyCode::Char(ch) => { self.insert_char(ch); true }
            KeyCode::Enter => { self.insert_newline(); true }
            KeyCode::Tab => { self.insert_char('\t'); true }
            KeyCode::Backspace => {
                if alt {
                    let start = (self.row, self.col);
                    self.word_backward();
                    let s = (self.row, self.col);
                    self.delete_range(s, start, false);
                    self.mode = EditorMode::Edit;
                } else {
                    self.backspace();
                }
                true
            }
            KeyCode::Delete => { self.delete_char(); true }
            KeyCode::Left => { if ctrl || alt { self.word_backward(); } else { self.move_left(); } true }
            KeyCode::Right => { if ctrl || alt { self.word_forward(); } else { self.move_right(); } true }
            KeyCode::Up => { self.move_up(); true }
            KeyCode::Down => { self.move_down(); true }
            KeyCode::Home => { self.move_head(); true }
            KeyCode::End => { self.move_end(); true }
            KeyCode::PageUp => { for _ in 0..10 { self.move_up(); } true }
            KeyCode::PageDown => { for _ in 0..10 { self.move_down(); } true }
            _ => false,
        }
    }

    /// Handle a key in Normal / Visual mode.  Returns true if the key was
    /// consumed by the editor (as opposed to being a global command, which
    /// the caller decides before calling this for most keys).
    pub fn handle_normal_visual_key(&mut self, key: KeyEvent) -> bool {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        if ctrl {
            return false;
        }
        // Pending operator
        if let Some(op) = self.operator.take() {
            return self.handle_operator_motion(op, key);
        }
        if self.pending_g {
            self.pending_g = false;
            if key.code == KeyCode::Char('g') {
                self.move_top();
                return true;
            }
            return true;
        }
        match key.code {
            KeyCode::Char(ch) => self.handle_normal_char(ch),
            KeyCode::Left => { self.move_left(); true }
            KeyCode::Right => { self.move_right(); true }
            KeyCode::Up => { self.move_up(); true }
            KeyCode::Down => { self.move_down(); true }
            KeyCode::Home => { self.move_head(); true }
            KeyCode::End => { self.move_end(); true }
            KeyCode::PageUp => { for _ in 0..10 { self.move_up(); } true }
            KeyCode::PageDown => { for _ in 0..10 { self.move_down(); } true }
            KeyCode::Delete => {
                if self.mode == EditorMode::Visual {
                    let s = self.selection_range();
                    if let Some((a, b)) = s { self.apply_operator(Operator::Delete, a, b, true); self.anchor = None; }
                } else {
                    self.delete_char();
                }
                true
            }
            KeyCode::Backspace => { self.move_left(); true }
            KeyCode::Enter => { self.move_down(); self.move_head(); true }
            _ => false,
        }
    }

    fn handle_operator_motion(&mut self, op: Operator, key: KeyEvent) -> bool {
        let start = (self.row, self.col);
        let KeyCode::Char(ch) = key.code else { return true };
        match ch {
            'd' if op == Operator::Delete => { self.delete_line(); }
            'y' if op == Operator::Yank => { self.yank_line(); }
            'c' if op == Operator::Change => {
                self.push_undo();
                let line = std::mem::take(&mut self.lines[self.row]);
                self.yank = line;
                self.col = 0;
                self.mode = EditorMode::Edit;
            }
            'w' => { self.word_forward(); let e = (self.row, self.col); self.apply_operator(op, start, e, false); }
            'b' => { self.word_backward(); let e = (self.row, self.col); self.apply_operator(op, start, e, false); }
            'e' => { self.word_end_forward(); let e = (self.row, self.col); self.apply_operator(op, start, e, true); }
            '0' => { self.move_head(); let e = (self.row, self.col); self.apply_operator(op, start, e, false); }
            '$' => { self.move_end(); let e = (self.row, self.col); self.apply_operator(op, start, e, false); }
            'h' => { self.move_left(); let e = (self.row, self.col); self.apply_operator(op, start, e, false); }
            'l' => { self.move_right(); let e = (self.row, self.col); self.apply_operator(op, start, e, false); }
            'j' => {
                // Line-wise-ish: operate over current and next line start.
                self.move_down();
                self.move_head();
                let e = (self.row, self.col);
                self.apply_operator(op, start, e, false);
            }
            'k' => {
                self.move_up();
                self.move_head();
                let e = (self.row, self.col);
                self.apply_operator(op, start, e, false);
            }
            _ => {}
        }
        true
    }

    fn handle_normal_char(&mut self, ch: char) -> bool {
        let visual = self.mode == EditorMode::Visual;
        match ch {
            'h' => self.move_left(),
            'j' => self.move_down(),
            'k' => self.move_up(),
            'l' => self.move_right(),
            'w' | 'W' => self.word_forward(),
            'b' | 'B' => self.word_backward(),
            'e' | 'E' => self.word_end_forward(),
            '0' => self.move_head(),
            '$' => self.move_end(),
            '^' => {
                // first non-blank
                let line = self.lines[self.row].clone();
                self.col = line.chars().position(|c| !c.is_whitespace()).unwrap_or(0);
            }
            'g' => { self.pending_g = true; }
            'G' => self.move_bottom(),
            'i' if !visual => { self.mode = EditorMode::Edit; }
            'I' if !visual => { self.move_head(); self.mode = EditorMode::Edit; }
            'a' if !visual => { self.move_right(); self.mode = EditorMode::Edit; }
            'A' if !visual => { self.move_end(); self.mode = EditorMode::Edit; }
            'o' if !visual => {
                self.push_undo();
                self.row += 1;
                self.lines.insert(self.row, String::new());
                self.col = 0;
                self.mode = EditorMode::Edit;
            }
            'O' if !visual => {
                self.push_undo();
                self.lines.insert(self.row, String::new());
                self.col = 0;
                self.mode = EditorMode::Edit;
            }
            'x' => {
                if visual {
                    if let Some((a, b)) = self.selection_range() { self.anchor = None; self.apply_operator(Operator::Delete, a, b, true); }
                } else {
                    self.delete_char();
                }
            }
            'D' if !visual => {
                let start = (self.row, self.col);
                self.move_end();
                let e = (self.row, self.col);
                self.apply_operator(Operator::Delete, start, e, false);
            }
            'C' if !visual => {
                let start = (self.row, self.col);
                self.move_end();
                let e = (self.row, self.col);
                self.apply_operator(Operator::Change, start, e, false);
            }
            'd' => {
                if visual {
                    if let Some((a, b)) = self.selection_range() { self.anchor = None; self.apply_operator(Operator::Delete, a, b, true); }
                } else {
                    self.operator = Some(Operator::Delete);
                }
            }
            'y' => {
                if visual {
                    if let Some((a, b)) = self.selection_range() { self.anchor = None; self.apply_operator(Operator::Yank, a, b, true); self.mode = EditorMode::Normal; }
                } else {
                    self.operator = Some(Operator::Yank);
                }
            }
            'c' => {
                if visual {
                    if let Some((a, b)) = self.selection_range() { self.anchor = None; self.apply_operator(Operator::Change, a, b, true); }
                } else {
                    self.operator = Some(Operator::Change);
                }
            }
            'p' if !visual => self.paste_after(),
            'P' if !visual => {
                if !self.yank.is_empty() {
                    let text = self.yank.clone();
                    self.insert_str(&text);
                    if self.col > 0 { self.col -= 1; }
                }
            }
            'u' if !visual => { self.undo(); return true; }
            'v' => {
                // handled by caller as a global toggle in some contexts; if
                // we get here, toggle locally.
                if visual { self.exit_visual(); } else { self.start_visual(); }
            }
            'r' if !visual => {
                // Replace requires a following char; without a pending state
                // for it, ignore (rare in tests).
                return true;
            }
            _ => return false,
        }
        true
    }

    pub fn ensure_cursor_visible(&mut self, height: usize, width: usize) {
        if height == 0 || width == 0 { return; }
        if self.row < self.scroll_row { self.scroll_row = self.row; }
        if self.row >= self.scroll_row + height { self.scroll_row = self.row + 1 - height; }
        let disp = disp_col_of(&self.lines[self.row], self.col);
        if disp < self.scroll_col { self.scroll_col = disp; }
        if disp >= self.scroll_col + width { self.scroll_col = disp + 1 - width; }
    }
}
