pub struct EntryPopupState {
    pub is_edit: bool,
    pub entry_id: Option<u32>,
    pub title: TextInput,
    pub date: TextInput,
    pub priority: TextInput,
    pub tags: TextInput,
    pub focus: usize,
    pub title_err: Option<String>,
    pub date_err: Option<String>,
    pub priority_err: Option<String>,
}

impl EntryPopupState {
    pub fn new_create() -> Self {
        let today = chrono::Local::now().date_naive().format("%d-%m-%Y").to_string();
        Self {
            is_edit: false,
            entry_id: None,
            title: TextInput::new(""),
            date: TextInput::with_cursor_at_start(today),
            priority: TextInput::new(""),
            tags: TextInput::new(""),
            focus: 0,
            title_err: None,
            date_err: None,
            priority_err: None,
        }
    }
    pub fn new_edit(entry: &Entry) -> Self {
        Self {
            is_edit: true,
            entry_id: Some(entry.id),
            title: TextInput::new(entry.title.clone()),
            date: TextInput::with_cursor_at_start(entry.date.format("%d-%m-%Y").to_string()),
            priority: TextInput::new(entry.priority.map(|p| p.to_string()).unwrap_or_default()),
            tags: TextInput::new(entry.tags.join(", ")),
            focus: 0,
            title_err: None,
            date_err: None,
            priority_err: None,
        }
    }
    pub fn focused_input_mut(&mut self) -> &mut TextInput {
        match self.focus {
            0 => &mut self.title,
            1 => &mut self.date,
            2 => &mut self.priority,
            _ => &mut self.tags,
        }
    }
    pub fn clear_focus_err(&mut self) {
        match self.focus {
            0 => self.title_err = None,
            1 => self.date_err = None,
            2 => self.priority_err = None,
            _ => {}
        }
    }
    pub fn validate(&mut self) -> Option<EntryDraft> {
        self.title_err = None;
        self.date_err = None;
        self.priority_err = None;
        let mut ok = true;
        if self.title.text().is_empty() {
            self.title_err = Some("Title can't be empty".to_owned());
            ok = false;
        }
        let date = parse_entry_date(self.date.text());
        let date = match date {
            Ok(d) => Some(d),
            Err(msg) => { self.date_err = Some(msg); ok = false; None }
        };
        let mut priority = None;
        if !self.priority.text().is_empty() {
            match self.priority.text().parse::<u32>() {
                Ok(p) => priority = Some(p),
                Err(_) => {
                    self.priority_err = Some("Priority must be a positive number".to_owned());
                    ok = false;
                }
            }
        }
        if !ok {
            return None;
        }
        Some(EntryDraft {
            date: date.unwrap(),
            title: self.title.text().to_owned(),
            content: String::new(),
            tags: parse_tags(self.tags.text()),
            priority,
        })
    }
}

pub fn parse_entry_date(text: &str) -> std::result::Result<DateTime<Utc>, String> {
    let naive = NaiveDate::parse_from_str(text, "%d-%m-%Y").map_err(|e| e.to_string())?;
    let ndt = naive.and_hms_opt(0, 0, 0).unwrap();
    Ok(Utc.from_utc_datetime(&ndt))
}

pub fn parse_tags(text: &str) -> Vec<String> {
    text.split_terminator(',')
        .map(|t| t.trim().to_owned())
        .collect()
}

