pub enum Popup {
    MsgBox(MsgBoxState),
    Entry(EntryPopupState),
    Tags(TagsPopupState),
    Filter(FilterPopupState),
    Sort(SortPopupState),
    Help(HelpPopupState),
    Fuzzy(FuzzyPopupState),
    Export(ExportPopupState),
    Loading(String),
}

#[derive(Clone)]
struct Snapshot {
    entries: Vec<Entry>,
    selected_id: Option<u32>,
}

pub struct App {
    pub settings: Settings,
    pub styles: AppStyles,
    provider: Box<dyn DataProvider>,
    pub entries: Vec<Entry>,
    pub displayed: Vec<usize>,
    pub list_state: ListState,
    pub focus: Focus,
    pub editor: Editor,
    pub full_screen: bool,
    pub multi_select: bool,
    pub multi_selected: HashSet<u32>,
    pub filter: Option<Filter>,
    pub sort: SortOptions,
    pub popups: Vec<Popup>,
    pub should_quit: bool,
    undo_stack: Vec<Snapshot>,
    redo_stack: Vec<Snapshot>,
}

pub fn run(settings: Settings, styles: AppStyles, pending: PendingCommand) -> Result<()> {
    // Install a panic hook that restores the terminal before printing.
    let original_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        let _ = disable_raw_mode();
        let _ = execute!(io::stdout(), LeaveAlternateScreen);
        let _ = execute!(io::stdout(), crossterm::cursor::Show);
        original_hook(info);
    }));

    let result = run_inner(settings, styles, pending);
    // Restore terminal state (idempotent for the early-error paths).
    let _ = disable_raw_mode();
    let _ = execute!(io::stdout(), LeaveAlternateScreen);
    let _ = execute!(io::stdout(), crossterm::cursor::Show);
    result
}

fn run_inner(settings: Settings, styles: AppStyles, pending: PendingCommand) -> Result<()> {
    enable_raw_mode()?;
    let mut stdout: Stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    // Creating the SQLite provider can fail (bad file etc.); on error the
    // caller restores the terminal before the error reaches main.
    let provider: Box<dyn DataProvider> = match settings.backend_type {
        BackendType::Json => Box::new(JsonDataProvider::new(settings.json_backend.file_path.clone())),
        BackendType::Sqlite => Box::new(SqliteDataProvider::new(settings.sqlite_backend.file_path.clone())?),
    };

    let mut app = App {
        settings,
        styles,
        provider,
        entries: Vec::new(),
        displayed: Vec::new(),
        list_state: ListState::default(),
        focus: Focus::EntriesList,
        editor: Editor::default(),
        full_screen: false,
        multi_select: false,
        multi_selected: HashSet::new(),
        filter: None,
        sort: SortOptions::default(),
        popups: Vec::new(),
        should_quit: false,
        undo_stack: Vec::new(),
        redo_stack: Vec::new(),
    };

    app.initial_load(&mut terminal, pending)?;

    loop {
        terminal.draw(|frame| ui::draw(frame, &mut app))?;
        if app.should_quit {
            break;
        }
        let event = event::read()?;
        match event {
            Event::Key(key) => {
                if key.kind == KeyEventKind::Release {
                    continue;
                }
                app.handle_key(key, &mut terminal)?;
            }
            Event::Mouse(_) => {}
            Event::Resize(_, _) => {}
            Event::Paste(text) => {
                app.handle_paste(text);
            }
            _ => {}
        }
    }
    Ok(())
}

// The remainder of the App implementation lives in app_impl.rs via include
// to keep this file manageable while preserving module privacy.
include!("app_impl.rs");
