impl Filter {
    pub fn is_active(&self) -> bool {
        !self.title.is_empty() || !self.content.is_empty() || self.priority.is_some() || !self.tags.is_empty()
    }
    pub fn matches(&self, entry: &Entry) -> bool {
        let mut preds: Vec<bool> = Vec::new();
        if !self.title.is_empty() {
            preds.push(entry.title.to_lowercase().contains(&self.title.to_lowercase()));
        }
        if !self.content.is_empty() {
            preds.push(entry.content.to_lowercase().contains(&self.content.to_lowercase()));
        }
        if let Some(p) = self.priority {
            preds.push(entry.priority == Some(p));
        }
        for tag in &self.tags {
