                preds.push(entry.tags.is_empty());
            } else {
                preds.push(entry.tags.iter().any(|t| t == tag));
            }
        }
        if preds.is_empty() {
            return true;
        }
        match self.logic {
            MatchingLogic::All => preds.iter().all(|b| *b),
            MatchingLogic::Any => preds.iter().any(|b| *b),
        }
    }
