// Implementation of App behaviour.  This file is included from mod.rs.

impl App {
    pub fn current_entry(&self) -> Option<&Entry> {
        let idx = self.list_state.selected()?;
        let pos = *self.displayed.get(idx)?;
        self.entries.get(pos)
    }

    pub fn current_entry_id(&self) -> Option<u32> {
        self.current_entry().map(|e| e.id)
    }

    fn entry_index_by_id(&self, id: u32) -> Option<usize> {
        self.entries.iter().position(|e| e.id == id)
    }

    pub fn all_tags(&self) -> Vec<String> {
        let mut set = std::collections::BTreeSet::new();
        for e in &self.entries {
            for t in &e.tags {
                set.insert(t.clone());
            }
        }
        let mut tags: Vec<String> = set.into_iter().collect();
        tags.sort();
        tags
    }

    pub fn is_filtered(&self) -> bool {
        self.filter.as_ref().map(|f| f.is_active()).unwrap_or(false)
    }

    pub fn editor_modified(&self) -> bool {
        match self.current_entry() {
            Some(entry) => self.editor.text() != entry.content,
            None => false,
        }
    }

    fn sort_displayed(&self, indices: &mut Vec<usize>) {
        let criteria = self.sort.criteria.clone();
        let descending = self.sort.order == SortOrder::Descending;
        let entries = &self.entries;
        indices.sort_by(|&a, &b| {
            let ea = &entries[a];
            let eb = &entries[b];
            let mut ord = std::cmp::Ordering::Equal;
            for crit in &criteria {
                ord = match crit {
                    SortCriterion::Date => ea.date.cmp(&eb.date),
                    SortCriterion::Title => ea.title.cmp(&eb.title),
                    SortCriterion::Priority => ea.priority.cmp(&eb.priority),
                };
                if ord != std::cmp::Ordering::Equal {
                    break;
                }
            }
            if descending { ord.reverse() } else { ord }
        });
    }

    pub fn refresh_displayed(&mut self, keep_selected_id: Option<u32>) {
        let previous_id = keep_selected_id.or_else(|| self.current_entry_id());
        let previous_index = self.list_state.selected().unwrap_or(0);
        let mut indices: Vec<usize> = self
            .entries
            .iter()
            .enumerate()
            .filter(|(_, e)| self.filter.as_ref().map(|f| f.matches(e)).unwrap_or(true))
            .map(|(i, _)| i)
            .collect();
        self.sort_displayed(&mut indices);
        self.displayed = indices;
        if self.displayed.is_empty() {
            self.list_state.select(None);
            self.editor.set_text("");
            return;
        }
        let selected = if let Some(id) = previous_id {
            self.displayed
                .iter()
                .position(|&pos| self.entries[pos].id == id)
                .unwrap_or_else(|| previous_index.min(self.displayed.len() - 1))
        } else {
            previous_index.min(self.displayed.len() - 1)
        };
        self.list_state.select(Some(selected));
        self.sync_editor_to_current();
    }

    fn sync_editor_to_current(&mut self) {
        let content = self.current_entry().map(|e| e.content.clone()).unwrap_or_default();
        let mode = self.editor.mode;
        self.editor.set_text(&content);
        // Reloading content lands in Normal mode unless callers explicitly
        // asked for Edit mode (they set it after selection change).
        self.editor.mode = if mode == EditorMode::Edit && self.focus == Focus::Editor {
            EditorMode::Normal
        } else {
            EditorMode::Normal
        };
    }

    fn set_selection_index(&mut self, idx: usize, sync_editor: bool) {
        if self.displayed.is_empty() {
            self.list_state.select(None);
            return;
        }
        let idx = idx.min(self.displayed.len() - 1);
        self.list_state.select(Some(idx));
        if sync_editor {
            self.sync_editor_to_current();
        }
    }

    fn select_entry_by_id(&mut self, id: u32) {
        if let Some(pos) = self.displayed.iter().position(|&p| self.entries[p].id == id) {
            self.list_state.select(Some(pos));
            self.sync_editor_to_current();
        }
    }

    fn load_entries_into_app(&mut self) -> Option<String> {
        log::trace!(target: "tjournal::app", "Loading entries");
        match self.provider.load_all_entries() {
            Ok(entries) => {
                self.entries = entries;
                self.refresh_displayed(None);
                None
            }
            Err(err) => {
                self.entries = Vec::new();
                self.refresh_displayed(None);
                Some(format!("{}", err))
            }
        }
    }

    fn initial_load(
        &mut self,
        terminal: &mut Terminal<CrosstermBackend<Stdout>>,
        pending: PendingCommand,
    ) -> Result<()> {
        let mut initial_error: Option<String> = self.load_entries_into_app();

        match pending {
            PendingCommand::None => {}
            PendingCommand::AssignPriority(priority) => {
                if let Err(err) = self.provider.assign_priority(priority) {
                    if initial_error.is_none() {
                        initial_error = Some(format!("{}", err));
                    }
                } else {
                    let err = self.load_entries_into_app();
                    if initial_error.is_none() {
                        initial_error = err;
                    }
                }
            }
            PendingCommand::Import(path) => {
                // Show the transient importing indicator once, as the
                // reference does while the import runs.
                self.popups.push(Popup::Loading("Importing journals...".to_owned()));
                let _ = terminal.draw(|frame| ui::draw(frame, self));
                self.popups.pop();
                if let Some(msg) = self.import_from_path(&path) {
                    initial_error = Some(msg);
                } else {
                    let err = self.load_entries_into_app();
                    if initial_error.is_none() {
                        initial_error = err;
                    }
                }
            }
        }

        if let Some(msg) = initial_error {
            self.popups.push(Popup::MsgBox(MsgBoxState::new(MsgBoxKind::Error, msg)));
