                set.insert(t.clone());
            }
        }
        let mut tags: Vec<String> = set.into_iter().collect();
        tags.sort();
        tags
    }

    pub fn is_filtered(&self) -> bool {
        self.filter.as_ref().map(|f| f.is_active()).unwrap_or(false)
    }

    pub fn editor_modified(&self) -> bool {
        match self.current_entry() {
            Some(entry) => self.editor.text() != entry.content,
            None => false,
        }
    }

    fn sort_displayed(&self, indices: &mut Vec<usize>) {
        let criteria = self.sort.criteria.clone();
        let descending = self.sort.order == SortOrder::Descending;
        let entries = &self.entries;
        indices.sort_by(|&a, &b| {
            let ea = &entries[a];
            let eb = &entries[b];
            let mut ord = std::cmp::Ordering::Equal;
            for crit in &criteria {
                ord = match crit {
                    SortCriterion::Date => ea.date.cmp(&eb.date),
                    SortCriterion::Title => ea.title.cmp(&eb.title),
                    SortCriterion::Priority => ea.priority.cmp(&eb.priority),
                };
                if ord != std::cmp::Ordering::Equal {
                    break;
                }
            }
            if descending { ord.reverse() } else { ord }
        });
    }

    pub fn refresh_displayed(&mut self, keep_selected_id: Option<u32>) {
        let previous_id = keep_selected_id.or_else(|| self.current_entry_id());
        let previous_index = self.list_state.selected().unwrap_or(0);
        let mut indices: Vec<usize> = self
            .entries
            .iter()
            .enumerate()
            .filter(|(_, e)| self.filter.as_ref().map(|f| f.matches(e)).unwrap_or(true))
            .map(|(i, _)| i)
            .collect();
        self.sort_displayed(&mut indices);
        self.displayed = indices;
        if self.displayed.is_empty() {
            self.list_state.select(None);
            self.editor.set_text("");
            return;
        }
        let selected = if let Some(id) = previous_id {
            self.displayed
                .iter()
                .position(|&pos| self.entries[pos].id == id)
                .unwrap_or_else(|| previous_index.min(self.displayed.len() - 1))
        } else {
            previous_index.min(self.displayed.len() - 1)
        };
        self.list_state.select(Some(selected));
        self.sync_editor_to_current();
    }

    fn sync_editor_to_current(&mut self) {
        let content = self.current_entry().map(|e| e.content.clone()).unwrap_or_default();
        let mode = self.editor.mode;
        self.editor.set_text(&content);
        // Reloading content lands in Normal mode unless callers explicitly
        // asked for Edit mode (they set it after selection change).
        self.editor.mode = if mode == EditorMode::Edit && self.focus == Focus::Editor {
            EditorMode::Normal
        } else {
            EditorMode::Normal
        };
    }

    fn set_selection_index(&mut self, idx: usize, sync_editor: bool) {
        if self.displayed.is_empty() {
            self.list_state.select(None);
            return;
        }
        let idx = idx.min(self.displayed.len() - 1);
        self.list_state.select(Some(idx));
        if sync_editor {
            self.sync_editor_to_current();
        }
    }

    fn select_entry_by_id(&mut self, id: u32) {
        if let Some(pos) = self.displayed.iter().position(|&p| self.entries[p].id == id) {
            self.list_state.select(Some(pos));
            self.sync_editor_to_current();
        }
    }

    fn load_entries_into_app(&mut self) -> Option<String> {
        log::trace!(target: "tjournal::app", "Loading entries");
        match self.provider.load_all_entries() {
            Ok(entries) => {
                self.entries = entries;
                self.refresh_displayed(None);
                None
            }
            Err(err) => {
                self.entries = Vec::new();
                self.refresh_displayed(None);
                Some(format!("{}", err))
            }
        }
    }

    fn initial_load(
        &mut self,
        terminal: &mut Terminal<CrosstermBackend<Stdout>>,
        pending: PendingCommand,
    ) -> Result<()> {
        let mut initial_error: Option<String> = self.load_entries_into_app();

        match pending {
            PendingCommand::None => {}
            PendingCommand::AssignPriority(priority) => {
                if let Err(err) = self.provider.assign_priority(priority) {
                    if initial_error.is_none() {
                        initial_error = Some(format!("{}", err));
                    }
                } else {
                    let err = self.load_entries_into_app();
                    if initial_error.is_none() {
                        initial_error = err;
                    }
                }
            }
            PendingCommand::Import(path) => {
                // Show the transient importing indicator once, as the
                // reference does while the import runs.
                self.popups.push(Popup::Loading("Importing journals...".to_owned()));
                let _ = terminal.draw(|frame| ui::draw(frame, self));
                self.popups.pop();
                if let Some(msg) = self.import_from_path(&path) {
                    initial_error = Some(msg);
                } else {
                    let err = self.load_entries_into_app();
                    if initial_error.is_none() {
                        initial_error = err;
                    }
                }
            }
        }

        if let Some(msg) = initial_error {
            self.popups.push(Popup::MsgBox(MsgBoxState::new(MsgBoxKind::Error, msg)));
        }
        Ok(())
    }

    fn import_from_path(&mut self, path: &PathBuf) -> Option<String> {
        if !path.exists() {
            return Some(format!("Import file doesn't exist: path {}", path.display()));
        }
        let content = match std::fs::read_to_string(path) {
            Ok(c) => c,
            Err(err) => return Some(format!("{}", err)),
        };
        let dto: EntriesDTO = match serde_json::from_str(&content) {
            Ok(d) => d,
            Err(err) => {
                return Some(format!("Error while parsing import file. Error: {}", err));
            }
        };
        match self.provider.import_entries(dto.entries) {
            Ok(_) => None,
            Err(err) => Some(format!("{}", err)),
        }
    }

    fn show_error(&mut self, msg: impl Into<String>) {
        self.popups.push(Popup::MsgBox(MsgBoxState::new(MsgBoxKind::Error, msg)));
    }
    fn show_info(&mut self, msg: impl Into<String>) {
        self.popups.push(Popup::MsgBox(MsgBoxState::new(MsgBoxKind::Info, msg)));
    }

    // ---------- history ----------
    fn snapshot_now(&self) -> Snapshot {
        Snapshot { entries: self.entries.clone(), selected_id: self.current_entry_id() }
    }
    fn push_history_before_change(&mut self) {
        let limit = self.settings.history_limit;
        if limit == 0 {
            self.undo_stack.clear();
            self.redo_stack.clear();
            return;
        }
        let snap = self.snapshot_now();
        self.undo_stack.push(snap);
        while self.undo_stack.len() > limit {
            self.undo_stack.remove(0);
        }
        self.redo_stack.clear();
    }

    fn apply_snapshot(&mut self, target: Snapshot) -> Result<()> {
        // Apply a target snapshot by diffing it against the current state,
        // using the provider's add/remove/update operations.  Re-created
        // entries receive fresh ids from the provider.
        let current = self.entries.clone();
        let current_ids: HashSet<u32> = current.iter().map(|e| e.id).collect();
        let target_ids: HashSet<u32> = target.entries.iter().map(|e| e.id).collect();
        let mut id_map: std::collections::HashMap<u32, u32> = std::collections::HashMap::new();

        // Remove entries that are not in the target.
        for entry in &current {
            if !target_ids.contains(&entry.id) {
                self.provider.remove_entry(entry.id)?;
            }
        }
        // Update entries present in both whose data differs.
        for t in &target.entries {
            if let Some(cur) = current.iter().find(|e| e.id == t.id) {
                if cur != t {
                    self.provider.update_entry(t)?;
                }
                id_map.insert(t.id, t.id);
            }
        }
        // Retained entries keep their current in-memory order; restored
        // entries are appended.
        let mut new_entries: Vec<Entry> = Vec::new();
        for entry in &current {
            if target_ids.contains(&entry.id) {
                if let Some(t) = target.entries.iter().find(|e| e.id == entry.id) {
                    new_entries.push(t.clone());
                }
            }
        }
        for t in &target.entries {
            if !current_ids.contains(&t.id) {
                let created = self.provider.add_entry(EntryDraft::from(t))?;
                id_map.insert(t.id, created.id);
                new_entries.push(created);
            }
        }
        self.entries = new_entries;
        let selected = target
            .selected_id
            .and_then(|id| id_map.get(&id).copied());
        // Keep filters etc., reselect by mapped id.
        let keep = selected;
        self.list_state.select(Some(0));
        self.refresh_displayed(keep);
        if let Some(id) = keep {
            self.select_entry_by_id(id);
        }
        Ok(())
    }

    fn undo(&mut self) {
        if let Some(target) = self.undo_stack.pop() {
            let current = self.snapshot_now();
            match self.apply_snapshot(target) {
                Ok(()) => {
                    self.redo_stack.push(current);
                }
                Err(err) => self.show_error(format!("{}", err)),
            }
        }
    }
    fn redo(&mut self) {
        if let Some(target) = self.redo_stack.pop() {
            let current = self.snapshot_now();
            match self.apply_snapshot(target) {
                Ok(()) => {
                    self.undo_stack.push(current);
                    let limit = self.settings.history_limit;
                    if limit > 0 {
                        while self.undo_stack.len() > limit { self.undo_stack.remove(0); }
                    }
                }
                Err(err) => self.show_error(format!("{}", err)),
            }
        }
    }

    // ---------- persistence helpers ----------
    fn save_current_content(&mut self) -> bool {
        // Returns true on success (or nothing to save).
        let Some(entry) = self.current_entry().cloned() else { return true };
        let new_content = self.editor.text();
        if new_content == entry.content {
            return true;
        }
        let mut updated = entry.clone();
        updated.content = new_content;
        // The history snapshot is pushed by the caller when going through
        // the Save command; here we do it directly if not already.
        match self.provider.update_entry(&updated) {
            Ok(()) => {
                if let Some(slot) = self.entries.iter_mut().find(|e| e.id == updated.id) {
                    *slot = updated;
                }
                true
            }
            Err(err) => {
                self.show_error(format!("{}", err));
                false
            }
        }
    }

    fn discard_editor_changes(&mut self) {
        self.sync_editor_to_current();
    }

    /// If there are unsaved changes, show the save prompt and remember the
    /// action to run afterwards.  Returns true when the caller must stop.
    fn needs_save_guard(&mut self, action: PendingAction) -> bool {
        if self.editor_modified() {
            let mut box_ = MsgBoxState::new(
                MsgBoxKind::QuestionCancel,
                "Do you want to save the changes on the current journal?",
            );
            box_.action = MsgBoxAction::SaveChangesPending(Box::new(action));
            self.popups.push(Popup::MsgBox(box_));
            true
        } else {
            false
        }
    }

    // ---------- paste ----------
    pub fn handle_paste(&mut self, text: String) {
        if let Some(popup) = self.popups.last_mut() {
            match popup {
                Popup::Entry(state) => {
                    for ch in text.chars() {
                        if ch != '\n' && ch != '\r' {
                            state.focused_input_mut().insert_char(ch);
                        }
                    }
                    return;
                }
                Popup::Filter(state) => {
                    let input = match state.focus {
                        0 => &mut state.title,
                        1 => &mut state.content,
                        2 => &mut state.priority,
                        _ => return,
                    };
                    for ch in text.chars() {
                        if ch != '\n' && ch != '\r' { input.insert_char(ch); }
                    }
                    return;
                }
                Popup::Fuzzy(state) => {
                    for ch in text.chars() {
                        if ch != '\n' && ch != '\r' { state.query.insert_char(ch); }
                    }
                    self.update_fuzzy_results();
                    return;
                }
                Popup::Export(state) => {
                    for ch in text.chars() {
                        if ch != '\n' && ch != '\r' { state.path.insert_char(ch); }
                    }
                    return;
                }
                _ => return,
            }
        }
        if self.focus == Focus::Editor && self.editor.mode == EditorMode::Edit {
            self.editor.insert_str(&text);
        }
    }

    // ---------- top-level key handling ----------
    pub fn handle_key(
        &mut self,
        key: KeyEvent,
        terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    ) -> Result<()> {
        if !self.popups.is_empty() {
            // The Tags popup is hosted on top of the Entry popup.
            let is_tags = matches!(self.popups.last(), Some(Popup::Tags(_)));
            if is_tags {
                self.handle_tags_key(key);
            } else {
                self.handle_popup_key(key, terminal)?;
            }
            return Ok(());
        }
        if self.multi_select {
            self.handle_multi_key(key);
            return Ok(());
        }
        self.handle_main_key(key, terminal)
    }
}
