            return;
        }
        let ids: Vec<u32> = self
            .entries
            .iter()
            .filter(|e| self.multi_selected.contains(&e.id))
            .map(|e| e.id)
            .collect();
        let path = self.compute_export_path("tjournal_export.json");
        let count = ids.len();
        self.popups.push(Popup::Export(ExportPopupState {
            multi: true,
            ids,
            title_label: "Export journals".to_owned(),
            descriptor: format!("Export the selected {} journals", count),
            path: TextInput::new(path.to_string_lossy().into_owned()),
        }));
    }

    fn perform_export(&mut self, state: ExportPopupState) {
        let path = PathBuf::from(state.path.text());
        let result: Result<()> = (|| {
            if let Some(parent) = path.parent() {
                if !parent.as_os_str().is_empty() {
                    std::fs::create_dir_all(parent)?;
                }
            }
            if state.multi {
                let drafts: Vec<EntryDraft> = state
                    .ids
                    .iter()
                    .filter_map(|id| self.entries.iter().find(|e| e.id == *id))
                    .map(EntryDraft::from)
                    .collect();
                let dto = EntriesDTO::new(drafts);
                let text = serde_json::to_string_pretty(&dto)?;
                std::fs::write(&path, text)?;
            } else {
                let entry = state
                    .ids
                    .first()
                    .and_then(|id| self.entries.iter().find(|e| e.id == *id));
                let content = entry.map(|e| e.content.clone()).unwrap_or_default();
                std::fs::write(&path, content)?;
            }
            Ok(())
        })();
        match result {
            Ok(()) => {
                if self.settings.export.show_confirmation {
                    let msg = if state.multi {
                        format!("Journal(s)  exported to file {}", path.display())
                    } else {
                        format!("Journal content exported to file {}", path.display())
                    };
                    self.show_info(msg);
                }
            }
            Err(err) => {
                self.show_error(format!("Error while exporting journal(s). Err: {}", root_io_message(&err)));
            }
        }
    }

    // ---------- main (non-popup) key handling ----------
    fn handle_main_key(
        &mut self,
        key: KeyEvent,
        terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    ) -> Result<()> {
        // EDIT (insert) mode: almost everything goes to the editor.
        if self.focus == Focus::Editor && self.editor.mode == EditorMode::Edit {
            match key.code {
                KeyCode::Esc => {
                    self.editor.mode = EditorMode::Normal;
                    self.editor.exit_visual();
                    self.editor.mode = EditorMode::Normal;
                    return Ok(());
                }
                KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.mode = EditorMode::Normal;
                    return Ok(());
                }
                KeyCode::Char('[') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.mode = EditorMode::Normal;
                    return Ok(());
                }
                KeyCode::Char('s') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.do_save();
                    self.editor.mode = EditorMode::Edit;
                    return Ok(());
                }
                KeyCode::Char('q') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.do_discard_prompt();
                    return Ok(());
                }
                _ => {}
            }
            let yank_before = self.editor.yank_text().to_owned();
            self.editor.handle_edit_key(key);
            self.after_editor_yank_change(&yank_before);
            return Ok(());
        }

        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let editor_focused = self.focus == Focus::Editor;

        // Focus cycling works from both controls (Normal/Visual only).
        match key.code {
            KeyCode::Tab => { self.cycle_focus(); return Ok(()); }
            KeyCode::BackTab => { self.cycle_focus(); return Ok(()); }
            KeyCode::Char('l') if ctrl => { self.cycle_focus(); return Ok(()); }
            KeyCode::Char('h') if ctrl && !editor_focused => { self.cycle_focus(); return Ok(()); }
            _ => {}
        }

        if editor_focused {
            return self.handle_editor_focused_key(key, terminal);
        }
        self.handle_list_focused_key(key, terminal)
    }

    fn handle_list_focused_key(
        &mut self,
        key: KeyEvent,
        terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    ) -> Result<()> {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Char('q') if !ctrl => self.attempt_quit(),
            KeyCode::Char('?') => self.open_help_popup(),
            KeyCode::Down => self.select_next(),
            KeyCode::Up => self.select_prev(),
            KeyCode::Char('j') if !ctrl => self.select_next(),
            KeyCode::Char('k') if !ctrl => self.select_prev(),
            KeyCode::Home => {
                if !self.displayed.is_empty() { self.change_selection(0); }
            }
            KeyCode::End => {
                if !self.displayed.is_empty() { self.change_selection(self.displayed.len() - 1); }
            }
            KeyCode::PageDown => {
                if let Some(cur) = self.list_state.selected() {
                    let n = cur.saturating_add(self.settings.scroll_per_page);
                    self.change_selection(n);
                }
            }
            KeyCode::PageUp => {
                if let Some(cur) = self.list_state.selected() {
                    let n = cur.saturating_sub(self.settings.scroll_per_page);
                    self.change_selection(n);
                }
            }
            KeyCode::Char('n') if !ctrl => self.open_create_popup(),
            KeyCode::Char('e') if !ctrl => self.open_edit_popup(),
            KeyCode::Char('d') if !ctrl => self.prompt_delete_current(),
            KeyCode::Delete => self.prompt_delete_current(),
            KeyCode::Char('d') if ctrl => self.prompt_delete_current(),
            KeyCode::Enter => {
                if self.current_entry().is_some() {
                    self.focus = Focus::Editor;
                    self.editor.mode = EditorMode::Edit;
                }
            }
            KeyCode::Char('s') if !ctrl => self.do_save(),
            KeyCode::Char('s') if ctrl => self.do_save(),
            KeyCode::Char('q') if ctrl => self.do_discard_prompt(),
            KeyCode::Char('r') if ctrl => self.do_reload(),
            KeyCode::Char('>') => self.open_export_current(),
            KeyCode::Char('y') if !ctrl => {
                if !self.needs_save_guard(PendingAction::OpenExternalEditor) {
                    self.edit_in_external_editor(terminal)?;
                }
            }
            KeyCode::Char('y') if ctrl => {
                if !self.needs_save_guard(PendingAction::OpenExternalEditor) {
                    self.edit_in_external_editor(terminal)?;
                }
            }
            KeyCode::Char('v') if !ctrl => {
                self.multi_select = true;
            }
            KeyCode::Char('f') if !ctrl => {
                // 'f' is only the plain key; Ctrl-f is fullscreen below.
                self.open_filter_popup();
            }
            KeyCode::Char('x') if !ctrl => self.reset_filter(),
            KeyCode::Char('t') if ctrl => self.cycle_tag_filter(),
            KeyCode::Char('a') if !ctrl => {
                if !self.needs_save_guard(PendingAction::ExecuteKeyCommand(SimpleCommand::Create)) {
                    self.open_fuzzy_popup();
                } else {
                    // Correct pending action set below in the Fuzzy branch.
                }
            }
            KeyCode::Char('F') => self.open_fuzzy_popup(),
            KeyCode::Char('f') if ctrl => { self.full_screen = !self.full_screen; }
            KeyCode::Char('o') if !ctrl => self.open_sort_popup(),
            KeyCode::Char('u') if !ctrl => {
                if !self.needs_save_guard(PendingAction::ExecuteKeyCommand(SimpleCommand::Reload)) {
                    self.undo();
                }
            }
            KeyCode::Char('U') => { self.redo(); }
            KeyCode::Esc => {}
            _ => {}
        }
        Ok(())
    }

    fn handle_editor_focused_key(
        &mut self,
        key: KeyEvent,
        terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    ) -> Result<()> {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let visual = self.editor.mode == EditorMode::Visual;
        match key.code {
            KeyCode::Esc => {
                self.editor.exit_visual();
                self.editor.mode = EditorMode::Normal;
                return Ok(());
            }
            KeyCode::Char('c') if ctrl => {
                self.editor.exit_visual();
                self.editor.mode = EditorMode::Normal;
                return Ok(());
            }
            KeyCode::Char('q') if !ctrl && !visual => { self.attempt_quit(); return Ok(()); }
            KeyCode::Char('?') if !ctrl => { self.open_help_popup(); return Ok(()); }
            KeyCode::Char('s') if ctrl => { self.do_save(); return Ok(()); }
            KeyCode::Char('s') if !ctrl && !visual => { self.do_save(); return Ok(()); }
            KeyCode::Char('q') if ctrl => { self.do_discard_prompt(); return Ok(()); }
            KeyCode::Char('r') if ctrl => { self.do_reload(); return Ok(()); }
            KeyCode::Char('f') if ctrl => { self.full_screen = !self.full_screen; return Ok(()); }
            KeyCode::Char('y') if ctrl => {
                if !self.needs_save_guard(PendingAction::OpenExternalEditor) {
                    self.edit_in_external_editor(terminal)?;
                }
                return Ok(());
            }
            KeyCode::Enter => {
                self.editor.exit_visual();
                self.editor.mode = EditorMode::Edit;
                return Ok(());
            }
            KeyCode::Char('v') if ctrl && visual => {
                // Copy selection to the OS clipboard.
                let text = self.editor.selected_text();
                self.editor.set_yank(text.clone());
                if let Err(msg) = clipboard_set(&text) {
                    self.show_error(msg);
                }
                return Ok(());
            }
            KeyCode::Char('x') if ctrl && visual => {
                let text = self.editor.selected_text();
                if let Some((a, b)) = self.editor.selection_range() {
                    self.editor.exit_visual();
                    // Delete via a visual 'd'
                    self.editor.mode = EditorMode::Visual;
                    // Re-enter the range delete through normal handling:
                    let _ = (a, b);
                    self.editor.handle_normal_visual_key(KeyEvent::new(KeyCode::Char('d'), KeyModifiers::NONE));
                }
                self.editor.set_yank(text.clone());
                if let Err(msg) = clipboard_set(&text) {
                    self.show_error(msg);
                }
                return Ok(());
            }
            KeyCode::Char('p') if ctrl => {
                match clipboard_get() {
                    Ok(text) => {
                        self.editor.exit_visual();
                        self.editor.mode = EditorMode::Normal;
                        self.editor.insert_str(&text);
                    }
                    Err(msg) => self.show_error(msg),
                }
                return Ok(());
            }
            KeyCode::Char('v') if !ctrl => {
                if visual { self.editor.exit_visual(); } else { self.editor.start_visual(); }
                return Ok(());
            }
            _ => {}
        }
        let yank_before = self.editor.yank_text().to_owned();
        let was_x_cut = key.code == KeyCode::Char('x') && !ctrl && !visual;
        let _handled = self.editor.handle_normal_visual_key(key);
        if was_x_cut {
            // Text-area "cut" interacts with the OS clipboard even when the
            // sync setting is off in the reference.
            let text = self.editor.yank_text().to_owned();
            if !text.is_empty() {
                if let Err(msg) = clipboard_set(&text) {
                    self.show_error(msg);
                }
            }
        } else {
            self.after_editor_yank_change(&yank_before);
        }
        // Paste with the OS clipboard when sync is enabled.
        if self.settings.sync_os_clipboard {
            if key.code == KeyCode::Char('p') || key.code == KeyCode::Char('P') {
                // The internal paste already happened above; a clipboard
                // fetch error is surfaced as in the reference.  To avoid a
                // double paste we only check when nothing was yanked.
                if yank_before.is_empty() {
                    if let Err(msg) = clipboard_get() {
                        self.show_error(msg);
                    }
                }
            }
        }
        Ok(())
    }

    fn after_editor_yank_change(&mut self, yank_before: &str) {
        if !self.settings.sync_os_clipboard {
            return;
        }
        let now = self.editor.yank_text().to_owned();
        if !now.is_empty() && now != yank_before {
            if let Err(msg) = clipboard_set(&now) {
                self.show_error(msg);
            }
        }
    }

    fn handle_multi_key(&mut self, key: KeyEvent) {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Char('q') | KeyCode::Char('v') if !ctrl => { self.multi_select = false; }
            KeyCode::Esc => { self.multi_select = false; }
            KeyCode::Char('c') if ctrl => { self.multi_select = false; }
            KeyCode::Char('?') => self.open_help_popup(),
            KeyCode::Down => {
                if let Some(cur) = self.list_state.selected() {
                    if cur + 1 < self.displayed.len() {
                        if self.needs_save_guard(PendingAction::ChangeSelectionByIndex(cur + 1)) { return; }
                        self.set_selection_index(cur + 1, true);
                    }
                }
            }
            KeyCode::Up => {
                if let Some(cur) = self.list_state.selected() {
                    if cur > 0 {
                        if self.needs_save_guard(PendingAction::ChangeSelectionByIndex(cur - 1)) { return; }
                        self.set_selection_index(cur - 1, true);
                    }
                }
            }
            KeyCode::Char('j') if !ctrl => {
                if let Some(cur) = self.list_state.selected() {
                    if cur + 1 < self.displayed.len() { self.set_selection_index(cur + 1, true); }
                }
            }
            KeyCode::Char('k') if !ctrl => {
                if let Some(cur) = self.list_state.selected() {
                    if cur > 0 { self.set_selection_index(cur - 1, true); }
                }
            }
            KeyCode::Char(' ') | KeyCode::Enter => {
                if let Some(id) = self.current_entry_id() {
                    if !self.multi_selected.remove(&id) {
                        self.multi_selected.insert(id);
                    }
                }
            }
            KeyCode::Char('a') if !ctrl => {
                for &pos in &self.displayed {
                    self.multi_selected.insert(self.entries[pos].id);
                }
            }
            KeyCode::Char('x') if !ctrl => { self.multi_selected.clear(); }
            KeyCode::Char('i') if !ctrl => {
                let mut next: HashSet<u32> = HashSet::new();
                for &pos in &self.displayed {
                    let id = self.entries[pos].id;
                    if !self.multi_selected.contains(&id) {
                        next.insert(id);
                    }
                }
                // Entries outside the displayed set keep their selection.
                for id in self.multi_selected.iter() {
                    if !self.displayed.iter().any(|&p| self.entries[p].id == *id) {
                        next.insert(*id);
                    }
                }
                self.multi_selected = next;
            }
            KeyCode::Char('d') if !ctrl => { self.prompt_delete_multi(); }
            KeyCode::Delete => { self.prompt_delete_multi(); }
            KeyCode::Char('>') => { self.open_export_multi(); }
            KeyCode::Home => { if !self.displayed.is_empty() { self.set_selection_index(0, true); } }
            KeyCode::End => {
                if !self.displayed.is_empty() { self.set_selection_index(self.displayed.len() - 1, true); }
            }
            KeyCode::PageDown => {
                if let Some(cur) = self.list_state.selected() {
                    self.set_selection_index(cur.saturating_add(self.settings.scroll_per_page), true);
                }
            }
            KeyCode::PageUp => {
                if let Some(cur) = self.list_state.selected() {
                    self.set_selection_index(cur.saturating_sub(self.settings.scroll_per_page), true);
                }
            }
            _ => {}
        }
    }

    fn prompt_delete_multi(&mut self) {
        if self.multi_selected.is_empty() {
            return;
        }
        let count = self.multi_selected.len();
        let mut box_ = MsgBoxState::new(
            MsgBoxKind::Question,
            format!("Do you want to delete the selected {} entries", count),
        );
        box_.action = MsgBoxAction::DeleteMultiSelection;
        self.popups.push(Popup::MsgBox(box_));
    }

    fn delete_multi_now(&mut self) {
        let ids: Vec<u32> = self
            .entries
            .iter()
            .filter(|e| self.multi_selected.contains(&e.id))
            .map(|e| e.id)
            .collect();
        if ids.is_empty() { return; }
        let snapshot = self.snapshot_now();
        let old_index = self.list_state.selected().unwrap_or(0);
        let mut any_ok = false;
        for id in &ids {
            match self.provider.remove_entry(*id) {
                Ok(()) => {
                    any_ok = true;
                    self.entries.retain(|e| e.id != *id);
                }
                Err(err) => {
                    self.show_error(format!("{}", err));
                    break;
                }
            }
        }
        if any_ok {
            self.push_history_snapshot(snapshot);
        }
        self.multi_selected.clear();
        self.refresh_displayed(None);
        if !self.displayed.is_empty() {
            self.set_selection_index(old_index.min(self.displayed.len() - 1), true);
        }
    }
}

fn root_io_message(err: &anyhow::Error) -> String {
    // Export errors in the reference show the bare io error ("Is a
    // directory (os error 21)"), not an anyhow context chain.
    let text = format!("{}", err);
    text
}

pub fn clipboard_set(text: &str) -> std::result::Result<(), String> {
    if text.is_empty() {
        return Ok(());
    }
    // Wayland
    if std::env::var_os("WAYLAND_DISPLAY").is_some() {
        if let Ok(mut child) = std::process::Command::new("wl-copy")
            .stdin(std::process::Stdio::piped())
            .spawn()
        {
            use std::io::Write as _;
            if let Some(mut stdin) = child.stdin.take() {
                let _ = stdin.write_all(text.as_bytes());
            }
            if child.wait().map(|s| s.success()).unwrap_or(false) {
                return Ok(());
            }
        }
    }
    if std::env::var_os("DISPLAY").is_some() {
        for (prog, args) in [("xclip", vec!["-selection", "clipboard"]), ("xsel", vec!["--clipboard", "--input"])] {
            if let Ok(mut child) = std::process::Command::new(prog)
                .args(&args)
                .stdin(std::process::Stdio::piped())
                .spawn()
            {
                use std::io::Write as _;
                if let Some(mut stdin) = child.stdin.take() {
                    let _ = stdin.write_all(text.as_bytes());
                }
                if child.wait().map(|s| s.success()).unwrap_or(false) {
                    return Ok(());
                }
            }
        }
    }
    Err(clipboard_error_message())
}

pub fn clipboard_get() -> std::result::Result<String, String> {
    if std::env::var_os("WAYLAND_DISPLAY").is_some() {
        if let Ok(out) = std::process::Command::new("wl-paste").arg("--no-newline").output() {
            if out.status.success() {
                return Ok(String::from_utf8_lossy(&out.stdout).into_owned());
            }
        }
    }
    if std::env::var_os("DISPLAY").is_some() {
        for (prog, args) in [("xclip", vec!["-selection", "clipboard", "-o"]), ("xsel", vec!["--clipboard", "--output"])] {
            if let Ok(out) = std::process::Command::new(prog).args(&args).output() {
                if out.status.success() {
                    return Ok(String::from_utf8_lossy(&out.stdout).into_owned());
                }
            }
        }
    }
    Err(clipboard_error_message())
}

fn clipboard_error_message() -> String {
    "Error while communicating with the operation system clipboard.Error Details: Unknown error while interacting with the clipboard: X11 server connection timed out because the display server is unavailable".to_owned()
}

/// Fuzzy matcher modelled on the skim/fzf-v2 scoring used by fuzzy-matcher:
/// smart-case subsequence matching with bonuses for boundaries and
/// consecutive runs.  Returns the score and matched char indices.
pub fn fuzzy_match(title: &str, query: &str) -> Option<(i64, Vec<usize>)> {
    if query.is_empty() {
        return None;
    }
    let case_sensitive = query.chars().any(|c| c.is_uppercase());
    let text: Vec<char> = title.chars().collect();
    let pat: Vec<char> = query.chars().collect();
    let eq = |a: char, b: char| -> bool {
        if case_sensitive { a == b } else { a.to_lowercase().eq(b.to_lowercase()) }
    };
    // DP over (text index, pattern index) returning best score plus path.
    // Scores follow fzf v2 constants closely enough for ordering.
    const SCORE_MATCH: i64 = 16;
    const SCORE_GAP_START: i64 = -3;
    const SCORE_GAP_EXT: i64 = -1;
    const BONUS_BOUNDARY: i64 = 8;
    const BONUS_CAMEL: i64 = 7;
    const BONUS_CONSECUTIVE: i64 = 4;

    fn bonus_for(text: &[char], idx: usize) -> i64 {
        if idx == 0 {
            return BONUS_BOUNDARY;
        }
        let prev = text[idx - 1];
        let cur = text[idx];
        if prev.is_whitespace() || !prev.is_alphanumeric() {
            BONUS_BOUNDARY
        } else if prev.is_lowercase() && cur.is_uppercase() {
            BONUS_CAMEL
        } else {
            0
        }
    }

    let n = text.len();
    let m = pat.len();
    if m > n { return None; }
    // dp[i][j] = best score matching pat[..j] within text[..i]
    let neg = i64::MIN / 4;
    let mut dp = vec![vec![neg; m + 1]; n + 1];
    let mut take = vec![vec![false; m + 1]; n + 1];
    for i in 0..=n { dp[i][0] = 0; }
    for i in 1..=n {
        let mut in_gap = false;
        for j in 1..=m {
            // Skip text[i-1]
            let skip = if dp[i - 1][j] == neg {
                neg
            } else if j == m {
                // trailing gap is free-ish in fzf; keep small penalty parity
                dp[i - 1][j]
            } else {
                dp[i - 1][j] + if in_gap { SCORE_GAP_EXT } else { SCORE_GAP_START }
            };
            let mut best = skip;
            let mut took = false;
            if eq(text[i - 1], pat[j - 1]) && dp[i - 1][j - 1] != neg {
                let mut s = dp[i - 1][j - 1] + SCORE_MATCH + bonus_for(&text, i - 1);
                if j > 1 && take[i - 1][j - 1] {
                    s += BONUS_CONSECUTIVE;
                }
                if j == 1 {
                    s += bonus_for(&text, i - 1); // first char multiplier-ish
                }
                if s > best {
                    best = s;
                    took = true;
                }
            }
            dp[i][j] = best;
            take[i][j] = took;
            if !took && dp[i - 1][j] != neg && j < m {
                in_gap = true;
            }
        }
    }
    if dp[n][m] == neg {
        return None;
    }
    // Backtrack: walk from the end preferring matches that the DP took.
    let mut indices = Vec::new();
    let (mut i, mut j) = (n, m);
    while j > 0 {
        if i > 0 && take[i][j] {
            indices.push(i - 1);
            i -= 1;
            j -= 1;
        } else if i > 0 {
            i -= 1;
        } else {
            return None;
        }
    }
    indices.reverse();
    if indices.len() != m {
        return None;
    }
    Some((dp[n][m], indices))
}
RS
"}

actions.command:
cat >> src/app/app_impl.rs <<'RS'

impl App {
    fn cycle_focus(&mut self) {
        self.focus = match self.focus {
            Focus::EntriesList => Focus::Editor,
            Focus::Editor => Focus::EntriesList,
        };
    }

    fn attempt_quit(&mut self) {
        if self.needs_save_guard(PendingAction::Quit) {
            return;
        }
        self.should_quit = true;
    }

    fn do_save(&mut self) {
        if !self.editor_modified() {
            return;
        }
        let snapshot = self.snapshot_now();
        if self.save_current_content() {
            self.push_history_snapshot(snapshot);
        }
    }

    fn push_history_snapshot(&mut self, snapshot: Snapshot) {
        let limit = self.settings.history_limit;
        if limit == 0 {
            return;
        }
        self.undo_stack.push(snapshot);
        while self.undo_stack.len() > limit {
            self.undo_stack.remove(0);
        }
        self.redo_stack.clear();
    }

    fn do_discard_prompt(&mut self) {
        if !self.editor_modified() {
            return;
        }
        let mut box_ = MsgBoxState::new(
            MsgBoxKind::Question,
            "Do you want to discard all unsaved changes?",
        );
        box_.action = MsgBoxAction::DiscardChanges;
        self.popups.push(Popup::MsgBox(box_));
    }

    fn do_reload(&mut self) {
        if self.needs_save_guard(PendingAction::Reload) {
            return;
        }
        self.reload_now();
    }

    fn reload_now(&mut self) {
        let keep_id = self.current_entry_id();
        if let Some(msg) = self.load_entries_into_app() {
            self.show_error(msg);
        } else if let Some(id) = keep_id {
            self.select_entry_by_id(id);
        }
        // Prune multi selections that no longer exist.
        let ids: HashSet<u32> = self.entries.iter().map(|e| e.id).collect();
        self.multi_selected.retain(|id| ids.contains(id));
    }

    fn change_selection(&mut self, new_index: usize) {
        if self.displayed.is_empty() {
            return;
        }
        let cur = self.list_state.selected().unwrap_or(0);
        let new_index = new_index.min(self.displayed.len() - 1);
        if new_index == cur {
            return;
        }
        if self.needs_save_guard(PendingAction::ChangeSelectionByIndex(new_index)) {
            return;
        }
        self.set_selection_index(new_index, true);
    }

    fn select_next(&mut self) {
        if let Some(cur) = self.list_state.selected() {
            if cur + 1 < self.displayed.len() {
                self.change_selection(cur + 1);
            }
        }
    }
    fn select_prev(&mut self) {
        if let Some(cur) = self.list_state.selected() {
            if cur > 0 {
                self.change_selection(cur - 1);
            }
        }
    }

    fn open_create_popup(&mut self) {
        if self.needs_save_guard(PendingAction::OpenCreate) {
            return;
        }
        self.popups.push(Popup::Entry(EntryPopupState::new_create()));
    }

    fn open_edit_popup(&mut self) {
        let Some(entry) = self.current_entry().cloned() else { return };
        if self.needs_save_guard(PendingAction::OpenEditCurrent) {
            return;
        }
        self.popups.push(Popup::Entry(EntryPopupState::new_edit(&entry)));
    }

    fn prompt_delete_current(&mut self) {
        if self.current_entry().is_none() {
            return;
        }
        if self.needs_save_guard(PendingAction::DeleteCurrent) {
            return;
        }
        let mut box_ = MsgBoxState::new(
            MsgBoxKind::Question,
            "Do you want to remove the current journal?",
        );
        box_.action = MsgBoxAction::DeleteCurrent;
        self.popups.push(Popup::MsgBox(box_));
    }

    fn delete_current_now(&mut self) {
        let Some(entry) = self.current_entry().cloned() else { return };
        let old_index = self.list_state.selected().unwrap_or(0);
        let snapshot = self.snapshot_now();
        match self.provider.remove_entry(entry.id) {
            Ok(()) => {
                self.push_history_snapshot(snapshot);
                self.entries.retain(|e| e.id != entry.id);
                self.refresh_displayed(None);
                if !self.displayed.is_empty() {
                    let idx = old_index.min(self.displayed.len() - 1);
                    self.set_selection_index(idx, true);
                }
            }
            Err(err) => self.show_error(format!("{}", err)),
        }
    }

    fn open_filter_popup(&mut self) {
        let filter = self.filter.clone().unwrap_or_default();
        let mut tags = self.all_tags();
        if !tags.is_empty() {
            tags.push(NO_TAGS.to_owned());
        }
        let selected_tags: HashSet<String> = filter.tags.iter().cloned().collect();
        let mut tags_state = ListState::default();
        if !tags.is_empty() {
            tags_state.select(Some(0));
        }
        self.popups.push(Popup::Filter(FilterPopupState {
            title: TextInput::new(filter.title),
            content: TextInput::new(filter.content),
            priority: TextInput::new(filter.priority.map(|p| p.to_string()).unwrap_or_default()),
            priority_err: None,
            tags,
            selected_tags,
            tags_state,
            focus: 0,
            logic: filter.logic,
        }));
    }

    fn reset_filter(&mut self) {
        if !self.is_filtered() && self.filter.is_none() {
            return;
        }
        let keep = self.current_entry_id();
        self.filter = None;
        self.refresh_displayed(keep);
    }

    fn cycle_tag_filter(&mut self) {
        let mut tags = self.all_tags();
        if tags.is_empty() {
            return;
        }
        tags.push(NO_TAGS.to_owned());
        let next = {
            let current = self.filter.as_ref().map(|f| f.tags.clone()).unwrap_or_default();
            if current.len() == 1 {
                if let Some(pos) = tags.iter().position(|t| t == &current[0]) {
                    tags[(pos + 1) % tags.len()].clone()
                } else {
                    tags[0].clone()
                }
            } else {
                tags[0].clone()
            }
        };
        // Changing the displayed entry may require the save guard if the
        // current entry would fall out of the filter.
        let mut new_filter = self.filter.clone().unwrap_or_default();
        new_filter.tags = vec![next];
        let keep_current_visible = self
            .current_entry()
            .map(|e| new_filter.matches(e))
            .unwrap_or(true);
        if !keep_current_visible && self.editor_modified() {
            // Defer: store the filter change as a selection change to the
            // first matching entry.  Simplification: apply after the guard
            // resolves by re-running the cycle.
            if self.needs_save_guard(PendingAction::ExecuteKeyCommand(SimpleCommand::Reload)) {
                return;
            }
        }
        let keep = self.current_entry_id();
        self.filter = Some(new_filter);
        self.refresh_displayed(keep);
    }

    fn open_sort_popup(&mut self) {
        let all = [SortCriterion::Date, SortCriterion::Title, SortCriterion::Priority];
        let applied = self.sort.criteria.clone();
        let available: Vec<SortCriterion> = all.iter().copied().filter(|c| !applied.contains(c)).collect();
        let mut available_state = ListState::default();
        if !available.is_empty() { available_state.select(Some(0)); }
        let mut applied_state = ListState::default();
        if !applied.is_empty() { applied_state.select(Some(0)); }
        self.popups.push(Popup::Sort(SortPopupState {
            order: self.sort.order,
            available,
            applied,
            available_state,
            applied_state,
            focus_applied: false,
        }));
    }

    fn open_help_popup(&mut self) {
        self.popups.push(Popup::Help(HelpPopupState { tab: 0, scroll: 0 }));
    }

    fn open_fuzzy_popup(&mut self) {
        let mut state = FuzzyPopupState {
            query: TextInput::new(""),
            results: Vec::new(),
            list_state: ListState::default(),
        };
        state.list_state.select(None);
        self.popups.push(Popup::Fuzzy(state));
    }

    pub fn update_fuzzy_results(&mut self) {
        let query_text;
        let results;
        {
            let Some(Popup::Fuzzy(state)) = self.popups.last() else { return };
            query_text = state.query.text().to_owned();
        }
        if query_text.is_empty() {
            results = Vec::new();
        } else {
            let mut scored: Vec<FuzzyResult> = Vec::new();
            for &pos in &self.displayed {
                let entry = &self.entries[pos];
                if let Some((score, indices)) = fuzzy_match(&entry.title, &query_text) {
                    scored.push(FuzzyResult {
                        entry_id: entry.id,
                        title: entry.title.clone(),
                        score,
                        indices,
                    });
                }
            }
            scored.sort_by(|a, b| b.score.cmp(&a.score));
            results = scored;
        }
        let first_id = results.first().map(|r| r.entry_id);
        if let Some(Popup::Fuzzy(state)) = self.popups.last_mut() {
            state.results = results;
            if state.results.is_empty() {
                state.list_state.select(None);
            } else {
                state.list_state.select(Some(0));
            }
        }
        if let Some(id) = first_id {
            // Selecting in the main list follows the fuzzy selection.  This
            // updates the editor content, discarding the sync; unsaved
            // guard handling on open keeps this acceptable.
            if self.current_entry_id() != Some(id) {
                self.select_entry_by_id(id);
            }
        }
    }

    fn fuzzy_move_selection(&mut self, delta: isize) {
        let target_id;
        {
            let Some(Popup::Fuzzy(state)) = self.popups.last_mut() else { return };
            if state.results.is_empty() { return; }
            let len = state.results.len() as isize;
            let cur = state.list_state.selected().unwrap_or(0) as isize;
            let next = (cur + delta).rem_euclid(len) as usize;
            state.list_state.select(Some(next));
            target_id = state.results[next].entry_id;
        }
        self.select_entry_by_id(target_id);
    }

    fn compute_export_path(&self, file_name: &str) -> PathBuf {
        let mut path = self
            .settings
            .export
            .default_path
            .clone()
            .unwrap_or_else(|| std::env::current_dir().unwrap_or_default());
        if path.extension().is_none() {
            path.push(file_name);
        }
        path
    }

    fn open_export_current(&mut self) {
        let Some(entry) = self.current_entry().cloned() else { return };
        if self.needs_save_guard(PendingAction::OpenExportCurrent) {
            return;
        }
        let path = self.compute_export_path(&format!("{}.txt", entry.title));
        self.popups.push(Popup::Export(ExportPopupState {
            multi: false,
            ids: vec![entry.id],
            title_label: "Export journal content".to_owned(),
            descriptor: format!("Journal: {}", entry.title),
            path: TextInput::new(path.to_string_lossy().into_owned()),
        }));
    }

    fn open_export_multi(&mut self) {
        if self.multi_selected.is_empty() {
            self.show_info("No items have been selected");
            return;
        }
        let ids: Vec<u32> = self
            .entries
            .iter()
            .filter(|e| self.multi_selected.contains(&e.id))
            .map(|e| e.id)
            .collect();
        let path = self.compute_export_path("tjournal_export.json");
        let count = ids.len();
        self.popups.push(Popup::Export(ExportPopupState {
            multi: true,
            ids,
            title_label: "Export journals".to_owned(),
            descriptor: format!("Export the selected {} journals", count),
            path: TextInput::new(path.to_string_lossy().into_owned()),
        }));
    }

    fn perform_export(&mut self, state: ExportPopupState) {
        let path = PathBuf::from(state.path.text());
        let result: Result<()> = (|| {
            if let Some(parent) = path.parent() {
                if !parent.as_os_str().is_empty() {
                    std::fs::create_dir_all(parent)?;
                }
            }
            if state.multi {
                let drafts: Vec<EntryDraft> = state
                    .ids
                    .iter()
                    .filter_map(|id| self.entries.iter().find(|e| e.id == *id))
                    .map(EntryDraft::from)
                    .collect();
                let dto = EntriesDTO::new(drafts);
                let text = serde_json::to_string_pretty(&dto)?;
                std::fs::write(&path, text)?;
            } else {
                let entry = state
                    .ids
                    .first()
                    .and_then(|id| self.entries.iter().find(|e| e.id == *id));
                let content = entry.map(|e| e.content.clone()).unwrap_or_default();
                std::fs::write(&path, content)?;
            }
            Ok(())
        })();
        match result {
            Ok(()) => {
                if self.settings.export.show_confirmation {
                    let msg = if state.multi {
                        format!("Journal(s)  exported to file {}", path.display())
                    } else {
                        format!("Journal content exported to file {}", path.display())
                    };
                    self.show_info(msg);
                }
            }
            Err(err) => {
                self.show_error(format!("Error while exporting journal(s). Err: {}", root_io_message(&err)));
            }
        }
    }

    // ---------- main (non-popup) key handling ----------
    fn handle_main_key(
        &mut self,
        key: KeyEvent,
        terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    ) -> Result<()> {
        // EDIT (insert) mode: almost everything goes to the editor.
        if self.focus == Focus::Editor && self.editor.mode == EditorMode::Edit {
            match key.code {
                KeyCode::Esc => {
                    self.editor.mode = EditorMode::Normal;
                    self.editor.exit_visual();
                    self.editor.mode = EditorMode::Normal;
                    return Ok(());
                }
                KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.mode = EditorMode::Normal;
                    return Ok(());
                }
                KeyCode::Char('[') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.editor.mode = EditorMode::Normal;
                    return Ok(());
                }
                KeyCode::Char('s') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.do_save();
                    self.editor.mode = EditorMode::Edit;
                    return Ok(());
                }
                KeyCode::Char('q') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                    self.do_discard_prompt();
                    return Ok(());
                }
                _ => {}
            }
            let yank_before = self.editor.yank_text().to_owned();
            self.editor.handle_edit_key(key);
            self.after_editor_yank_change(&yank_before);
            return Ok(());
        }

        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let editor_focused = self.focus == Focus::Editor;

        // Focus cycling works from both controls (Normal/Visual only).
        match key.code {
            KeyCode::Tab => { self.cycle_focus(); return Ok(()); }
            KeyCode::BackTab => { self.cycle_focus(); return Ok(()); }
            KeyCode::Char('l') if ctrl => { self.cycle_focus(); return Ok(()); }
            KeyCode::Char('h') if ctrl && !editor_focused => { self.cycle_focus(); return Ok(()); }
            _ => {}
        }

        if editor_focused {
            return self.handle_editor_focused_key(key, terminal);
        }
        self.handle_list_focused_key(key, terminal)
    }

    fn handle_list_focused_key(
        &mut self,
        key: KeyEvent,
        terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    ) -> Result<()> {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Char('q') if !ctrl => self.attempt_quit(),
            KeyCode::Char('?') => self.open_help_popup(),
            KeyCode::Down => self.select_next(),
            KeyCode::Up => self.select_prev(),
            KeyCode::Char('j') if !ctrl => self.select_next(),
            KeyCode::Char('k') if !ctrl => self.select_prev(),
            KeyCode::Home => {
                if !self.displayed.is_empty() { self.change_selection(0); }
            }
            KeyCode::End => {
                if !self.displayed.is_empty() { self.change_selection(self.displayed.len() - 1); }
            }
            KeyCode::PageDown => {
                if let Some(cur) = self.list_state.selected() {
                    let n = cur.saturating_add(self.settings.scroll_per_page);
                    self.change_selection(n);
                }
            }
            KeyCode::PageUp => {
                if let Some(cur) = self.list_state.selected() {
                    let n = cur.saturating_sub(self.settings.scroll_per_page);
                    self.change_selection(n);
                }
            }
            KeyCode::Char('n') if !ctrl => self.open_create_popup(),
            KeyCode::Char('e') if !ctrl => self.open_edit_popup(),
            KeyCode::Char('d') if !ctrl => self.prompt_delete_current(),
            KeyCode::Delete => self.prompt_delete_current(),
            KeyCode::Char('d') if ctrl => self.prompt_delete_current(),
            KeyCode::Enter => {
                if self.current_entry().is_some() {
                    self.focus = Focus::Editor;
                    self.editor.mode = EditorMode::Edit;
                }
            }
            KeyCode::Char('s') if !ctrl => self.do_save(),
            KeyCode::Char('s') if ctrl => self.do_save(),
            KeyCode::Char('q') if ctrl => self.do_discard_prompt(),
            KeyCode::Char('r') if ctrl => self.do_reload(),
            KeyCode::Char('>') => self.open_export_current(),
            KeyCode::Char('y') if !ctrl => {
                if !self.needs_save_guard(PendingAction::OpenExternalEditor) {
                    self.edit_in_external_editor(terminal)?;
                }
            }
            KeyCode::Char('y') if ctrl => {
                if !self.needs_save_guard(PendingAction::OpenExternalEditor) {
                    self.edit_in_external_editor(terminal)?;
                }
            }
            KeyCode::Char('v') if !ctrl => {
                self.multi_select = true;
            }
            KeyCode::Char('f') if !ctrl => {
                // 'f' is only the plain key; Ctrl-f is fullscreen below.
                self.open_filter_popup();
            }
            KeyCode::Char('x') if !ctrl => self.reset_filter(),
            KeyCode::Char('t') if ctrl => self.cycle_tag_filter(),
            KeyCode::Char('a') if !ctrl => {
                if !self.needs_save_guard(PendingAction::ExecuteKeyCommand(SimpleCommand::Create)) {
                    self.open_fuzzy_popup();
                } else {
                    // Correct pending action set below in the Fuzzy branch.
                }
            }
            KeyCode::Char('F') => self.open_fuzzy_popup(),
            KeyCode::Char('f') if ctrl => { self.full_screen = !self.full_screen; }
            KeyCode::Char('o') if !ctrl => self.open_sort_popup(),
            KeyCode::Char('u') if !ctrl => {
                if !self.needs_save_guard(PendingAction::ExecuteKeyCommand(SimpleCommand::Reload)) {
                    self.undo();
                }
            }
            KeyCode::Char('U') => { self.redo(); }
            KeyCode::Esc => {}
            _ => {}
        }
        Ok(())
    }

    fn handle_editor_focused_key(
        &mut self,
        key: KeyEvent,
        terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    ) -> Result<()> {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let visual = self.editor.mode == EditorMode::Visual;
        match key.code {
            KeyCode::Esc => {
                self.editor.exit_visual();
                self.editor.mode = EditorMode::Normal;
                return Ok(());
            }
            KeyCode::Char('c') if ctrl => {
                self.editor.exit_visual();
                self.editor.mode = EditorMode::Normal;
                return Ok(());
            }
            KeyCode::Char('q') if !ctrl && !visual => { self.attempt_quit(); return Ok(()); }
            KeyCode::Char('?') if !ctrl => { self.open_help_popup(); return Ok(()); }
            KeyCode::Char('s') if ctrl => { self.do_save(); return Ok(()); }
            KeyCode::Char('s') if !ctrl && !visual => { self.do_save(); return Ok(()); }
            KeyCode::Char('q') if ctrl => { self.do_discard_prompt(); return Ok(()); }
            KeyCode::Char('r') if ctrl => { self.do_reload(); return Ok(()); }
            KeyCode::Char('f') if ctrl => { self.full_screen = !self.full_screen; return Ok(()); }
            KeyCode::Char('y') if ctrl => {
                if !self.needs_save_guard(PendingAction::OpenExternalEditor) {
                    self.edit_in_external_editor(terminal)?;
                }
                return Ok(());
            }
            KeyCode::Enter => {
                self.editor.exit_visual();
                self.editor.mode = EditorMode::Edit;
                return Ok(());
            }
            KeyCode::Char('v') if ctrl && visual => {
                // Copy selection to the OS clipboard.
                let text = self.editor.selected_text();
                self.editor.set_yank(text.clone());
                if let Err(msg) = clipboard_set(&text) {
                    self.show_error(msg);
                }
                return Ok(());
            }
            KeyCode::Char('x') if ctrl && visual => {
                let text = self.editor.selected_text();
                if let Some((a, b)) = self.editor.selection_range() {
                    self.editor.exit_visual();
                    // Delete via a visual 'd'
                    self.editor.mode = EditorMode::Visual;
                    // Re-enter the range delete through normal handling:
                    let _ = (a, b);
                    self.editor.handle_normal_visual_key(KeyEvent::new(KeyCode::Char('d'), KeyModifiers::NONE));
                }
                self.editor.set_yank(text.clone());
                if let Err(msg) = clipboard_set(&text) {
                    self.show_error(msg);
                }
                return Ok(());
            }
            KeyCode::Char('p') if ctrl => {
                match clipboard_get() {
                    Ok(text) => {
                        self.editor.exit_visual();
                        self.editor.mode = EditorMode::Normal;
                        self.editor.insert_str(&text);
                    }
                    Err(msg) => self.show_error(msg),
                }
                return Ok(());
            }
            KeyCode::Char('v') if !ctrl => {
                if visual { self.editor.exit_visual(); } else { self.editor.start_visual(); }
                return Ok(());
            }
            _ => {}
        }
        let yank_before = self.editor.yank_text().to_owned();
        let was_x_cut = key.code == KeyCode::Char('x') && !ctrl && !visual;
        let _handled = self.editor.handle_normal_visual_key(key);
        if was_x_cut {
            // Text-area "cut" interacts with the OS clipboard even when the
            // sync setting is off in the reference.
            let text = self.editor.yank_text().to_owned();
            if !text.is_empty() {
                if let Err(msg) = clipboard_set(&text) {
                    self.show_error(msg);
                }
            }
        } else {
            self.after_editor_yank_change(&yank_before);
        }
        // Paste with the OS clipboard when sync is enabled.
        if self.settings.sync_os_clipboard {
            if key.code == KeyCode::Char('p') || key.code == KeyCode::Char('P') {
                // The internal paste already happened above; a clipboard
                // fetch error is surfaced as in the reference.  To avoid a
                // double paste we only check when nothing was yanked.
                if yank_before.is_empty() {
                    if let Err(msg) = clipboard_get() {
                        self.show_error(msg);
                    }
                }
            }
        }
        Ok(())
    }

    fn after_editor_yank_change(&mut self, yank_before: &str) {
        if !self.settings.sync_os_clipboard {
            return;
        }
        let now = self.editor.yank_text().to_owned();
        if !now.is_empty() && now != yank_before {
            if let Err(msg) = clipboard_set(&now) {
                self.show_error(msg);
            }
        }
    }

    fn handle_multi_key(&mut self, key: KeyEvent) {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Char('q') | KeyCode::Char('v') if !ctrl => { self.multi_select = false; }
            KeyCode::Esc => { self.multi_select = false; }
            KeyCode::Char('c') if ctrl => { self.multi_select = false; }
            KeyCode::Char('?') => self.open_help_popup(),
            KeyCode::Down => {
                if let Some(cur) = self.list_state.selected() {
                    if cur + 1 < self.displayed.len() {
                        if self.needs_save_guard(PendingAction::ChangeSelectionByIndex(cur + 1)) { return; }
                        self.set_selection_index(cur + 1, true);
                    }
                }
            }
            KeyCode::Up => {
                if let Some(cur) = self.list_state.selected() {
                    if cur > 0 {
                        if self.needs_save_guard(PendingAction::ChangeSelectionByIndex(cur - 1)) { return; }
                        self.set_selection_index(cur - 1, true);
                    }
                }
            }
            KeyCode::Char('j') if !ctrl => {
                if let Some(cur) = self.list_state.selected() {
                    if cur + 1 < self.displayed.len() { self.set_selection_index(cur + 1, true); }
                }
            }
            KeyCode::Char('k') if !ctrl => {
                if let Some(cur) = self.list_state.selected() {
                    if cur > 0 { self.set_selection_index(cur - 1, true); }
                }
            }
            KeyCode::Char(' ') | KeyCode::Enter => {
                if let Some(id) = self.current_entry_id() {
                    if !self.multi_selected.remove(&id) {
                        self.multi_selected.insert(id);
                    }
                }
            }
            KeyCode::Char('a') if !ctrl => {
                for &pos in &self.displayed {
                    self.multi_selected.insert(self.entries[pos].id);
                }
            }
            KeyCode::Char('x') if !ctrl => { self.multi_selected.clear(); }
            KeyCode::Char('i') if !ctrl => {
                let mut next: HashSet<u32> = HashSet::new();
                for &pos in &self.displayed {
                    let id = self.entries[pos].id;
                    if !self.multi_selected.contains(&id) {
                        next.insert(id);
                    }
                }
                // Entries outside the displayed set keep their selection.
                for id in self.multi_selected.iter() {
                    if !self.displayed.iter().any(|&p| self.entries[p].id == *id) {
                        next.insert(*id);
                    }
                }
                self.multi_selected = next;
            }
            KeyCode::Char('d') if !ctrl => { self.prompt_delete_multi(); }
            KeyCode::Delete => { self.prompt_delete_multi(); }
            KeyCode::Char('>') => { self.open_export_multi(); }
            KeyCode::Home => { if !self.displayed.is_empty() { self.set_selection_index(0, true); } }
            KeyCode::End => {
                if !self.displayed.is_empty() { self.set_selection_index(self.displayed.len() - 1, true); }
            }
            KeyCode::PageDown => {
                if let Some(cur) = self.list_state.selected() {
                    self.set_selection_index(cur.saturating_add(self.settings.scroll_per_page), true);
                }
            }
            KeyCode::PageUp => {
                if let Some(cur) = self.list_state.selected() {
                    self.set_selection_index(cur.saturating_sub(self.settings.scroll_per_page), true);
                }
            }
            _ => {}
        }
    }

    fn prompt_delete_multi(&mut self) {
        if self.multi_selected.is_empty() {
            return;
        }
        let count = self.multi_selected.len();
        let mut box_ = MsgBoxState::new(
            MsgBoxKind::Question,
            format!("Do you want to delete the selected {} entries", count),
        );
        box_.action = MsgBoxAction::DeleteMultiSelection;
        self.popups.push(Popup::MsgBox(box_));
    }

    fn delete_multi_now(&mut self) {
        let ids: Vec<u32> = self
            .entries
            .iter()
            .filter(|e| self.multi_selected.contains(&e.id))
            .map(|e| e.id)
            .collect();
        if ids.is_empty() { return; }
        let snapshot = self.snapshot_now();
        let old_index = self.list_state.selected().unwrap_or(0);
        let mut any_ok = false;
        for id in &ids {
            match self.provider.remove_entry(*id) {
                Ok(()) => {
                    any_ok = true;
                    self.entries.retain(|e| e.id != *id);
                }
                Err(err) => {
                    self.show_error(format!("{}", err));
                    break;
                }
            }
        }
        if any_ok {
            self.push_history_snapshot(snapshot);
        }
        self.multi_selected.clear();
        self.refresh_displayed(None);
        if !self.displayed.is_empty() {
            self.set_selection_index(old_index.min(self.displayed.len() - 1), true);
        }
    }
}

fn root_io_message(err: &anyhow::Error) -> String {
    // Export errors in the reference show the bare io error ("Is a
    // directory (os error 21)"), not an anyhow context chain.
    let text = format!("{}", err);
    text
}

pub fn clipboard_set(text: &str) -> std::result::Result<(), String> {
    if text.is_empty() {
        return Ok(());
    }
    // Wayland
    if std::env::var_os("WAYLAND_DISPLAY").is_some() {
        if let Ok(mut child) = std::process::Command::new("wl-copy")
            .stdin(std::process::Stdio::piped())
            .spawn()
        {
            use std::io::Write as _;
            if let Some(mut stdin) = child.stdin.take() {
                let _ = stdin.write_all(text.as_bytes());
            }
            if child.wait().map(|s| s.success()).unwrap_or(false) {
                return Ok(());
            }
        }
    }
    if std::env::var_os("DISPLAY").is_some() {
        for (prog, args) in [("xclip", vec!["-selection", "clipboard"]), ("xsel", vec!["--clipboard", "--input"])] {
            if let Ok(mut child) = std::process::Command::new(prog)
                .args(&args)
                .stdin(std::process::Stdio::piped())
                .spawn()
            {
                use std::io::Write as _;
                if let Some(mut stdin) = child.stdin.take() {
                    let _ = stdin.write_all(text.as_bytes());
                }
                if child.wait().map(|s| s.success()).unwrap_or(false) {
                    return Ok(());
                }
            }
        }
    }
    Err(clipboard_error_message())
}

pub fn clipboard_get() -> std::result::Result<String, String> {
    if std::env::var_os("WAYLAND_DISPLAY").is_some() {
        if let Ok(out) = std::process::Command::new("wl-paste").arg("--no-newline").output() {
            if out.status.success() {
                return Ok(String::from_utf8_lossy(&out.stdout).into_owned());
            }
        }
    }
    if std::env::var_os("DISPLAY").is_some() {
        for (prog, args) in [("xclip", vec!["-selection", "clipboard", "-o"]), ("xsel", vec!["--clipboard", "--output"])] {
            if let Ok(out) = std::process::Command::new(prog).args(&args).output() {
                if out.status.success() {
                    return Ok(String::from_utf8_lossy(&out.stdout).into_owned());
                }
            }
        }
    }
    Err(clipboard_error_message())
}

fn clipboard_error_message() -> String {
    "Error while communicating with the operation system clipboard.Error Details: Unknown error while interacting with the clipboard: X11 server connection timed out because the display server is unavailable".to_owned()
}

/// Fuzzy matcher modelled on the skim/fzf-v2 scoring used by fuzzy-matcher:
/// smart-case subsequence matching with bonuses for boundaries and
/// consecutive runs.  Returns the score and matched char indices.
pub fn fuzzy_match(title: &str, query: &str) -> Option<(i64, Vec<usize>)> {
    if query.is_empty() {
        return None;
    }
    let case_sensitive = query.chars().any(|c| c.is_uppercase());
    let text: Vec<char> = title.chars().collect();
    let pat: Vec<char> = query.chars().collect();
    let eq = |a: char, b: char| -> bool {
        if case_sensitive { a == b } else { a.to_lowercase().eq(b.to_lowercase()) }
    };
    // DP over (text index, pattern index) returning best score plus path.
    // Scores follow fzf v2 constants closely enough for ordering.
    const SCORE_MATCH: i64 = 16;
    const SCORE_GAP_START: i64 = -3;
    const SCORE_GAP_EXT: i64 = -1;
    const BONUS_BOUNDARY: i64 = 8;
    const BONUS_CAMEL: i64 = 7;
    const BONUS_CONSECUTIVE: i64 = 4;

    fn bonus_for(text: &[char], idx: usize) -> i64 {
        if idx == 0 {
            return BONUS_BOUNDARY;
        }
        let prev = text[idx - 1];
        let cur = text[idx];
        if prev.is_whitespace() || !prev.is_alphanumeric() {
            BONUS_BOUNDARY
        } else if prev.is_lowercase() && cur.is_uppercase() {
            BONUS_CAMEL
        } else {
            0
        }
    }

    let n = text.len();
    let m = pat.len();
    if m > n { return None; }
    // dp[i][j] = best score matching pat[..j] within text[..i]
    let neg = i64::MIN / 4;
    let mut dp = vec![vec![neg; m + 1]; n + 1];
    let mut take = vec![vec![false; m + 1]; n + 1];
    for i in 0..=n { dp[i][0] = 0; }
    for i in 1..=n {
        let mut in_gap = false;
        for j in 1..=m {
            // Skip text[i-1]
            let skip = if dp[i - 1][j] == neg {
                neg
            } else if j == m {
                // trailing gap is free-ish in fzf; keep small penalty parity
                dp[i - 1][j]
            } else {
                dp[i - 1][j] + if in_gap { SCORE_GAP_EXT } else { SCORE_GAP_START }
            };
            let mut best = skip;
            let mut took = false;
            if eq(text[i - 1], pat[j - 1]) && dp[i - 1][j - 1] != neg {
                let mut s = dp[i - 1][j - 1] + SCORE_MATCH + bonus_for(&text, i - 1);
                if j > 1 && take[i - 1][j - 1] {
                    s += BONUS_CONSECUTIVE;
                }
                if j == 1 {
                    s += bonus_for(&text, i - 1); // first char multiplier-ish
                }
                if s > best {
                    best = s;
                    took = true;
                }
            }
            dp[i][j] = best;
            take[i][j] = took;
            if !took && dp[i - 1][j] != neg && j < m {
                in_gap = true;
            }
        }
    }
    if dp[n][m] == neg {
        return None;
    }
    // Backtrack: walk from the end preferring matches that the DP took.
    let mut indices = Vec::new();
    let (mut i, mut j) = (n, m);
    while j > 0 {
        if i > 0 && take[i][j] {
            indices.push(i - 1);
            i -= 1;
            j -= 1;
        } else if i > 0 {
            i -= 1;
        } else {
            return None;
        }
    }
    indices.reverse();
    if indices.len() != m {
        return None;
    }
    Some((dp[n][m], indices))
}
