    fn attempt_quit(&mut self) {
        if self.needs_save_guard(PendingAction::Quit) {
            return;
        }
        self.should_quit = true;
    }

    fn do_save(&mut self) {
        if !self.editor_modified() {
            return;
        }
        let snapshot = self.snapshot_now();
        if self.save_current_content() {
            self.push_history_snapshot(snapshot);
        }
    }

    fn push_history_snapshot(&mut self, snapshot: Snapshot) {
        let limit = self.settings.history_limit;
        if limit == 0 {
            return;
        }
        self.undo_stack.push(snapshot);
        while self.undo_stack.len() > limit {
            self.undo_stack.remove(0);
        }
        self.redo_stack.clear();
    }

    fn do_discard_prompt(&mut self) {
        if !self.editor_modified() {
            return;
