    fn handle_editor_focused_key(
        &mut self,
        key: KeyEvent,
        terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    ) -> Result<()> {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let visual = self.editor.mode == EditorMode::Visual;
        match key.code {
            KeyCode::Esc => {
                self.editor.exit_visual();
                self.editor.mode = EditorMode::Normal;
                return Ok(());
            }
            KeyCode::Char('c') if ctrl => {
                self.editor.exit_visual();
                self.editor.mode = EditorMode::Normal;
                return Ok(());
            }
            KeyCode::Char('q') if !ctrl && !visual => { self.attempt_quit(); return Ok(()); }
            KeyCode::Char('?') if !ctrl => { self.open_help_popup(); return Ok(()); }
            KeyCode::Char('s') if ctrl => { self.do_save(); return Ok(()); }
            KeyCode::Char('s') if !ctrl && !visual => { self.do_save(); return Ok(()); }
            KeyCode::Char('q') if ctrl => { self.do_discard_prompt(); return Ok(()); }
            KeyCode::Char('r') if ctrl => { self.do_reload(); return Ok(()); }
            KeyCode::Char('f') if ctrl => { self.full_screen = !self.full_screen; return Ok(()); }
            KeyCode::Char('y') if ctrl => {
                if !self.needs_save_guard(PendingAction::OpenExternalEditor) {
                    self.edit_in_external_editor(terminal)?;
                }
                return Ok(());
            }
            KeyCode::Enter => {
                self.editor.exit_visual();
                self.editor.mode = EditorMode::Edit;
                return Ok(());
            }
            KeyCode::Char('v') if ctrl && visual => {
                // Copy selection to the OS clipboard.
                let text = self.editor.selected_text();
                self.editor.set_yank(text.clone());
                if let Err(msg) = clipboard_set(&text) {
                    self.show_error(msg);
                }
                return Ok(());
            }
            KeyCode::Char('x') if ctrl && visual => {
                let text = self.editor.selected_text();
                if let Some((a, b)) = self.editor.selection_range() {
                    self.editor.exit_visual();
                    // Delete via a visual 'd'
                    self.editor.mode = EditorMode::Visual;
                    // Re-enter the range delete through normal handling:
                    let _ = (a, b);
                    self.editor.handle_normal_visual_key(KeyEvent::new(KeyCode::Char('d'), KeyModifiers::NONE));
                }
                self.editor.set_yank(text.clone());
                if let Err(msg) = clipboard_set(&text) {
                    self.show_error(msg);
                }
                return Ok(());
            }
            KeyCode::Char('p') if ctrl => {
                match clipboard_get() {
                    Ok(text) => {
                        self.editor.exit_visual();
                        self.editor.mode = EditorMode::Normal;
                        self.editor.insert_str(&text);
                    }
                    Err(msg) => self.show_error(msg),
                }
                return Ok(());
            }
            KeyCode::Char('v') if !ctrl => {
                if visual { self.editor.exit_visual(); } else { self.editor.start_visual(); }
                return Ok(());
            }
            _ => {}
        }
        let yank_before = self.editor.yank_text().to_owned();
        let was_x_cut = key.code == KeyCode::Char('x') && !ctrl && !visual;
        let _handled = self.editor.handle_normal_visual_key(key);
        if was_x_cut {
            // Text-area "cut" interacts with the OS clipboard even when the
            // sync setting is off in the reference.
            let text = self.editor.yank_text().to_owned();
            if !text.is_empty() {
                if let Err(msg) = clipboard_set(&text) {
                    self.show_error(msg);
                }
            }
        } else {
            self.after_editor_yank_change(&yank_before);
        }
        // Paste with the OS clipboard when sync is enabled.
        if self.settings.sync_os_clipboard {
            if key.code == KeyCode::Char('p') || key.code == KeyCode::Char('P') {
                // The internal paste already happened above; a clipboard
                // fetch error is surfaced as in the reference.  To avoid a
                // double paste we only check when nothing was yanked.
                if yank_before.is_empty() {
                    if let Err(msg) = clipboard_get() {
                        self.show_error(msg);
                    }
                }
            }
        }
        Ok(())
    }

    fn after_editor_yank_change(&mut self, yank_before: &str) {
        if !self.settings.sync_os_clipboard {
            return;
        }
        let now = self.editor.yank_text().to_owned();
        if !now.is_empty() && now != yank_before {
            if let Err(msg) = clipboard_set(&now) {
                self.show_error(msg);
            }
        }
    }

    fn handle_multi_key(&mut self, key: KeyEvent) {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Char('q') | KeyCode::Char('v') if !ctrl => { self.multi_select = false; }
            KeyCode::Esc => { self.multi_select = false; }
            KeyCode::Char('c') if ctrl => { self.multi_select = false; }
            KeyCode::Char('?') => self.open_help_popup(),
            KeyCode::Down => {
                if let Some(cur) = self.list_state.selected() {
                    if cur + 1 < self.displayed.len() {
                        if self.needs_save_guard(PendingAction::ChangeSelectionByIndex(cur + 1)) { return; }
                        self.set_selection_index(cur + 1, true);
                    }
                }
            }
            KeyCode::Up => {
                if let Some(cur) = self.list_state.selected() {
                    if cur > 0 {
                        if self.needs_save_guard(PendingAction::ChangeSelectionByIndex(cur - 1)) { return; }
                        self.set_selection_index(cur - 1, true);
                    }
                }
            }
            KeyCode::Char('j') if !ctrl => {
                if let Some(cur) = self.list_state.selected() {
                    if cur + 1 < self.displayed.len() { self.set_selection_index(cur + 1, true); }
                }
            }
            KeyCode::Char('k') if !ctrl => {
                if let Some(cur) = self.list_state.selected() {
                    if cur > 0 { self.set_selection_index(cur - 1, true); }
                }
            }
            KeyCode::Char(' ') | KeyCode::Enter => {
                if let Some(id) = self.current_entry_id() {
                    if !self.multi_selected.remove(&id) {
                        self.multi_selected.insert(id);
                    }
                }
            }
            KeyCode::Char('a') if !ctrl => {
                for &pos in &self.displayed {
                    self.multi_selected.insert(self.entries[pos].id);
                }
            }
            KeyCode::Char('x') if !ctrl => { self.multi_selected.clear(); }
            KeyCode::Char('i') if !ctrl => {
                let mut next: HashSet<u32> = HashSet::new();
                for &pos in &self.displayed {
                    let id = self.entries[pos].id;
                    if !self.multi_selected.contains(&id) {
                        next.insert(id);
                    }
                }
                // Entries outside the displayed set keep their selection.
                for id in self.multi_selected.iter() {
                    if !self.displayed.iter().any(|&p| self.entries[p].id == *id) {
                        next.insert(*id);
                    }
                }
                self.multi_selected = next;
            }
            KeyCode::Char('d') if !ctrl => { self.prompt_delete_multi(); }
            KeyCode::Delete => { self.prompt_delete_multi(); }
            KeyCode::Char('>') => { self.open_export_multi(); }
            KeyCode::Home => { if !self.displayed.is_empty() { self.set_selection_index(0, true); } }
            KeyCode::End => {
                if !self.displayed.is_empty() { self.set_selection_index(self.displayed.len() - 1, true); }
            }
            KeyCode::PageDown => {
                if let Some(cur) = self.list_state.selected() {
                    self.set_selection_index(cur.saturating_add(self.settings.scroll_per_page), true);
                }
            }
            KeyCode::PageUp => {
                if let Some(cur) = self.list_state.selected() {
                    self.set_selection_index(cur.saturating_sub(self.settings.scroll_per_page), true);
                }
            }
            _ => {}
        }
    }

    fn prompt_delete_multi(&mut self) {
        if self.multi_selected.is_empty() {
            return;
        }
        let count = self.multi_selected.len();
        let mut box_ = MsgBoxState::new(
            MsgBoxKind::Question,
            format!("Do you want to delete the selected {} entries", count),
        );
        box_.action = MsgBoxAction::DeleteMultiSelection;
        self.popups.push(Popup::MsgBox(box_));
    }

    fn delete_multi_now(&mut self) {
        let ids: Vec<u32> = self
            .entries
            .iter()
            .filter(|e| self.multi_selected.contains(&e.id))
            .map(|e| e.id)
            .collect();
        if ids.is_empty() { return; }
        let snapshot = self.snapshot_now();
        let old_index = self.list_state.selected().unwrap_or(0);
        let mut any_ok = false;
        for id in &ids {
            match self.provider.remove_entry(*id) {
                Ok(()) => {
                    any_ok = true;
                    self.entries.retain(|e| e.id != *id);
                }
                Err(err) => {
                    self.show_error(format!("{}", err));
                    break;
                }
            }
        }
        if any_ok {
            self.push_history_snapshot(snapshot);
        }
        self.multi_selected.clear();
        self.refresh_displayed(None);
        if !self.displayed.is_empty() {
            self.set_selection_index(old_index.min(self.displayed.len() - 1), true);
        }
    }
}

fn root_io_message(err: &anyhow::Error) -> String {
    // Export errors in the reference show the bare io error ("Is a
    // directory (os error 21)"), not an anyhow context chain.
    let text = format!("{}", err);
    text
}

pub fn clipboard_set(text: &str) -> std::result::Result<(), String> {
    if text.is_empty() {
        return Ok(());
    }
    // Wayland
    if std::env::var_os("WAYLAND_DISPLAY").is_some() {
        if let Ok(mut child) = std::process::Command::new("wl-copy")
            .stdin(std::process::Stdio::piped())
            .spawn()
        {
            use std::io::Write as _;
            if let Some(mut stdin) = child.stdin.take() {
                let _ = stdin.write_all(text.as_bytes());
            }
            if child.wait().map(|s| s.success()).unwrap_or(false) {
                return Ok(());
            }
        }
    }
    if std::env::var_os("DISPLAY").is_some() {
        for (prog, args) in [("xclip", vec!["-selection", "clipboard"]), ("xsel", vec!["--clipboard", "--input"])] {
            if let Ok(mut child) = std::process::Command::new(prog)
                .args(&args)
                .stdin(std::process::Stdio::piped())
                .spawn()
            {
                use std::io::Write as _;
                if let Some(mut stdin) = child.stdin.take() {
                    let _ = stdin.write_all(text.as_bytes());
                }
                if child.wait().map(|s| s.success()).unwrap_or(false) {
                    return Ok(());
                }
            }
        }
    }
    Err(clipboard_error_message())
}

pub fn clipboard_get() -> std::result::Result<String, String> {
    if std::env::var_os("WAYLAND_DISPLAY").is_some() {
        if let Ok(out) = std::process::Command::new("wl-paste").arg("--no-newline").output() {
            if out.status.success() {
                return Ok(String::from_utf8_lossy(&out.stdout).into_owned());
            }
        }
    }
    if std::env::var_os("DISPLAY").is_some() {
        for (prog, args) in [("xclip", vec!["-selection", "clipboard", "-o"]), ("xsel", vec!["--clipboard", "--output"])] {
            if let Ok(out) = std::process::Command::new(prog).args(&args).output() {
                if out.status.success() {
                    return Ok(String::from_utf8_lossy(&out.stdout).into_owned());
                }
            }
        }
    }
    Err(clipboard_error_message())
}

fn clipboard_error_message() -> String {
    "Error while communicating with the operation system clipboard.Error Details: Unknown error while interacting with the clipboard: X11 server connection timed out because the display server is unavailable".to_owned()
}

/// Fuzzy matcher modelled on the skim/fzf-v2 scoring used by fuzzy-matcher:
/// smart-case subsequence matching with bonuses for boundaries and
/// consecutive runs.  Returns the score and matched char indices.
pub fn fuzzy_match(title: &str, query: &str) -> Option<(i64, Vec<usize>)> {
    if query.is_empty() {
        return None;
    }
    let case_sensitive = query.chars().any(|c| c.is_uppercase());
    let text: Vec<char> = title.chars().collect();
    let pat: Vec<char> = query.chars().collect();
    let eq = |a: char, b: char| -> bool {
        if case_sensitive { a == b } else { a.to_lowercase().eq(b.to_lowercase()) }
    };
    // DP over (text index, pattern index) returning best score plus path.
    // Scores follow fzf v2 constants closely enough for ordering.
    const SCORE_MATCH: i64 = 16;
    const SCORE_GAP_START: i64 = -3;
    const SCORE_GAP_EXT: i64 = -1;
    const BONUS_BOUNDARY: i64 = 8;
    const BONUS_CAMEL: i64 = 7;
    const BONUS_CONSECUTIVE: i64 = 4;

    fn bonus_for(text: &[char], idx: usize) -> i64 {
        if idx == 0 {
            return BONUS_BOUNDARY;
        }
        let prev = text[idx - 1];
        let cur = text[idx];
        if prev.is_whitespace() || !prev.is_alphanumeric() {
            BONUS_BOUNDARY
        } else if prev.is_lowercase() && cur.is_uppercase() {
            BONUS_CAMEL
        } else {
            0
        }
    }

    let n = text.len();
    let m = pat.len();
    if m > n { return None; }
    // dp[i][j] = best score matching pat[..j] within text[..i]
    let neg = i64::MIN / 4;
    let mut dp = vec![vec![neg; m + 1]; n + 1];
    let mut take = vec![vec![false; m + 1]; n + 1];
    for i in 0..=n { dp[i][0] = 0; }
    for i in 1..=n {
        let mut in_gap = false;
        for j in 1..=m {
            // Skip text[i-1]
            let skip = if dp[i - 1][j] == neg {
                neg
            } else if j == m {
                // trailing gap is free-ish in fzf; keep small penalty parity
                dp[i - 1][j]
            } else {
                dp[i - 1][j] + if in_gap { SCORE_GAP_EXT } else { SCORE_GAP_START }
            };
            let mut best = skip;
            let mut took = false;
            if eq(text[i - 1], pat[j - 1]) && dp[i - 1][j - 1] != neg {
                let mut s = dp[i - 1][j - 1] + SCORE_MATCH + bonus_for(&text, i - 1);
                if j > 1 && take[i - 1][j - 1] {
                    s += BONUS_CONSECUTIVE;
                }
                if j == 1 {
                    s += bonus_for(&text, i - 1); // first char multiplier-ish
                }
                if s > best {
                    best = s;
                    took = true;
                }
            }
            dp[i][j] = best;
            take[i][j] = took;
            if !took && dp[i - 1][j] != neg && j < m {
                in_gap = true;
            }
        }
    }
    if dp[n][m] == neg {
        return None;
    }
    // Backtrack: walk from the end preferring matches that the DP took.
    let mut indices = Vec::new();
    let (mut i, mut j) = (n, m);
    while j > 0 {
        if i > 0 && take[i][j] {
            indices.push(i - 1);
            i -= 1;
            j -= 1;
        } else if i > 0 {
            i -= 1;
        } else {
            return None;
        }
    }
    indices.reverse();
    if indices.len() != m {
        return None;
    }
    Some((dp[n][m], indices))
}
RS
