    fn handle_msgbox_key(
        &mut self,
        state: MsgBoxState,
        key: KeyEvent,
        terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    ) -> Result<bool> {
        // Returns true if the box was answered/closed.
        #[derive(PartialEq)]
        enum Answer { Ok, Yes, No, Cancel }
        let answer: Option<Answer> = match state.kind {
            MsgBoxKind::Question => match key.code {
                KeyCode::Char('y') | KeyCode::Char('Y') => Some(Answer::Yes),
                KeyCode::Char('n') | KeyCode::Char('N') => Some(Answer::No),
                KeyCode::Enter => Some(Answer::Yes),
                KeyCode::Esc => Some(Answer::No),
                KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => Some(Answer::No),
                _ => None,
            },
            MsgBoxKind::QuestionCancel => match key.code {
                KeyCode::Char('y') | KeyCode::Char('Y') => Some(Answer::Yes),
                KeyCode::Char('n') | KeyCode::Char('N') => Some(Answer::No),
                KeyCode::Char('c') if !key.modifiers.contains(KeyModifiers::CONTROL) => Some(Answer::Cancel),
                KeyCode::Char('C') => Some(Answer::Cancel),
                KeyCode::Enter => Some(Answer::Yes),
                KeyCode::Esc => Some(Answer::Cancel),
                KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => Some(Answer::Cancel),
                _ => None,
            },
            _ => match key.code {
                KeyCode::Char('o') | KeyCode::Char('O') => Some(Answer::Ok),
                KeyCode::Enter => Some(Answer::Ok),
                KeyCode::Esc => Some(Answer::Ok),
                KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => Some(Answer::Ok),
                _ => None,
            },
        };
        let Some(answer) = answer else {
            // Not answered: push the box back.
            self.popups.push(Popup::MsgBox(state));
            return Ok(false);
        };
        match state.action {
            MsgBoxAction::None => {}
            MsgBoxAction::DeleteCurrent => {
                if answer == Answer::Yes {
                    self.delete_current_now();
                }
            }
            MsgBoxAction::DeleteMultiSelection => {
                if answer == Answer::Yes {
                    self.delete_multi_now();
                }
            }
            MsgBoxAction::DiscardChanges => {
                if answer == Answer::Yes {
                    let mode = self.editor.mode;
                    self.discard_editor_changes();
                    // Preserve the mode the discard was requested from.
                    self.editor.mode = mode;
                }
            }
            MsgBoxAction::SaveChangesPending(action) => {
                match answer {
                    Answer::Yes => {
                        let snapshot = self.snapshot_now();
                        if self.save_current_content() {
                            self.push_history_snapshot(snapshot);
                            self.execute_pending_action(*action, terminal)?;
                        }
                    }
                    Answer::No => {
                        self.discard_editor_changes();
                        self.execute_pending_action(*action, terminal)?;
                    }
                    Answer::Cancel | Answer::Ok => {}
                }
            }
        }
        Ok(true)
    }

    fn handle_tags_key(&mut self, key: KeyEvent) {
