            }
            KeyCode::Down | KeyCode::Char('j') if len > 0 && key.code != KeyCode::Char('j') || key.code == KeyCode::Char('j') && !ctrl && len > 0 => {
                let cur = tags_state.list_state.selected().unwrap_or(0);
                let next = if cur + 1 >= len { 0 } else { cur + 1 };
                tags_state.list_state.select(Some(next));
            }
            KeyCode::Up => {
                if len > 0 {
                    let cur = tags_state.list_state.selected().unwrap_or(0);
                    let next = if cur == 0 { len - 1 } else { cur - 1 };
                    tags_state.list_state.select(Some(next));
                }
            }
            KeyCode::Char('k') if !ctrl => {
                if len > 0 {
                    let cur = tags_state.list_state.selected().unwrap_or(0);
                    let next = if cur == 0 { len - 1 } else { cur - 1 };
                    tags_state.list_state.select(Some(next));
                }
            }
            KeyCode::Char(' ') => {
                if let Some(idx) = tags_state.list_state.selected() {
                    if let Some(tag) = tags_state.tags.get(idx).cloned() {
                        if !tags_state.selected.remove(&tag) {
                            tags_state.selected.insert(tag);
                        }
                    }
                }
            }
            KeyCode::PageDown => {
                if len > 0 {
                    let cur = tags_state.list_state.selected().unwrap_or(0);
                    tags_state.list_state.select(Some((cur + self.settings.scroll_per_page).min(len - 1)));
                }
            }
            KeyCode::PageUp => {
                if len > 0 {
                    let cur = tags_state.list_state.selected().unwrap_or(0);
                    tags_state.list_state.select(Some(cur.saturating_sub(self.settings.scroll_per_page)));
                }
            }
            _ => {}
        }
        self.popups.push(Popup::Tags(tags_state));
    }

    fn open_tags_popup_for_entry(&mut self) {
        let tags = self.all_tags();
        let current_text = if let Some(Popup::Entry(entry)) = self.popups.last() {
            entry.tags.text().to_owned()
        } else {
            String::new()
        };
        let selected: HashSet<String> = parse_tags(&current_text)
            .into_iter()
            .filter(|t| tags.contains(t))
            .collect();
        let mut list_state = ListState::default();
        if !tags.is_empty() {
            list_state.select(Some(0));
        }
        self.popups.push(Popup::Tags(TagsPopupState { tags, selected, list_state }));
    }

    fn handle_popup_key(
        &mut self,
        key: KeyEvent,
        terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    ) -> Result<()> {
        let Some(popup) = self.popups.pop() else { return Ok(()) };
        match popup {
            Popup::MsgBox(state) => {
                self.handle_msgbox_key(state, key, terminal)?;
            }
            Popup::Loading(_) => {
                // Transient; put it back (it is removed programmatically).
                self.popups.push(popup);
            }
            Popup::Entry(mut state) => {
                let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
                let is_ctrl_space = (key.code == KeyCode::Char(' ') && ctrl)
                    || key.code == KeyCode::Char('\0');
                if is_ctrl_space || (key.code == KeyCode::Char('t') && ctrl) {
                    self.popups.push(Popup::Entry(state));
                    self.open_tags_popup_for_entry();
                    return Ok(());
                }
                match key.code {
                    KeyCode::Esc => { /* close */ }
                    KeyCode::Char('c') if ctrl => { /* close */ }
                    KeyCode::Enter => {
                        if let Some(mut draft) = state.validate() {
                            if state.is_edit {
                                let entry_id = state.entry_id.unwrap();
                                let original = self.entries.iter().find(|e| e.id == entry_id).cloned();
                                if let Some(original) = original {
                                    draft.content = original.content.clone();
                                    let updated = Entry {
                                        id: entry_id,
                                        date: draft.date,
                                        title: draft.title,
                                        content: draft.content,
                                        tags: draft.tags,
                                        priority: draft.priority,
                                    };
                                    let snapshot = self.snapshot_now();
                                    match self.provider.update_entry(&updated) {
                                        Ok(()) => {
                                            self.push_history_snapshot(snapshot);
                                            if let Some(slot) = self.entries.iter_mut().find(|e| e.id == entry_id) {
                                                *slot = updated;
                                            }
                                            self.refresh_displayed(Some(entry_id));
                                        }
                                        Err(err) => self.show_error(format!("{}", err)),
                                    }
                                }
                            } else {
                                let snapshot = self.snapshot_now();
                                match self.provider.add_entry(draft) {
                                    Ok(created) => {
                                        self.push_history_snapshot(snapshot);
                                        let id = created.id;
                                        self.entries.push(created);
                                        self.refresh_displayed(Some(id));
                                    }
                                    Err(err) => self.show_error(format!("{}", err)),
                                }
                            }
                        } else {
                            self.popups.push(Popup::Entry(state));
                        }
                    }
                    KeyCode::Tab => {
                        state.focus = (state.focus + 1) % 4;
                        self.popups.push(Popup::Entry(state));
                    }
                    KeyCode::BackTab => {
                        state.focus = (state.focus + 3) % 4;
                        self.popups.push(Popup::Entry(state));
                    }
                    _ => {
                        if state.focused_input_mut().handle_key(key) {
                            state.clear_focus_err();
                        }
                        self.popups.push(Popup::Entry(state));
                    }
                }
            }
            Popup::Tags(_) => {
                // Handled earlier (nested); unreachable in this path.
                self.popups.push(popup);
            }
            Popup::Filter(mut state) => {
                let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
                match key.code {
                    KeyCode::Esc => {}
                    KeyCode::Char('c') if ctrl => {}
                    KeyCode::Char('r') if ctrl => {
                        state.logic = match state.logic {
                            MatchingLogic::All => MatchingLogic::Any,
                            MatchingLogic::Any => MatchingLogic::All,
                        };
                        self.popups.push(Popup::Filter(state));
                    }
                    KeyCode::Tab => {
                        state.focus = (state.focus + 1) % 4;
                        self.popups.push(Popup::Filter(state));
                    }
                    KeyCode::BackTab => {
                        state.focus = (state.focus + 3) % 4;
                        self.popups.push(Popup::Filter(state));
                    }
                    KeyCode::Enter => {
                        // validate priority
                        let mut priority = None;
                        let mut valid = true;
                        if !state.priority.text().is_empty() {
                            match state.priority.text().parse::<u32>() {
                                Ok(p) => priority = Some(p),
                                Err(_) => {
                                    state.priority_err = Some("Priority must be a positive number".to_owned());
                                    valid = false;
                                }
                            }
                        }
                        if !valid {
                            self.popups.push(Popup::Filter(state));
                        } else {
                            let tags: Vec<String> = state
                                .tags
                                .iter()
                                .filter(|t| state.selected_tags.contains(*t))
                                .cloned()
                                .collect();
                            let filter = Filter {
                                title: state.title.text().to_owned(),
                                content: state.content.text().to_owned(),
                                priority,
                                tags,
                                logic: state.logic,
                            };
                            let keep = self.current_entry_id();
                            self.filter = if filter.is_active() { Some(filter) } else { None };
                            self.refresh_displayed(keep);
                        }
                    }
                    _ => {
                        if state.focus == 3 {
                            self.handle_filter_tags_list_key(&mut state, key);
                        } else {
                            let handled = match state.focus {
                                0 => state.title.handle_key(key),
                                1 => state.content.handle_key(key),
                                _ => state.priority.handle_key(key),
                            };
                            if handled && state.focus == 2 {
                                state.priority_err = None;
                            }
                        }
                        self.popups.push(Popup::Filter(state));
                    }
                }
            }
            Popup::Sort(mut state) => {
                if self.handle_sort_key(&mut state, key) {
                    // confirmed
                    self.sort = SortOptions { order: state.order, criteria: state.applied.clone() };
                    let keep = self.current_entry_id();
                    self.refresh_displayed(keep);
                } else if !sort_popup_closed(&state, key) {
                    self.popups.push(Popup::Sort(state));
                }
            }
            Popup::Help(mut state) => {
                if !self.handle_help_key(&mut state, key) {
                    self.popups.push(Popup::Help(state));
                }
            }
            Popup::Fuzzy(mut state) => {
                let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
                match key.code {
                    KeyCode::Esc | KeyCode::Enter => {}
                    KeyCode::Char('c') if ctrl => {}
                    KeyCode::Down => {
                        self.popups.push(Popup::Fuzzy(state));
                        self.fuzzy_move_selection(1);
                    }
                    KeyCode::Up => {
                        self.popups.push(Popup::Fuzzy(state));
                        self.fuzzy_move_selection(-1);
                    }
                    KeyCode::Char('n') if ctrl => {
                        self.popups.push(Popup::Fuzzy(state));
                        self.fuzzy_move_selection(1);
                    }
                    KeyCode::Char('p') if ctrl => {
                        self.popups.push(Popup::Fuzzy(state));
                        self.fuzzy_move_selection(-1);
                    }
                    _ => {
                        if state.query.handle_key(key) {
                            self.popups.push(Popup::Fuzzy(state));
                            self.update_fuzzy_results();
                        } else {
                            self.popups.push(Popup::Fuzzy(state));
                        }
                    }
                }
            }
            Popup::Export(state) => {
                let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
                match key.code {
                    KeyCode::Esc => {}
                    KeyCode::Char('c') if ctrl => {}
                    KeyCode::Enter => {
                        self.perform_export(state);
                    }
                    _ => {
                        let mut state = state;
                        state.path.handle_key(key);
                        self.popups.push(Popup::Export(state));
                    }
                }
            }
        }
        Ok(())
    }

    fn handle_filter_tags_list_key(&mut self, state: &mut FilterPopupState, key: KeyEvent) {
        let len = state.tags.len();
        if len == 0 { return; }
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Down => {
                let cur = state.tags_state.selected().unwrap_or(0);
                state.tags_state.select(Some(if cur + 1 >= len { 0 } else { cur + 1 }));
            }
            KeyCode::Up => {
                let cur = state.tags_state.selected().unwrap_or(0);
                state.tags_state.select(Some(if cur == 0 { len - 1 } else { cur - 1 }));
            }
            KeyCode::Char('j') if !ctrl => {
                let cur = state.tags_state.selected().unwrap_or(0);
                state.tags_state.select(Some(if cur + 1 >= len { 0 } else { cur + 1 }));
            }
            KeyCode::Char('k') if !ctrl => {
                let cur = state.tags_state.selected().unwrap_or(0);
                state.tags_state.select(Some(if cur == 0 { len - 1 } else { cur - 1 }));
            }
            KeyCode::Char(' ') => {
                if let Some(idx) = state.tags_state.selected() {
                    if let Some(tag) = state.tags.get(idx).cloned() {
                        if !state.selected_tags.remove(&tag) {
                            state.selected_tags.insert(tag);
                        }
                    }
                }
            }
            KeyCode::PageDown => {
                let cur = state.tags_state.selected().unwrap_or(0);
                state.tags_state.select(Some((cur + self.settings.scroll_per_page).min(len - 1)));
            }
            KeyCode::PageUp => {
                let cur = state.tags_state.selected().unwrap_or(0);
                state.tags_state.select(Some(cur.saturating_sub(self.settings.scroll_per_page)));
            }
            _ => {}
        }
    }

    /// Returns true when the sort popup was confirmed.
    fn handle_sort_key(&mut self, state: &mut SortPopupState, key: KeyEvent) -> bool {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Enter => return true,
            KeyCode::Esc => {}
            KeyCode::Char('c') if ctrl => {}
            KeyCode::Tab | KeyCode::BackTab => {
                state.focus_applied = !state.focus_applied;
            }
            KeyCode::Char('o') if !ctrl => {
                state.order = match state.order {
                    SortOrder::Ascending => SortOrder::Descending,
                    SortOrder::Descending => SortOrder::Ascending,
                };
            }
            KeyCode::Char('d') if ctrl => {
                let default = SortOptions::default();
                state.order = default.order;
                state.applied = default.criteria.clone();
                state.available = [SortCriterion::Date, SortCriterion::Title, SortCriterion::Priority]
                    .iter().copied().filter(|c| !state.applied.contains(c)).collect();
                state.available_state.select(if state.available.is_empty() { None } else { Some(0) });
                state.applied_state.select(if state.applied.is_empty() { None } else { Some(0) });
            }
            KeyCode::Char('j') if ctrl => { move_criterion(state, 1); }
            KeyCode::Char('k') if ctrl => { move_criterion(state, -1); }
            KeyCode::Down if ctrl => { move_criterion(state, 1); }
            KeyCode::Up if ctrl => { move_criterion(state, -1); }
            KeyCode::Char(' ') => {
                if state.focus_applied {
                    if let Some(idx) = state.applied_state.selected() {
                        if idx < state.applied.len() {
                            let item = state.applied.remove(idx);
                            state.available.push(item);
                            fix_list_selection(&mut state.applied_state, state.applied.len(), idx);
                            if state.available_state.selected().is_none() {
                                state.available_state.select(Some(0));
                            }
                        }
                    }
                } else if let Some(idx) = state.available_state.selected() {
                    if idx < state.available.len() {
                        let item = state.available.remove(idx);
                        state.applied.push(item);
                        fix_list_selection(&mut state.available_state, state.available.len(), idx);
                        if state.applied_state.selected().is_none() {
                            state.applied_state.select(Some(0));
                        }
                    }
                }
            }
            KeyCode::Down => cycle_sort_selection(state, 1),
            KeyCode::Up => cycle_sort_selection(state, -1),
            KeyCode::Char('j') if !ctrl => cycle_sort_selection(state, 1),
            KeyCode::Char('k') if !ctrl => cycle_sort_selection(state, -1),
            _ => {}
        }
        false
    }

    /// Returns true when the help popup should close.
    fn handle_help_key(&mut self, state: &mut HelpPopupState, key: KeyEvent) -> bool {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        match key.code {
            KeyCode::Esc => return true,
            KeyCode::Char('c') if ctrl => return true,
            KeyCode::Char('q') if !ctrl => return true,
            KeyCode::Tab => {
                state.tab = (state.tab + 1) % 3;
                state.scroll = 0;
            }
            KeyCode::BackTab => {
                state.tab = (state.tab + 2) % 3;
                state.scroll = 0;
            }
            KeyCode::Down => { state.scroll = state.scroll.saturating_add(1); }
            KeyCode::Up => { state.scroll = state.scroll.saturating_sub(1); }
            KeyCode::Char('j') if !ctrl => { state.scroll = state.scroll.saturating_add(1); }
            KeyCode::Char('k') if !ctrl => { state.scroll = state.scroll.saturating_sub(1); }
            KeyCode::PageDown => {
                state.scroll = state.scroll.saturating_add(self.settings.scroll_per_page as u16);
            }
            KeyCode::PageUp => {
                state.scroll = state.scroll.saturating_sub(self.settings.scroll_per_page as u16);
            }
            KeyCode::Home => { state.scroll = 0; }
            _ => {}
        }
        false
    }

    fn edit_in_external_editor(
        &mut self,
        terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    ) -> Result<()> {
        let Some(_entry) = self.current_entry().cloned() else { return Ok(()) };
        let command_string = self
            .settings
            .external_editor
            .command
            .clone()
            .or_else(|| std::env::var("VISUAL").ok())
            .or_else(|| std::env::var("EDITOR").ok())
            .unwrap_or_else(|| "vi".to_owned());
        if command_string.is_empty() {
            self.show_error("The Editor in configuration and environmental variables is empty: VISUAL - EDITOR");
            return Ok(());
        }
        let ext = &self.settings.external_editor.temp_file_extension;
        let temp_path = std::env::temp_dir().join(format!("tui_journal.{}", ext));
        if let Err(err) = std::fs::write(&temp_path, self.editor.text()) {
            self.show_error(format!("{}", err));
            return Ok(());
        }
        let mut parts = command_string.split_whitespace();
        let program = parts.next().unwrap_or("").to_owned();
        let args: Vec<String> = parts.map(|s| s.to_owned()).collect();

        // Suspend the TUI while the editor runs.
        let _ = disable_raw_mode();
        {
            let mut out = io::stdout();
            let _ = execute!(out, LeaveAlternateScreen);
            let _ = execute!(out, crossterm::cursor::Show);
        }
        let status = std::process::Command::new(&program)
            .args(&args)
            .arg(&temp_path)
            .status();
        // Resume the TUI.
        let _ = enable_raw_mode();
        {
            let mut out = io::stdout();
            let _ = execute!(out, EnterAlternateScreen);
        }
        let _ = terminal.clear();

        match status {
            Err(err) => {
                let _ = std::fs::remove_file(&temp_path);
                self.focus = Focus::EntriesList;
                self.show_error(format!(
                    "Error while opening the editor. Editor command: '{}'. Error: {}",
                    program, err
                ));
                return Ok(());
            }
            Ok(_) => {}
        }
        let new_content = std::fs::read_to_string(&temp_path).unwrap_or_default();
        // The reference panics here if the temp file was removed by the
        // editor; replicate the message via expect on the removal.
        std::fs::remove_file(&temp_path).expect("Temp File couldn't be deleted");
        self.focus = Focus::EntriesList;
        if new_content != self.editor.text() {
            let mode_before = self.editor.mode;
            self.editor.set_text(&new_content);
            self.editor.mode = mode_before;
            if self.editor.mode != EditorMode::Normal {
                // External editing returns to the list; the editor shows as
                // inactive (Normal) again.
                self.editor.mode = EditorMode::Normal;
            }
            if self.settings.external_editor.auto_save {
                let snapshot = self.snapshot_now();
                // snapshot was taken after set_text; rebuild it as the
                // pre-save state by restoring entry content in the clone.
                let mut snapshot = snapshot;
                if let Some(cur) = self.current_entry().cloned() {
                    if let Some(slot) = snapshot.entries.iter_mut().find(|e| e.id == cur.id) {
                        *slot = cur;
                    }
                }
                if self.save_current_content() {
                    self.push_history_snapshot(snapshot);
                }
            }
        }
        Ok(())
    }
}

fn sort_popup_closed(state: &SortPopupState, key: KeyEvent) -> bool {
    let _ = state;
    matches!(key.code, KeyCode::Esc) || (key.code == KeyCode::Char('c') && key.modifiers.contains(KeyModifiers::CONTROL))
}

fn fix_list_selection(state: &mut ListState, len: usize, removed_idx: usize) {
    if len == 0 {
        state.select(None);
    } else {
        state.select(Some(removed_idx.min(len - 1)));
    }
}

fn cycle_sort_selection(state: &mut SortPopupState, delta: isize) {
    let (list_state, len) = if state.focus_applied {
        (&mut state.applied_state, state.applied.len())
    } else {
        (&mut state.available_state, state.available.len())
    };
    if len == 0 { return; }
    let cur = list_state.selected().unwrap_or(0) as isize;
    let next = (cur + delta).rem_euclid(len as isize) as usize;
    list_state.select(Some(next));
}

fn move_criterion(state: &mut SortPopupState, delta: isize) {
    if !state.focus_applied {
        return;
    }
    let Some(idx) = state.applied_state.selected() else { return };
    let next = idx as isize + delta;
    if next < 0 || next as usize >= state.applied.len() {
        return;
    }
    let next = next as usize;
    state.applied.swap(idx, next);
    state.applied_state.select(Some(next));
}
