fn draw_help_popup(frame: &mut Frame, app: &mut App, idx: usize, area: Rect) {
    let mut state = take_popup!(app, idx, Help);
    let rect = centered_rect_percent(90, 80, area);
    frame.render_widget(Clear, rect);
    let block = Block::default().borders(Borders::ALL).title("Help");
    let inner = block.inner(rect);
    frame.render_widget(block, rect);
    let rows = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Length(3), Constraint::Min(0)])
        .split(inner);
    let inner_rows = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Length(1), Constraint::Min(0), Constraint::Length(1)])
        .split(rows[0]);
    let tabs_block = Block::default().borders(Borders::ALL).title("Tabs");
    let tabs_inner = tabs_block.inner(inner_rows[1]);
    frame.render_widget(tabs_block, inner_rows[1]);
    let tab_titles = ["Global", "Editor", "Multi-Select"];
    let tabs = Tabs::new(tab_titles)
        .select(state.tab)
        .highlight_style(app.styles.general.list_item_selected.to_rat())
        .padding(" ", " ");
    frame.render_widget(tabs, tabs_inner);

    let content_area = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Length(1), Constraint::Min(0), Constraint::Length(1)])
        .split(rows[1])[1];

    match state.tab {
        1 => {
            let b = Block::default().borders(Borders::ALL).title("Editor Keybindings");
            let inner2 = b.inner(content_area);
            frame.render_widget(b, content_area);
            // Clamp scroll.
            let lines = wrapped_line_count(EDITOR_HELP_TEXT, inner2.width.max(1) as usize) as u16;
            let max_scroll = lines.saturating_sub(inner2.height);
            if state.scroll > max_scroll { state.scroll = max_scroll; }
            let para = Paragraph::new(EDITOR_HELP_TEXT)
                .wrap(Wrap { trim: false })
                .scroll((state.scroll, 0));
            frame.render_widget(para, inner2);
            if lines > inner2.height {
                let mut sb = ScrollbarState::new(lines as usize)
                    .position(state.scroll as usize)
                    .viewport_content_length(inner2.height as usize);
                frame.render_stateful_widget(Scrollbar::new(ScrollbarOrientation::VerticalRight), inner2, &mut sb);
            }
        }
        other => {
            let (bindings, title) = if other == 0 {
                (GLOBAL_BINDINGS, "Global Keybindings")
            } else {
                (MULTI_BINDINGS, "Multi-Select Mode Keybindings")
            };
            let b = Block::default().borders(Borders::ALL).title(title);
            let inner2 = b.inner(content_area);
            frame.render_widget(b, content_area);
            draw_bindings_table(frame, bindings, inner2, &mut state);
        }
    }
    app.popups[idx] = Popup::Help(state);
}

fn draw_bindings_table(
    frame: &mut Frame,
    bindings: &[KeyBinding],
    area: Rect,
    state: &mut HelpPopupState,
) {
    let header = Row::new(["Key", "Command", "Description"]).bottom_margin(1);
    let rows: Vec<Row> = bindings
        .iter()
        .map(|b| Row::new([Cell::from(b.key), Cell::from(b.command), Cell::from(b.description)]))
        .collect();
    // Compute the total wrapped height for clamping/scrollbar purposes.
    let widths = column_widths(area.width);
    let total_height: usize = bindings
        .iter()
        .map(|b| {
            wrapped_line_count(b.key, widths.0)
                .max(wrapped_line_count(b.command, widths.1))
                .max(wrapped_line_count(b.description, widths.2))
        })
        .sum();
    let visible = area.height.saturating_sub(2) as usize; // minus header+margin
    let max_offset_lines = total_height.saturating_sub(visible);
    if (state.scroll as usize) > max_offset_lines {
        state.scroll = max_offset_lines as u16;
    }
    // Convert the line scroll into a row offset for the stateful Table.
    let mut offset_rows = 0usize;
    let mut acc = 0usize;
    for b in bindings {
        let h = wrapped_line_count(b.key, widths.0)
            .max(wrapped_line_count(b.command, widths.1))
            .max(wrapped_line_count(b.description, widths.2));
        if acc + h <= state.scroll as usize {
            offset_rows += 1;
            acc += h;
        } else {
            break;
        }
    }
    let table = Table::new(
        rows,
        [
            Constraint::Percentage(20),
            Constraint::Percentage(30),
            Constraint::Percentage(50),
        ],
    )
    .header(header);
    let mut table_state = TableState::default().with_offset(offset_rows);
    frame.render_stateful_widget(table, area, &mut table_state);
    if total_height > visible {
        let mut sb = ScrollbarState::new(total_height)
            .position(state.scroll as usize)
            .viewport_content_length(visible);
        frame.render_stateful_widget(Scrollbar::new(ScrollbarOrientation::VerticalRight), area, &mut sb);
    }
}

fn column_widths(width: u16) -> (usize, usize, usize) {
    let usable = (width as usize).saturating_sub(2);
    let k = usable * 20 / 100;
    let c = usable * 30 / 100;
    let d = usable.saturating_sub(k + c);
    (k.max(1), c.max(1), d.max(1))
}

