pub fn draw(frame: &mut Frame, app: &mut App) {
    let area = frame.area();
    let footer_text = footer_text(app);
    let footer_height = footer_height(&footer_text, area.width);
    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Min(0), Constraint::Length(footer_height)])
        .split(area);
    draw_main(frame, app, chunks[0]);
    // Footer
    let footer = Paragraph::new(footer_text).wrap(Wrap { trim: true });
    frame.render_widget(footer, chunks[1]);

    // Popups are drawn over the *whole* frame area (including footer rows
    // for the bigger popups) to mirror the reference geometry.
    let popup_count = app.popups.len();
    for i in 0..popup_count {
        draw_popup(frame, app, i, area);
    }
}

fn footer_height(text: &str, width: u16) -> u16 {
    // The reference divides by the area width; a zero width panics there.
    let h = text.len() / (width as usize) + 1;
    h.min(u16::MAX as usize) as u16
}

pub fn footer_text(app: &App) -> String {
    if app.focus == Focus::Editor && app.editor.mode == EditorMode::Edit {
        return "Back to Editor Normal Mode: 'Esc','<Ctrl-c>','<Ctrl-[>' |  Edit using Emacs motions".to_owned();
    }
    if app.multi_select {
        return "Leave journals multi selection mode: 'q','v','Esc','<Ctrl-c>' | Show help: '?'".to_owned();
    }
    if app.focus == Focus::Editor {
        return "Exit: 'q' | Edit journal content: 'Enter','<Ctrl-m>' | Show help: '?'".to_owned();
    }
    if app.is_filtered() {
        "Exit: 'q' | Edit journal content: 'Enter','<Ctrl-m>' | Reset filter: 'x' | Open sort options: 'o' | Show help: '?'".to_owned()
    } else {
        "Exit: 'q' | Edit journal content: 'Enter','<Ctrl-m>' | Open filter: 'f' | Open sort options: 'o' | Show help: '?'".to_owned()
    }
}

fn draw_main(frame: &mut Frame, app: &mut App, area: Rect) {
    if app.full_screen {
        match app.focus {
            Focus::EntriesList => draw_entries_list(frame, app, area),
            Focus::Editor => draw_editor(frame, app, area),
        }
        return;
    }
    let chunks = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([Constraint::Percentage(30), Constraint::Percentage(70)])
        .split(area);
    draw_entries_list(frame, app, chunks[0]);
    draw_editor(frame, app, chunks[1]);
