fn entry_item_lines(app: &App, entry: &Entry, inner_width: u16) -> Vec<Line<'static>> {
    let styles = &app.styles;
    let active = app.focus == Focus::EntriesList && !app.multi_select;
    let title_style = if app.multi_selected.contains(&entry.id) {
        styles.journals_list.title_selected.to_rat()
    } else if active || app.multi_select {
        styles.journals_list.title_active.to_rat()
    } else {
        styles.journals_list.title_inactive.to_rat()
    };
    let date_style = styles.journals_list.date_priority.to_rat();

    let title_text = if app.multi_select && app.multi_selected.contains(&entry.id) {
        format!("* {}", entry.title)
    } else {
        entry.title.clone()
    };
    let text_width = inner_width.saturating_sub(2) as usize;
    let mut lines: Vec<Line> = Vec::new();
    for part in wrap_text(&title_text, text_width) {
        lines.push(Line::from(Span::styled(part, title_style)));
    }
    if lines.is_empty() {
        lines.push(Line::from(Span::styled(String::new(), title_style)));
    }

    // Datum line
    let show_datum = match app.settings.datum_visibility {
        DatumVisibility::Show => true,
        DatumVisibility::EmptyLine => true,
        DatumVisibility::Hide => entry.priority.is_some(),
    };
    if show_datum {
        let mut datum = String::new();
        if app.settings.datum_visibility == DatumVisibility::Show {
            datum = format!(
                "{},{},{}",
                entry.date.format("%-d"),
                entry.date.format("%-m"),
                entry.date.format("%Y")
            );
        }
        if let Some(p) = entry.priority {
            if datum.is_empty() {
                datum = format!("Priority: {}", p);
            } else {
                datum = format!("{} | Priority: {}", datum, p);
            }
        }
        lines.push(Line::from(Span::styled(datum, date_style)));
    }

    if !entry.tags.is_empty() {
        let tag_lines = build_tag_lines(app, entry, text_width);
        lines.extend(tag_lines);
    }
    lines
}

fn tag_color(tag: &str) -> Color {
    // Deterministic colour per tag, similar in spirit to the reference
    // which colours each tag individually.
    const PALETTE: &[Color] = &[
        Color::LightCyan,
        Color::LightGreen,
        Color::LightRed,
        Color::LightYellow,
        Color::LightBlue,
        Color::LightMagenta,
        Color::Cyan,
        Color::Green,
        Color::Yellow,
        Color::Blue,
        Color::Magenta,
        Color::Red,
    ];
    let mut h: u64 = 0xcbf29ce484222325;
    for b in tag.as_bytes() {
        h ^= *b as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    PALETTE[(h % PALETTE.len() as u64) as usize]
}

fn build_tag_lines(app: &App, entry: &Entry, width: usize) -> Vec<Line<'static>> {
    let default_style = app.styles.journals_list.tags_default.to_rat();
    if !app.settings.colored_tags {
        let joined = entry.tags.join(" | ");
        return wrap_text(&joined, width)
            .into_iter()
            .map(|p| Line::from(Span::styled(p, default_style)))
            .collect();
    }
    // Coloured tags: place tags left-to-right, wrapping to a new line when
    // the next tag would exceed the width.  A tag longer than a line yields
    // a leading empty line and is truncated, matching observed behaviour.
    let mut lines: Vec<Line> = Vec::new();
    let mut spans: Vec<Span> = Vec::new();
    let mut cur_len = 0usize;
    for (i, tag) in entry.tags.iter().enumerate() {
        let tag_style = Style::default().fg(Color::Black).bg(tag_color(tag));
        let sep_len = if i == 0 { 0 } else { 3 };
        if tag.chars().count() > width {
            if cur_len == 0 && spans.is_empty() {
                lines.push(Line::from(""));
            } else {
                lines.push(Line::from(std::mem::take(&mut spans)));
            }
            let truncated: String = tag.chars().take(width).collect();
            let mut line_spans = vec![Span::styled(truncated, tag_style)];
            if i + 1 < entry.tags.len() {
                line_spans.push(Span::styled(" | ".to_owned(), default_style));
            }
            lines.push(Line::from(line_spans));
            cur_len = 0;
            continue;
        }
        if cur_len > 0 && cur_len + sep_len + tag.chars().count() > width {
            lines.push(Line::from(std::mem::take(&mut spans)));
            cur_len = 0;
        }
        if cur_len > 0 || i > 0 && cur_len == 0 && !lines.is_empty() {
            // separator before this tag on the current line
            if cur_len > 0 {
                spans.push(Span::styled(" | ".to_owned(), default_style));
                cur_len += 3;
            }
        }
        spans.push(Span::styled(tag.clone(), tag_style));
        cur_len += tag.chars().count();
        // Trailing separator is added before the next tag; but the
        // reference puts " |" at line ends when wrapping happens after a
        // tag.  That is approximated when the next tag does not fit:
        if i + 1 < entry.tags.len() {
            let next_len = entry.tags[i + 1].chars().count();
            if cur_len + 3 + next_len > width && next_len <= width {
                spans.push(Span::styled(" |".to_owned(), default_style));
                lines.push(Line::from(std::mem::take(&mut spans)));
                cur_len = 0;
                // Mark that a separator has been consumed by using a
                // sentinel: we set a flag via an empty span list and skip
                // adding the separator next iteration because cur_len==0.
            }
        }
    }
    if !spans.is_empty() || lines.is_empty() {
        lines.push(Line::from(spans));
    }
    // Remove a possible trailing empty line produced above.
    while lines.len() > 1 {
        let last_empty = lines.last().map(|l: &Line| l.spans.iter().all(|s| s.content.is_empty())).unwrap_or(false);
        if last_empty { lines.pop(); } else { break; }
    }
    lines
}

pub fn wrap_text(text: &str, width: usize) -> Vec<String> {
    if width == 0 {
        return vec![text.to_owned()];
    }
    if text.is_empty() {
        return vec![String::new()];
    }
    let mut lines = Vec::new();
    let mut cur = String::new();
    let mut cur_w = 0usize;
    let mut first_word_on_line = true;
    for word in split_words(text) {
        let word_w = str_width(&word);
        if word_w > width {
            if !cur.is_empty() {
                lines.push(std::mem::take(&mut cur));
                cur_w = 0;
                first_word_on_line = true;
            }
            // Split the long word into chunks.
            let mut chunk = String::new();
            let mut chunk_w = 0;
            for ch in word.chars() {
                let cw = UnicodeWidthChar::width(ch).unwrap_or(0);
                if chunk_w + cw > width && !chunk.is_empty() {
                    lines.push(std::mem::take(&mut chunk));
                    chunk_w = 0;
                }
                chunk.push(ch);
                chunk_w += cw;
            }
            cur = chunk;
            cur_w = chunk_w;
            first_word_on_line = false;
            continue;
        }
        let add = if first_word_on_line { word_w } else { word_w + 1 };
        if cur_w + add > width && !cur.is_empty() {
            lines.push(std::mem::take(&mut cur));
            cur.push_str(&word);
            cur_w = word_w;
            first_word_on_line = false;
        } else {
            if !first_word_on_line {
                cur.push(' ');
                cur_w += 1;
            }
            cur.push_str(&word);
            cur_w += word_w;
            first_word_on_line = false;
        }
    }
    if !cur.is_empty() || lines.is_empty() {
        lines.push(cur);
    }
    lines
}

fn split_words(text: &str) -> Vec<String> {
    text.split(' ').filter(|s| !s.is_empty()).map(|s| s.to_owned()).collect()
}

pub fn str_width(text: &str) -> usize {
    text.chars().map(|c| UnicodeWidthChar::width(c).unwrap_or(0)).sum()
}

fn draw_entries_list(frame: &mut Frame, app: &mut App, area: Rect) {
    let styles = &app.styles;
    let block_style = if app.multi_select {
        styles.journals_list.block_multi_select.to_rat()
    } else if app.focus == Focus::EntriesList {
        styles.journals_list.block_active.to_rat()
    } else {
        styles.journals_list.block_inactive.to_rat()
    };
    let mut block = Block::default()
        .borders(Borders::ALL)
        .title(list_block_title(app))
        .style(block_style);
    if !app.displayed.is_empty() {
        if let Some(sel) = app.list_state.selected() {
            block = block.title_bottom(
                Line::from(format!("{}/{}", sel + 1, app.displayed.len())).right_aligned(),
            );
        }
    }
    let inner = block.inner(area);
    frame.render_widget(block, area);
    if inner.width == 0 || inner.height == 0 {
        return;
    }
    if app.displayed.is_empty() {
        let msg = if app.multi_select {
            "No entries to select"
        } else {
            "Use 'n' to create new entry"
        };
        // The reference shows this text on the second row of the list.
        let text = format!("\n{}", msg);
        let para = Paragraph::new(text).alignment(Alignment::Center).wrap(Wrap { trim: true });
        frame.render_widget(para, inner);
        return;
    }
    let items: Vec<ListItem> = app
        .displayed
        .iter()
        .map(|&pos| {
            let lines = entry_item_lines(app, &app.entries[pos], inner.width);
            ListItem::new(Text::from(lines))
        })
        .collect();
    let total_lines: usize = items.iter().map(|i| i.height()).sum();
    let highlight = if app.focus == Focus::EntriesList {
        styles.journals_list.highlight_active.to_rat()
    } else {
        styles.journals_list.highlight_inactive.to_rat()
    };
    let list = List::new(items)
        .highlight_style(highlight)
        .highlight_symbol("> ")
        .highlight_spacing(ratatui::widgets::HighlightSpacing::Always)
        .direction(ListDirection::TopToBottom);
    // Ratatui's ListState needs a mutable borrow; render statefully.
    let list_state = std::mem::take(&mut app.list_state);
    let mut list_state = list_state;
    frame.render_stateful_widget(list, inner, &mut list_state);
    let offset = list_state.offset();
    app.list_state = list_state;

    if total_lines > inner.height as usize {
        // Scrollbar content is counted in visual rows of the list.
        let mut sb_state = ScrollbarState::new(total_lines)
            .position(offset)
            .viewport_content_length(inner.height as usize);
        let scrollbar = Scrollbar::new(ScrollbarOrientation::VerticalRight);
        frame.render_stateful_widget(scrollbar, inner, &mut sb_state);
    }
}

