fn editor_block_title(app: &App) -> String {
    let modified = app.editor_modified();
    let star = if modified { " *" } else { "" };
    if app.focus == Focus::Editor {
        match app.editor.mode {
            EditorMode::Normal => format!("Content - NORMAL{}", star),
            EditorMode::Edit => format!("Content - EDIT{}", star),
            EditorMode::Visual => format!("Content - Visual{}", star),
        }
    } else {
        format!("Content{}", star)
    }
}

fn draw_editor(frame: &mut Frame, app: &mut App, area: Rect) {
    let styles = &app.styles;
    let block_style = if app.focus != Focus::Editor {
        styles.editor.block_normal_inactive.to_rat()
    } else {
        match app.editor.mode {
            EditorMode::Normal => styles.editor.block_normal_active.to_rat(),
            EditorMode::Edit => styles.editor.block_insert.to_rat(),
            EditorMode::Visual => styles.editor.block_visual.to_rat(),
        }
    };
    let block = Block::default()
        .borders(Borders::ALL)
        .title(editor_block_title(app))
        .style(block_style);
    let inner = block.inner(area);
    frame.render_widget(block, area);
    if inner.width == 0 || inner.height == 0 {
        return;
    }
    render_editor_content(frame.buffer_mut(), app, inner);

    // Scrollbars (only meaningful when the editor is focused in the
    // reference's bottom-border overlay for the horizontal one).
    let line_count = app.editor.lines.len();
    if line_count > inner.height as usize {
        let mut state = ScrollbarState::new(line_count)
            .position(app.editor.scroll_row)
            .viewport_content_length(inner.height as usize);
        let sb = Scrollbar::new(ScrollbarOrientation::VerticalRight);
        frame.render_stateful_widget(sb, inner, &mut state);
    }
    let max_line = app.editor.lines.iter().map(|l| line_disp_width(l)).max().unwrap_or(0);
    if app.focus == Focus::Editor && max_line > inner.width as usize {
        // Horizontal scrollbar overlays the block's bottom border inside
        // the outer area.
        let sb_area = Rect {
            x: area.x,
            y: area.y + area.height.saturating_sub(1),
            width: area.width,
            height: 1,
        };
        let mut state = ScrollbarState::new(max_line)
            .position(app.editor.scroll_col)
            .viewport_content_length(inner.width as usize);
        let sb = Scrollbar::new(ScrollbarOrientation::HorizontalBottom);
        frame.render_stateful_widget(sb, sb_area, &mut state);
        // Restore the corners eaten by the scrollbar arrows to border
        // characters is left to ratatui (matches closely enough).
    }
}

fn render_editor_content(buf: &mut Buffer, app: &mut App, inner: Rect) {
    let height = inner.height as usize;
    let width = inner.width as usize;
    app.editor.ensure_cursor_visible(height, width);
    let focused = app.focus == Focus::Editor;
    let selection = if focused && app.editor.mode == EditorMode::Visual {
        app.editor.selection_range()
    } else {
        None
    };
    let sel_style = app.styles.editor.selection_style.to_rat();
    let cursor_style = match app.editor.mode {
        EditorMode::Normal => app.styles.editor.cursor_normal.to_rat(),
        EditorMode::Edit => app.styles.editor.cursor_insert.to_rat(),
        EditorMode::Visual => app.styles.editor.cursor_visual.to_rat(),
    };
    let base = Style::default();
    for vis_row in 0..height {
        let row = app.editor.scroll_row + vis_row;
        if row >= app.editor.lines.len() {
            break;
        }
        let y = inner.y + vis_row as u16;
        let line = &app.editor.lines[row];
        let mut disp = 0usize;
        for (ci, ch) in line.chars().enumerate() {
            let w = super::editor::char_disp_width_at(ch, disp);
            let start_disp = disp;
            disp += w;
            if disp <= app.editor.scroll_col {
                continue;
            }
            if start_disp >= app.editor.scroll_col + width {
                break;
            }
            let xoff = start_disp - app.editor.scroll_col;
            if xoff >= width { break; }
            let x = inner.x + xoff as u16;
            let is_cursor = focused && row == app.editor.row && ci == app.editor.col;
            let in_sel = selection
                .map(|(s, e)| (row > s.0 || (row == s.0 && ci >= s.1)) && (row < e.0 || (row == e.0 && ci <= e.1)))
                .unwrap_or(false);
            let style = if is_cursor {
                cursor_style
            } else if in_sel {
                sel_style
            } else {
                base
            };
            if ch == '\t' {
                // Fill tab span with spaces.
                for k in 0..w {
                    if xoff + k >= width { break; }
                    let cell = &mut buf[(x + k as u16, y)];
                    cell.set_symbol(" ");
                    cell.set_style(style);
                }
            } else {
                let cell = &mut buf[(x, y)];
                cell.set_char(ch);
                cell.set_style(style);
            }
        }
        // Cursor one past the last char (or on an empty line).
        if focused && row == app.editor.row {
            let total = line_disp_width(line);
            if app.editor.col >= line.chars().count() {
                if total >= app.editor.scroll_col && total < app.editor.scroll_col + width {
                    let x = inner.x + (total - app.editor.scroll_col) as u16;
                    let cell = &mut buf[(x, y)];
                    cell.set_symbol(" ");
                    cell.set_style(cursor_style);
                }
            } else if app.editor.col < line.chars().count() {
                // Also highlight selection background behind other selected
                // cells already handled above.
                let _ = disp_col_of(line, app.editor.col);
            }
        }
        // If a selection spans whole lines, also paint the rest of a
        // fully-selected line's trailing cell.
        if let Some((s, e)) = selection {
            if row > s.0 && row < e.0 {
                // middle lines are fully covered char-by-char; nothing extra
            }
        }
    }
}

// ---------- popups ----------

pub fn centered_rect_percent(percent_x: u16, percent_y: u16, area: Rect) -> Rect {
    let vertical = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Percentage((100 - percent_y) / 2),
            Constraint::Percentage(percent_y),
            Constraint::Percentage((100 - percent_y) / 2),
        ])
        .split(area);
    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(vertical[1])[1]
}

pub fn centered_rect_exact(percent_x: u16, height: u16, area: Rect) -> Rect {
    let vertical = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Fill(1),
            Constraint::Length(height),
            Constraint::Fill(1),
        ])
        .split(area);
    Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage((100 - percent_x) / 2),
            Constraint::Percentage(percent_x),
            Constraint::Percentage((100 - percent_x) / 2),
        ])
        .split(vertical[1])[1]
}

fn draw_popup(frame: &mut Frame, app: &mut App, idx: usize, area: Rect) {
    // We need an owned snapshot of lightweight metadata to avoid borrow
    // fights while rendering widgets that need &mut state (inputs etc.).
    match &app.popups[idx] {
        Popup::Loading(text) => {
            let text = text.clone();
            let rect = loading_rect(area);
            frame.render_widget(Clear, rect);
            let block = Block::default()
                .borders(Borders::ALL)
                .border_type(BorderType::Rounded);
            let inner = block.inner(rect);
            frame.render_widget(block, rect);
            let para = Paragraph::new(text).alignment(Alignment::Center);
            frame.render_widget(para, inner);
        }
        Popup::MsgBox(state) => {
            let state = unsafe { &*(state as *const MsgBoxState) };
            draw_msgbox(frame, state, &app.styles, area);
        }
        Popup::Entry(_) => draw_entry_popup(frame, app, idx, area),
        Popup::Tags(_) => draw_tags_popup(frame, app, idx, area),
        Popup::Filter(_) => draw_filter_popup(frame, app, idx, area),
        Popup::Sort(_) => draw_sort_popup(frame, app, idx, area),
        Popup::Help(_) => draw_help_popup(frame, app, idx, area),
        Popup::Fuzzy(_) => draw_fuzzy_popup(frame, app, idx, area),
        Popup::Export(_) => draw_export_popup(frame, app, idx, area),
    }
}

fn loading_rect(area: Rect) -> Rect {
    // "Importing journals..." popup: centred, about 25 wide and 3 high in
    // a 120x40 frame.
    let w = 25.min(area.width);
    let h = 3.min(area.height);
    Rect {
        x: area.x + (area.width.saturating_sub(w)) / 2,
        y: area.y + (area.height.saturating_sub(h)) / 2,
        width: w,
        height: h,
    }
}

// The popup renderers below take the popup index and temporarily move the
// popup state out with a placeholder so they can use &mut App freely.
// They put the state back afterwards.

macro_rules! take_popup {
    ($app:expr, $idx:expr, $variant:ident) => {{
        let placeholder = Popup::Loading(String::new());
        let taken = std::mem::replace(&mut $app.popups[$idx], placeholder);
        match taken {
            Popup::$variant(state) => state,
            other => {
                $app.popups[$idx] = other;
                return;
            }
        }
    }};
}

fn draw_entry_popup(frame: &mut Frame, app: &mut App, idx: usize, area: Rect) {
    let mut state = take_popup!(app, idx, Entry);
    let help_text = "Enter or <Ctrl-m>: confirm | Esc or <Ctrl-c>: Cancel | Tab: Change focused control | <Ctrl-Space> or <Ctrl-t>: Open tags";
    // Compute height from wrapped help lines at the popup's inner width.
    let tmp_rect = centered_rect_exact(70, 18, area);
    let inner_w = tmp_rect.width.saturating_sub(2) as usize;
    let help_lines = estimate_wrapped_lines(help_text, inner_w.max(1));
    let height = 16 + help_lines as u16;
    let rect = centered_rect_exact(70, height, area);
    frame.render_widget(Clear, rect);
    let title = if state.is_edit { "Edit journal" } else { "Create journal" };
    let block = Block::default().borders(Borders::ALL).title(title);
    let inner = block.inner(rect);
    frame.render_widget(block, rect);
    // Inner layout with margins.
    let rows = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(1),
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Length(3),
            Constraint::Length(help_lines as u16),
            Constraint::Length(1),
        ])
        .split(inner);
    let col = |r: Rect| -> Rect {
        Layout::default()
            .direction(Direction::Horizontal)
            .constraints([Constraint::Length(3), Constraint::Min(0), Constraint::Length(3)])
            .split(r)[1]
    };
    let title_label = match &state.title_err {
        Some(e) => format!("Title : {}", e),
        None => "Title".to_owned(),
    };
    let date_label = match &state.date_err {
        Some(e) => format!("Date : {}", e),
        None => "Date".to_owned(),
    };
    let prio_label = match &state.priority_err {
        Some(e) => format!("Priority : {}", e),
        None => "Priority".to_owned(),
    };
    let tags_label = if state.focus == 3 {
        "Tags - A comma-separated list".to_owned()
    } else {
        "Tags".to_owned()
    };
    let styles = unsafe { &*(&app.styles as *const AppStyles) };
    state.title.render(col(rows[1]), frame.buffer_mut(), &title_label, state.focus == 0, state.title_err.is_some(), styles);
    state.date.render(col(rows[2]), frame.buffer_mut(), &date_label, state.focus == 1, state.date_err.is_some(), styles);
    state.priority.render(col(rows[3]), frame.buffer_mut(), &prio_label, state.focus == 2, state.priority_err.is_some(), styles);
    state.tags.render(col(rows[4]), frame.buffer_mut(), &tags_label, state.focus == 3, false, styles);
    let help = Paragraph::new(help_text).alignment(Alignment::Center).wrap(Wrap { trim: true });
    frame.render_widget(help, rows[5]);
    app.popups[idx] = Popup::Entry(state);
}

fn draw_tags_popup(frame: &mut Frame, app: &mut App, idx: usize, area: Rect) {
    // The tags popup is centred over the entry popup beneath it.  Recompute
    // that popup's rect the same way as draw_entry_popup, then take a
    // 70% x 90% centred rect of it.
    let mut state = take_popup!(app, idx, Tags);
    let help_text_entry = "Enter or <Ctrl-m>: confirm | Esc or <Ctrl-c>: Cancel | Tab: Change focused control | <Ctrl-Space> or <Ctrl-t>: Open tags";
    let tmp_rect = centered_rect_exact(70, 18, area);
    let inner_w = tmp_rect.width.saturating_sub(2) as usize;
    let height = 16 + estimate_wrapped_lines(help_text_entry, inner_w.max(1)) as u16;
    let entry_rect = centered_rect_exact(70, height, area);
    let rect = centered_rect_percent(70, 90, entry_rect);
    frame.render_widget(Clear, rect);
    let block_style = app.styles.general.input_block_active.to_rat();
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title("Tags")
        .style(block_style);
    let inner = block.inner(rect);
    frame.render_widget(block, rect);
    let help_text = "<Space>: Toggle Selected | Enter or <Ctrl-m>: Confirm | Esc, q or <Ctrl-c>: Cancel";
    let help_lines = estimate_wrapped_lines(help_text, inner.width.max(1) as usize) as u16;
    // Layout: list area + help at the bottom.  In the entry popup the help
    // starts one line above the bottom inner row.
    let rows = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Min(0),
            Constraint::Length(help_lines),
            Constraint::Length(0),
        ])
        .split(inner);
    draw_checkable_tags_list(frame, &app.styles, &state.tags, &state.selected, &mut state.list_state, rows[0], true, false);
    let help = Paragraph::new(help_text).alignment(Alignment::Center).wrap(Wrap { trim: true });
    frame.render_widget(help, rows[1]);
    app.popups[idx] = Popup::Tags(state);
}

fn draw_checkable_tags_list(
    frame: &mut Frame,
    styles: &AppStyles,
    tags: &[String],
    selected: &HashSet<String>,
    list_state: &mut ListState,
    area: Rect,
    list_active: bool,
    in_filter: bool,
) {
    if tags.is_empty() {
        let para = Paragraph::new("\nNo journals with tags provided")
            .alignment(Alignment::Center)
            .wrap(Wrap { trim: true });
        frame.render_widget(para, area);
        return;
    }
    let items: Vec<ListItem> = tags
        .iter()
        .map(|tag| {
            let label = if in_filter && tag == NO_TAGS {
                "NO_TAGS (Entries with no tags)".to_owned()
            } else {
                tag.clone()
            };
            if selected.contains(tag) {
                ListItem::new(format!("* {}", label))
            } else {
                ListItem::new(label)
            }
        })
        .collect();
    let highlight = if list_active {
        styles.general.list_highlight_active.to_rat()
    } else {
        styles.general.list_highlight_inactive.to_rat()
    };
    let list = List::new(items)
        .highlight_style(highlight)
        .highlight_symbol(">> ")
        .highlight_spacing(ratatui::widgets::HighlightSpacing::Always);
    frame.render_stateful_widget(list, area, list_state);
    if tags.len() > area.height as usize {
        let mut sb = ScrollbarState::new(tags.len())
            .position(list_state.offset())
            .viewport_content_length(area.height as usize);
        frame.render_stateful_widget(Scrollbar::new(ScrollbarOrientation::VerticalRight), area, &mut sb);
    }
}

fn draw_filter_popup(frame: &mut Frame, app: &mut App, idx: usize, area: Rect) {
    let mut state = take_popup!(app, idx, Filter);
    let rect = centered_rect_percent(70, 80, area);
    frame.render_widget(Clear, rect);
    let block = Block::default().borders(Borders::ALL).title("Filter");
    let inner = block.inner(rect);
    frame.render_widget(block, rect);
    let help_text = "Tab: Change focused control | Enter or <Ctrl-m>: Confirm | Esc or <Ctrl-c>: Cancel | <Ctrl-r>: Change Matching Logic | <Space>: Tags Toggle Selected";
    let help_lines = estimate_wrapped_lines(help_text, inner.width.saturating_sub(4).max(1) as usize) as u16;
    let rows = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(1),
            Constraint::Length(3), // matching logic
            Constraint::Length(3), // title
            Constraint::Length(3), // content
            Constraint::Length(3), // priority
            Constraint::Min(0),    // tags
            Constraint::Length(help_lines),
            Constraint::Length(1),
        ])
        .split(inner);
    let col = |r: Rect| -> Rect {
        Layout::default()
            .direction(Direction::Horizontal)
            .constraints([Constraint::Length(3), Constraint::Min(0), Constraint::Length(3)])
            .split(r)[1]
    };
    // Matching logic display.
    let logic_text = match state.logic {
        MatchingLogic::All => "Journals must meet all criteria",
        MatchingLogic::Any => "Journals must meet any of the criteria",
    };
    let logic_block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title("Matching Logic");
    let logic_inner = logic_block.inner(col(rows[1]));
    frame.render_widget(logic_block, col(rows[1]));
    frame.render_widget(Paragraph::new(logic_text).alignment(Alignment::Center), logic_inner);

    let styles = unsafe { &*(&app.styles as *const AppStyles) };
    state.title.render(col(rows[2]), frame.buffer_mut(), "Title", state.focus == 0, false, styles);
    state.content.render(col(rows[3]), frame.buffer_mut(), "Content", state.focus == 1, false, styles);
    let prio_label = match &state.priority_err {
        Some(e) => format!("Priority : {}", e),
        None => "Priority".to_owned(),
    };
    state.priority.render(col(rows[4]), frame.buffer_mut(), &prio_label, state.focus == 2, state.priority_err.is_some(), styles);

    let tags_area = col(rows[5]);
    let tags_block_style = if state.focus == 3 {
        styles.general.input_block_active.to_rat()
    } else {
        Style::default()
    };
    let tags_block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title("Tags")
        .style(tags_block_style);
    let tags_inner = tags_block.inner(tags_area);
    frame.render_widget(tags_block, tags_area);
    draw_checkable_tags_list(frame, styles, &state.tags, &state.selected_tags, &mut state.tags_state, tags_inner, state.focus == 3, true);

    let help = Paragraph::new(help_text).alignment(Alignment::Center).wrap(Wrap { trim: true });
    frame.render_widget(help, rows[6]);
    app.popups[idx] = Popup::Filter(state);
}

fn draw_sort_popup(frame: &mut Frame, app: &mut App, idx: usize, area: Rect) {
    let mut state = take_popup!(app, idx, Sort);
    let rect = centered_rect_percent(70, 80, area);
    frame.render_widget(Clear, rect);
    let block = Block::default().borders(Borders::ALL).title("Sort");
    let inner = block.inner(rect);
    frame.render_widget(block, rect);
    let help_text = if state.focus_applied {
        "Tab: Change focused control | Enter or <Ctrl-m>: Confirm | Esc or <Ctrl-c>: Cancel |<o>: Change Sort Order | <Space>: Move criteria to other list |<j/k> or <up/down> cycle between criteria | <Ctrl-j/k> or <Ctrl-Up/Down> Move criteria up/down | <Ctrl-d> Load default"
    } else {
        "Tab: Change focused control | Enter or <Ctrl-m>: Confirm | Esc or <Ctrl-c>: Cancel |<o>: Change Sort Order | <Space>: Move criteria to other list |<j/k> or <up/down> cycle between criteria | <Ctrl-d> Load default"
    };
    let help_width = inner.width.saturating_sub(4).max(1) as usize;
    let help_lines = estimate_wrapped_lines(help_text, help_width) as u16;
    let list_h = inner
        .height
        .saturating_sub(1 + 3 + help_lines + 1)
        / 2;
    let rows = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(1),
            Constraint::Length(3),
            Constraint::Length(list_h),
            Constraint::Min(0),
            Constraint::Length(help_lines),
            Constraint::Length(1),
        ])
        .split(inner);
    let col = |r: Rect| -> Rect {
        Layout::default()
            .direction(Direction::Horizontal)
            .constraints([Constraint::Length(3), Constraint::Min(0), Constraint::Length(3)])
            .split(r)[1]
    };
    let order_block = Block::default().borders(Borders::ALL).title("Sort Order");
    let order_inner = order_block.inner(col(rows[1]));
    frame.render_widget(order_block, col(rows[1]));
    let order_text = match state.order {
        SortOrder::Ascending => "Ascending",
        SortOrder::Descending => "Descending",
    };
    frame.render_widget(Paragraph::new(order_text).alignment(Alignment::Center), order_inner);

    draw_criteria_list(frame, &app.styles, "Available Criteria", &state.available, &mut state.available_state, col(rows[2]), !state.focus_applied);
    draw_criteria_list(frame, &app.styles, "Applied Criteria", &state.applied, &mut state.applied_state, col(rows[3]), state.focus_applied);

    let help = Paragraph::new(help_text).alignment(Alignment::Center).wrap(Wrap { trim: true });
    frame.render_widget(help, rows[4]);
    app.popups[idx] = Popup::Sort(state);
}

fn draw_criteria_list(
    frame: &mut Frame,
    styles: &AppStyles,
    title: &str,
    items: &[super::SortCriterion],
    list_state: &mut ListState,
    area: Rect,
    active: bool,
) {
    let block_style = if active {
        styles.general.input_block_active.to_rat()
    } else {
        Style::default()
    };
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title(title.to_owned())
        .style(block_style);
    let inner = block.inner(area);
    frame.render_widget(block, area);
    let list_items: Vec<ListItem> = items.iter().map(|c| ListItem::new(c.name())).collect();
    let highlight = if active {
        styles.general.list_highlight_active.to_rat()
    } else {
        styles.general.list_highlight_inactive.to_rat()
    };
    let list = List::new(list_items)
        .highlight_style(highlight)
        .highlight_symbol(">> ")
        .highlight_spacing(ratatui::widgets::HighlightSpacing::Always);
    frame.render_stateful_widget(list, inner, list_state);
}

fn estimate_wrapped_lines(text: &str, width: usize) -> usize {
    // Height estimate used by the popups: text length / width + 1 line,
    // matching the reference's help paragraph sizing closely enough.
    let h = crate::app::ui::wrapped_line_count(text, width);
    h.max(1)
}

pub fn wrapped_line_count(text: &str, width: usize) -> usize {
    if width == 0 { return 1; }
    wrap_text(text, width).len()
}

fn draw_fuzzy_popup(frame: &mut Frame, app: &mut App, idx: usize, area: Rect) {
    let mut state = take_popup!(app, idx, Fuzzy);
    let rect = centered_rect_percent(60, 60, area);
    frame.render_widget(Clear, rect);
    let block = Block::default()
        .borders(Borders::ALL)
        .border_type(BorderType::Rounded)
        .title("Fuzzy Find");
    let inner = block.inner(rect);
    frame.render_widget(block, rect);
    let rows = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(1),
            Constraint::Length(3),
            Constraint::Min(0),
            Constraint::Length(2),
            Constraint::Length(1),
        ])
        .split(inner);
    let col = |r: Rect| -> Rect {
        Layout::default()
            .direction(Direction::Horizontal)
            .constraints([Constraint::Length(1), Constraint::Min(0), Constraint::Length(1)])
            .split(r)[1]
    };
    let styles = unsafe { &*(&app.styles as *const AppStyles) };
    state.query.render(col(rows[1]), frame.buffer_mut(), "Search Query", true, false, styles);

    let entries_area = col(rows[2]);
    let entries_block = Block::default()
        .borders(Borders::ALL)
        .title(format!("Entries: {}", state.results.len()));
    let entries_inner = entries_block.inner(entries_area);
    frame.render_widget(entries_block, entries_area);
    let items: Vec<ListItem> = state
        .results
        .iter()
        .map(|r| {
            let spans: Vec<Span> = r
                .title
                .chars()
                .enumerate()
                .map(|(i, ch)| {
                    if r.indices.contains(&i) {
                        Span::styled(
                            ch.to_string(),
                            Style::default().fg(Color::LightBlue).add_modifier(Modifier::BOLD),
                        )
                    } else {
                        Span::raw(ch.to_string())
                    }
                })
                .collect();
            ListItem::new(Line::from(spans))
        })
        .collect();
    let highlight = styles.general.list_highlight_active.to_rat();
    let list = List::new(items)
        .highlight_style(highlight)
        .highlight_symbol(">> ")
        .highlight_spacing(ratatui::widgets::HighlightSpacing::Always);
    frame.render_stateful_widget(list, entries_inner, &mut state.list_state);

    let help_text = "Esc, Enter, <Ctrl-m>, <Ctrl-c>: Close | Up, Down, <Ctrl-n>, <Ctrl-p>: cycle through filtered list";
    let help = Paragraph::new(help_text).alignment(Alignment::Center).wrap(Wrap { trim: true });
    frame.render_widget(help, rows[3]);
    app.popups[idx] = Popup::Fuzzy(state);
}

fn draw_export_popup(frame: &mut Frame, app: &mut App, idx: usize, area: Rect) {
    let mut state = take_popup!(app, idx, Export);
    let rect = centered_rect_exact(70, 11, area);
    frame.render_widget(Clear, rect);
    let block = Block::default().borders(Borders::ALL).title(state.title_label.clone());
    let inner = block.inner(rect);
    frame.render_widget(block, rect);
    let rows = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(3),
            Constraint::Length(1),
            Constraint::Length(1),
            Constraint::Length(1),
        ])
        .split(inner);
    let col = |r: Rect| -> Rect {
        Layout::default()
            .direction(Direction::Horizontal)
            .constraints([Constraint::Length(3), Constraint::Min(0), Constraint::Length(3)])
            .split(r)[1]
    };
    frame.render_widget(Paragraph::new(state.descriptor.clone()), col(rows[1]));
    let styles = unsafe { &*(&app.styles as *const AppStyles) };
    state.path.render(col(rows[3]), frame.buffer_mut(), "Path", true, false, styles);
    let help = Paragraph::new("Enter: confirm | Esc or <Ctrl-c>: Cancel")
        .alignment(Alignment::Center)
        .wrap(Wrap { trim: true });
    frame.render_widget(help, rows[5]);
    app.popups[idx] = Popup::Export(state);
}

fn draw_msgbox(frame: &mut Frame, state: &MsgBoxState, styles: &AppStyles, area: Rect) {
    let rect = centered_rect_exact(55, 8, area);
    frame.render_widget(Clear, rect);
    let color = match state.kind {
        MsgBoxKind::Error => styles.msgbox.error.0,
        MsgBoxKind::Warning => styles.msgbox.warning.0,
        MsgBoxKind::Info => styles.msgbox.info.0,
        MsgBoxKind::Question | MsgBoxKind::QuestionCancel => styles.msgbox.question.0,
    };
    let style = Style::default().fg(color);
    let title = state.title();
    let mut block = Block::default().borders(Borders::ALL).style(style);
    if !title.is_empty() {
        block = block.title(title);
    }
    let inner = block.inner(rect);
    frame.render_widget(block, rect);
    // Fixed layout: blank, up to 3 wrapped message lines, buttons, blank.
    let rows = Layout::default()
        .direction(Direction::Vertical)
        .constraints([
            Constraint::Length(1),
            Constraint::Length(3),
            Constraint::Length(1),
            Constraint::Length(1),
        ])
        .split(inner);
    let msg = Paragraph::new(state.message.clone())
        .style(style)
        .alignment(Alignment::Center)
        .wrap(Wrap { trim: true });
    frame.render_widget(msg, rows[1]);
    let buttons = Paragraph::new(state.buttons())
        .style(style)
        .alignment(Alignment::Center);
    frame.render_widget(buttons, rows[2]);
}

