p="src/app/ui.rs"; t=open(p).read()
start=t.index("pub fn wrap_text(text: &str, width: usize) -> Vec<String> {")
end=t.index("fn split_words(text: &str) -> Vec<String> {")
new='''pub fn wrap_text(text: &str, width: usize) -> Vec<String> {
    if width == 0 {
        return vec![text.to_owned()];
    }
    if text.is_empty() {
        return vec![String::new()];
    }
    // Wrap using line-break opportunities after spaces, hyphens and
    // slashes (a close approximation of the unicode line-break
    // opportunities ratatui's WordWrapper uses).  A fragment's measured
    // width includes its trailing space, matching the reference wrap at
    // exact-fit boundaries.
    let mut fragments: Vec<String> = Vec::new();
    let mut cur = String::new();
    for ch in text.chars() {
        cur.push(ch);
        if ch.is_whitespace() || ch == '-' || ch == '/' {
            fragments.push(std::mem::take(&mut cur));
        }
    }
    if !cur.is_empty() {
        fragments.push(cur);
    }

    let mut lines: Vec<String> = Vec::new();
    let mut line = String::new();
    let mut line_w = 0usize; // measured width including separators
    for frag in fragments {
        let frag_w = str_width(&frag);
        let frag_trimmed_w = str_width(frag.trim_end());
        if line_w > 0 && line_w + frag_w > width && frag_trimmed_w > 0 {
            // Cannot fit the whole fragment: if the fragment is a word
            // fragment, a piece of it may still fill this line when it
            // contains an internal break opportunity handled above; here
            // move to the next line.
            lines.push(line.trim_end().to_owned());
            line = String::new();
            line_w = 0;
        }
        if frag_w > width && line_w == 0 {
            // Long fragment: split by characters.
            let mut chunk = String::new();
            let mut chunk_w = 0usize;
            for ch in frag.chars() {
                let cw = UnicodeWidthChar::width(ch).unwrap_or(0);
                if chunk_w + cw > width && !chunk.is_empty() {
                    lines.push(chunk.trim_end().to_owned());
                    chunk = String::new();
                    chunk_w = 0;
                }
                chunk.push(ch);
                chunk_w += cw;
            }
            line = chunk;
            line_w = chunk_w;
        } else {
            line.push_str(&frag);
            line_w += frag_w;
        }
    }
    if !line.trim_end().is_empty() || lines.is_empty() {
        lines.push(line.trim_end().to_owned());
    }
    if lines.is_empty() {
        lines.push(String::new());
    }
    lines
}

