import subprocess, tempfile, os, time, sys, sqlite3
sys.path.insert(0,"/tmp")

def run_tmux(binary, setup):
    # setup(tmp) -> (cfgdir, home, backendflag args list, extra args, files_to_read dict)
    tmp=tempfile.mkdtemp(prefix="cmp_")
    cfg=os.path.join(tmp,"cfg"); os.mkdir(cfg); home=os.path.join(tmp,"home"); os.mkdir(home)
    args, files, actions = setup(tmp,cfg,home)
    subprocess.run(["tmux","kill-session","-t","tjcmp"],capture_output=True)
    cmd=f"HOME={home} TERM=xterm-256color {binary} -c {cfg} " + " ".join(args)
    subprocess.run(["tmux","new-session","-d","-s","tjcmp","-x","120","-y","40",cmd])
    time.sleep(0.9)
    panes=[]
    def pane(): return subprocess.run(["tmux","capture-pane","-t","tjcmp","-p"],capture_output=True,text=True).stdout
    panes.append(pane())
    for act in actions:
        if act[0]=="send": subprocess.run(["tmux","send-keys","-t","tjcmp",act[1]])
        elif act[0]=="text": subprocess.run(["tmux","send-keys","-t","tjcmp","-l",act[1]])
        time.sleep(0.45); panes.append(pane())
    outfiles={}
    for name,path in files.items():
        if os.path.exists(path):
            if name.endswith("dbdump"):
                con=sqlite3.connect(path); dump=[]
                for tbl in ["entries","tags","_sqlx_migrations"]:
                    try:
                        rows=con.execute(f"select * from {tbl}").fetchall()
                        if tbl=="_sqlx_migrations": rows=[(r[0],r[1],r[3],r[4].hex() if isinstance(r[4],bytes) else r[4]) for r in rows]
                        dump.append((tbl,rows))
                    except Exception as e: dump.append((tbl,str(e)))
                schema=con.execute("select type,name,sql from sqlite_master order by name").fetchall()
                outfiles[name]=repr((schema,dump))
            else:
                outfiles[name]=open(path,"rb").read().decode(errors="replace")
        else: outfiles[name]=None
    subprocess.run(["tmux","kill-session","-t","tjcmp"],capture_output=True)
    def norm(s): return s.replace(tmp,"<TMP>") if isinstance(s,str) else s
    return [norm(p) for p in panes], {k:(norm(v) if v else v) for k,v in outfiles.items()}

def compare(label, setup):
    p1,f1=run_tmux("/workspace/executable",setup)
    p2,f2=run_tmux("/tmp/minebin/executable",setup)
    ok=True
    for i,(a,b) in enumerate(zip(p1,p2)):
        if a!=b:
            ok=False; print(f"\n{label} DIFF step{i}")
            import difflib
            for line in list(difflib.unified_diff(a.splitlines(),b.splitlines(),fromfile="ref",tofile="mine",lineterm=""))[:100]: print(line)
    if f1!=f2:
        ok=False; print(f"\n{label} FILES DIFF\nref={f1}\nmine={f2}")
    print(label,"OK" if ok else "DIFF")
