        let path = PathBuf::from(state.path.text());
        let write_result: Result<()> = (|| {
            if let Some(parent) = path.parent() {
                if !parent.as_os_str().is_empty() {
                    std::fs::create_dir_all(parent)?;
                }
            }
            if state.multi {
                let drafts: Vec<EntryDraft> = state
                    .ids
                    .iter()
                    .filter_map(|id| self.entries.iter().find(|e| e.id == *id))
                    .map(EntryDraft::from)
                    .collect();
                let dto = EntriesDTO::new(drafts);
                let text = serde_json::to_string_pretty(&dto)?;
                std::fs::write(&path, text)?;
            } else {
                let entry = state
                    .ids
                    .first()
                    .and_then(|id| self.entries.iter().find(|e| e.id == *id));
                let content = entry.map(|e| e.content.clone()).unwrap_or_default();
                std::fs::write(&path, content)?;
            }
            Ok(())
        })();
        match write_result {
            Ok(()) => Ok(path),
            Err(err) => Err(format!(
                "Error while exporting journal(s). Err: {}",
                root_io_message(&err)
            )),
        }
    }

