    fn register_history(&mut self, record: HistoryRecord) {
        self.register_history_to(record, false);
        self.redo_stack.clear();
    }

    fn register_history_to(&mut self, record: HistoryRecord, to_redo: bool) {
        match &record {
            HistoryRecord::Add(entry) => {
                log::trace!(target: "tjournal::app::history", "History Register Add: Entry: {:?}", entry);
            }
            HistoryRecord::Remove(entry) => {
                log::trace!(target: "tjournal::app::history", "History Register Remove: Deleted Entry: {:?}", entry);
            }
            HistoryRecord::ChangeAttribute(before) => {
                log::trace!(target: "tjournal::app::history", "History Register Change attribute: Entry before: {:?}", before);
            }
            HistoryRecord::ChangeContent { id, .. } => {
                log::trace!(target: "tjournal::app::history", "History Register Change content: Entry ID: {}", id);
            }
        }
        let limit = self.settings.history_limit;
        if limit == 0 {
            return;
        }
        let stack = if to_redo { &mut self.redo_stack } else { &mut self.undo_stack };
        stack.push(record);
        while stack.len() > limit {
            stack.remove(0);
        }
    }

    fn perform_add_entry(&mut self, draft: EntryDraft) -> Result<Entry> {
        log::trace!(target: "tjournal::app", "Adding entry");
        let created = self.provider.add_entry(draft)?;
        self.entries.push(created.clone());
        self.refresh_displayed(Some(created.id));
        Ok(created)
    }

    fn perform_delete_entry(&mut self, id: u32) -> Result<Option<Entry>> {
        let Some(entry) = self.entries.iter().find(|e| e.id == id).cloned() else {
            return Ok(None);
        };
        log::trace!(target: "tjournal::app", "Deleting entry with id: {}", id);
        let was_current = self.current_id == Some(id);
        let old_list_index = self.list_state.selected().unwrap_or(0);
        let keep_id = self.current_id;
        self.provider.remove_entry(id)?;
        self.entries.retain(|e| e.id != id);
        self.multi_selected.remove(&id);
        if was_current {
            // Select whatever now sits at the old list index.
            self.current_id = None;
            self.refresh_displayed(None);
            if !self.displayed.is_empty() {
                self.set_selection_index(old_list_index.min(self.displayed.len() - 1), true);
            }
        } else {
            self.refresh_displayed(keep_id);
        }
        Ok(Some(entry))
    }

    fn perform_update_entry(&mut self, updated: &Entry) -> Result<()> {
        log::trace!(target: "tjournal::app", "Updating entry");
        self.provider.update_entry(updated)?;
        if let Some(slot) = self.entries.iter_mut().find(|e| e.id == updated.id) {
            *slot = updated.clone();
        }
        let keep = self.current_id;
        self.refresh_displayed(keep);
        Ok(())
    }

    fn perform_update_content(&mut self, id: u32, new_content: String) -> Result<Option<String>> {
        let Some(current) = self.entries.iter().find(|e| e.id == id).cloned() else {
            return Ok(None);
        };
        if current.content == new_content {
            return Ok(Some(current.content));
        }
        log::trace!(target: "tjournal::app", "Updating entry content");
        let old_content = current.content.clone();
        let mut updated = current;
        updated.content = new_content;
        self.provider.update_entry(&updated)?;
        if let Some(slot) = self.entries.iter_mut().find(|e| e.id == id) {
            *slot = updated;
        }
        let keep = self.current_id;
        self.refresh_displayed(keep);
        Ok(Some(old_content))
    }

    fn apply_history_record(&mut self, record: HistoryRecord, to_redo: bool) -> Result<()> {
        match record {
            HistoryRecord::Add(entry) => {
                log::trace!(target: "tjournal::app", "History Apply: Add Entry: ID {}", entry.id);
                if let Some(deleted) = self.perform_delete_entry(entry.id)? {
                    self.register_history_to(HistoryRecord::Remove(deleted), to_redo);
                }
            }
            HistoryRecord::Remove(entry) => {
                log::trace!(target: "tjournal::app", "History Apply: Remove Entry: {:?}", entry);
                let created = self.perform_add_entry(EntryDraft::from(&entry))?;
                self.register_history_to(HistoryRecord::Add(created), to_redo);
            }
            HistoryRecord::ChangeAttribute(before) => {
                log::trace!(
                    target: "tjournal::app",
                    "History Apply: Change Attributes: EntryAttributes {{ id: {}, date: {}, title: {:?}, tags: {:?}, priority: {:?} }}",
                    before.id,
                    before.date,
                    before.title,
                    before.tags,
                    before.priority
                );
                let Some(current) = self.entries.iter().find(|e| e.id == before.id).cloned() else {
                    return Ok(());
                };
                let inverse = current.clone();
                let mut updated = current;
                updated.date = before.date;
                updated.title = before.title.clone();
                updated.tags = before.tags.clone();
                updated.priority = before.priority;
                self.perform_update_entry(&updated)?;
                self.register_history_to(HistoryRecord::ChangeAttribute(inverse), to_redo);
            }
            HistoryRecord::ChangeContent { id, content } => {
                log::trace!(target: "tjournal::app", "History Apply: Change Content: ID: {}", id);
                if let Some(old) = self.perform_update_content(id, content)? {
                    self.register_history_to(
                        HistoryRecord::ChangeContent { id, content: old },
                        to_redo,
                    );
                }
            }
        }
        Ok(())
    }

    fn undo(&mut self) {
        if let Some(record) = self.undo_stack.pop() {
            if let Err(err) = self.apply_history_record(record, true) {
                self.show_error(format!("{}", err));
            }
        }
    }
    fn redo(&mut self) {
        if let Some(record) = self.redo_stack.pop() {
            if let Err(err) = self.apply_history_record(record, false) {
                self.show_error(format!("{}", err));
            }
        }
    }

    // ---------- persistence helpers ----------
    fn save_current_content(&mut self) -> bool {
        let Some(entry) = self.current_entry().cloned() else { return true };
        let new_content = self.editor.text();
        if new_content == entry.content {
            return true;
        }
        match self.perform_update_content(entry.id, new_content) {
            Ok(old) => {
                if let Some(old_content) = old {
                    self.register_history(HistoryRecord::ChangeContent {
                        id: entry.id,
                        content: old_content,
                    });
                }
                true
            }
            Err(err) => {
                self.show_error(format!("{}", err));
                false
            }
        }
    }

