use std::path::PathBuf;

/// Retrieve `core.editor` from the git configuration files that
/// `git2::Config::open_default` would consult (system, XDG and global).
/// Returns the configured editor string (which may be empty) on success.
pub fn git_core_editor() -> Option<String> {
    let mut paths: Vec<PathBuf> = Vec::new();

    if std::env::var_os("GIT_CONFIG_NOSYSTEM").is_none() {
        if let Some(sys) = std::env::var_os("GIT_CONFIG_SYSTEM") {
            if !sys.is_empty() {
                paths.push(PathBuf::from(sys));
            }
        } else {
            paths.push(PathBuf::from("/etc/gitconfig"));
        }
    }

    if let Some(global) = std::env::var_os("GIT_CONFIG_GLOBAL") {
        if !global.is_empty() {
            for part in std::env::split_paths(&global) {
                paths.push(part);
            }
        }
    } else {
        if let Some(config_dir) = dirs::config_dir() {
            paths.push(config_dir.join("git").join("config"));
        }
        if let Some(home) = dirs::home_dir() {
            paths.push(home.join(".gitconfig"));
        }
    }

    let mut found: Option<String> = None;
    let mut any_error = false;
    for path in &paths {
        if !path.exists() {
            continue;
        }
        match std::fs::read_to_string(path) {
            Ok(content) => match parse_core_editor(&content) {
                Ok(value) => {
                    if let Some(v) = value {
                        found = Some(v);
                    }
                }
                Err(()) => {
                    any_error = true;
                }
            },
            Err(_) => {
                any_error = true;
            }
        }
    }
    if any_error && found.is_none() {
        log::trace!(
            target: "tjournal::app::external_editor",
            "Failed to retrieve git editor, Err: config value 'core.editor' was not found; class=Config (7); code=NotFound (-3)"
        );
        return None;
    }
    if found.is_none() {
        log::trace!(
            target: "tjournal::app::external_editor",
            "Failed to retrieve git editor, Err: config value 'core.editor' was not found; class=Config (7); code=NotFound (-3)"
        );
    }
    found
}

fn parse_core_editor(content: &str) -> Result<Option<String>, ()> {
    let mut in_core = false;
    let mut result: Option<String> = None;
    for raw_line in content.lines() {
        let line = raw_line.trim();
        if line.is_empty() || line.starts_with('#') || line.starts_with(';') {
            continue;
        }
        if line.starts_with('[') {
            let Some(end) = line.find(']') else { return Err(()) };
            let header = line[1..end].trim();
            let section = header.split_whitespace().next().unwrap_or("");
            in_core = section.eq_ignore_ascii_case("core");
            continue;
        }
        if !in_core {
            continue;
        }
        // key = value / key <eol> (boolean) forms
        let (key, value) = match line.split_once('=') {
            Some((k, v)) => (k.trim(), Some(parse_git_value(v.trim()))),
            None => (line.trim(), None),
        };
        if key.eq_ignore_ascii_case("editor") {
            result = Some(value.unwrap_or_else(|| "true".to_owned()));
        }
    }
    Ok(result)
}

fn parse_git_value(raw: &str) -> String {
    if raw.is_empty() {
        return String::new();
    }
    let mut out = String::new();
    let mut chars = raw.chars().peekable();
    let mut in_quotes = false;
    while let Some(ch) = chars.next() {
        match ch {
            '"' => in_quotes = !in_quotes,
            '\\' => {
                if let Some(next) = chars.next() {
                    match next {
                        'n' => out.push('\n'),
                        't' => out.push('\t'),
                        'b' => out.push('\u{8}'),
                        other => out.push(other),
                    }
                }
            }
            '#' | ';' if !in_quotes => break,
            other => out.push(other),
        }
    }
    out.trim().to_owned()
}
