                self.push_undo();
                self.row += 1;
                self.lines.insert(self.row, String::new());
                self.col = 0;
                self.mode = EditorMode::Edit;
            }
            'O' if !visual => {
                self.push_undo();
                self.lines.insert(self.row, String::new());
                self.col = 0;
                self.mode = EditorMode::Edit;
            }'''
